/* 令和4年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r04.committeeSessions.push(...[{"id":"r04-20220222-5","meetingId":"r04-cm02","date":"2022年2月22日","dateIso":"2022-02-22","committee":"総務委員会","time":"午前１０時００分～午前１１時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を49件整理しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げたとおり、取り上げる順番を変更し、まず、(8)第３１号議案 一本橋保育園・児童センター改築工事請負契約","agenda":"冒頭に申し上げたとおり、取り上げる順番を変更し、まず、(8)第３１号議案 一本橋保育園・児童センター改築工事請負契約","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"園庭等には別に影響はないということでしょうか。その辺をお願いいたします。","respondent":"初貝保育教育運営担当課長","answer":"今委員からご質問がございました園庭に関しまして、影響という意味では、もちろん敷地内で工事をしますので、そこも一体的に進めているです。そのような意味では、園庭自体は引き続きそのまま既存の施設、以降建て替えの施設にも園庭は備え付けるというような予定です。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"どうもありがとうあります。それで、その他の保育園の施設、設備に関する変更などについても、同様と理解してよろしいのか尋ねました。","respondent":"小林施設整備課長","answer":"もちろん新しい施設ですので、既存の設備よりも新しい機器が、時代の進化、進展に伴って開発されておりますので、新しい機器、新しい設備で保育施設、整備していく予定です。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"ただ、人工芝化するのかどうかについて伺いたいと思います。避難ができるのかという部分を教えていただきたいということと、保育園と児童センター両方が使えるのかという部分を教えてほしいと求めました。","respondent":"小林施設整備課長、廣田子ども育成課長","answer":"二方向避難の考え方ですが、２階平面図を見ていただくと分かるかと思うのですけれども、２つ並んでいるかと思います。もちろん３階のほう、１・２階にも児童センターの方がエレベーターを使ったりとか… 児童厚生施設の建物に設置するべき、図書室を設けなければならないというふうになっている、その集会室に当たります。エレベーターがつくことになりますので、より使いやすくなろうかと思っています。","id":"exchange-003"},{"speaker":"田中委員","kind":"確認","question":"何というのですか、何というのですか、安全性の確保の部分でどういった配慮がされているのかということを確認できたらと思います。保育課の方もいらっしゃるので少し伺いたいのですが、考え方として、区として人工芝化をこれからも進めていくのかという確認をしたいなと思います。","respondent":"小林施設整備課長、初貝保育教育運営担当課長","answer":"私のほうから屋上広場の安全性、仕上材の安全性についてのご質問にお答えいたします。それらにつきましては、それらの劣化状況等を判断しながら、しかるべきタイミングで改修をするという形になろうかと思ってあります。今後の考え方ですけれども、今改築したり新設している保育園に関しましては、基本的には人工芝を採用しています。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"そういったことをきちんと考えていただきたいということと、人工芝にしていくのかということも議論していただきたいということと、とにかくそのリスクもあるということをきちんと周知していただければという意見でとどめます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"須貝委員","kind":"質問","question":"それから通行の妨げ、そこに住まわれている方の、そのようなところは大丈夫ですか。もう１点は、大まかに大体どれぐらいの金額が割り振られているのか、その辺についても説明を求めました。","respondent":"東野経理課長、小林施設整備課長","answer":"応札いただいた４社ですが、委員ご指摘のとおり、約２００万円、３００万円近くのところに３社が応札しているような状況です。こちらにつきましては、予定価格を事前公表しているということもありますし… あるいは車の大きさの選定等については、安全にけがのないように、通行人の方にご迷惑をかけないように行っていきたいというふうに考えてあります。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"恐らく解体工事費も相当かかる場所かなというように推察したのだけれども、建設もそうですよね。恐らく２トン車が入ったら、その辺の安全性とご配慮だけは、くれぐれも注意してやってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"小芝委員","kind":"質問・要望","question":"須貝委員の関連で質問させていただきたいのですけれども、また学生もよく通りますので、その辺りご配慮していただきたいなと思います。すぐそばに品川大井二郵便局もありますので、その辺り、時間帯等もご配慮してほしいと求めましたが、お考えがありましたら説明を求めました。","respondent":"小林施設整備課長","answer":"朝の通行時間帯は、非常に多くの方が大井町のほうから学校に行かれたり、通勤の方もいらっしゃるということはしっかり認識しています。すぐに説明会を開始いたしまして、引き続き区としましても、安全に工事が進められるようにしてまいりたいというふうに考えてあります。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問","question":"老朽化に伴う建て替え工事ですから、賛成ですけれども、運営に当たっては民営化を進めるべきではないということは述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"賛成します。ただ、保護者や子どもにもきちんと意見を求めてほしいということを求めて賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"第１６号議案 品川区庁舎整備基金条例","agenda":"第１６号議案 品川区庁舎整備基金条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"新庁舎の建設費、第二庁舎の改修費等書いてあるのですが、要するに新庁舎の建設費がほとんどというような理解の仕方でよろしいのでしょうか。いかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"新しくつくる条例です。こちらは新庁舎整備を中心に、積立てを行いたいと考えております。","id":"exchange-011"},{"speaker":"田中委員","kind":"確認","question":"今回のこの基金条例でどこまで決定してしまうのかというところを確認したいのですけれども、その根拠をまず伺いたいということと、その都度きちんと審査をされるということで間違いないのかということを確認させてください。","respondent":"黒田財政課長","answer":"基金の目標積立額を１２０億円としておりまして、基本構想の中では概算で４００億円と出ておりまして、１２０億円を基金として用意するです。補正予算が３０億円で、以後につきましては、そのたび予算のほうに計上して審査いただくという形になろうかと思います。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問","question":"予算は分かりました。３０億円にした、もう１回、そこを教えてほしいと求めました。","respondent":"黒田財政課長","answer":"そこから起債を検討しますので、庁舎ですと７５％ということですから、そこの部分について基金として用意する。令和６年度までに１２０億円の積立てを見据えてということで、１２０億円ありますと、１２０億円を目標に積み立てていくというものです。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"当初の積立額が３０億円の根拠を伺ったのですけれども、それは上下することもあるということを確認させていただきたいのですけれども、お願いします。","respondent":"黒田財政課長","answer":"令和６年度までですか、毎年度３０億円を積み立てる、それは状況として変更はあり得るというふうに考えてあります。","id":"exchange-014"},{"speaker":"田中委員","kind":"確認","question":"もう１回の確認になるのですが、その都度きちんと議会には諮られて決定していくということでよろしかったか尋ねました。","respondent":"黒田財政課長","answer":"積立てするためには歳出予算が必要ですし、歳出予算を組むためには歳入予算が必要ですので、予算編成の中で行っていくというものです。","id":"exchange-015"},{"speaker":"おくの委員","kind":"質問","question":"今の関連で、建設費が４００億円という、アバウトに４００億円あって、そのうちの３００億円を起債で調達できるだろうと。残りの１００億円について基金をつくっておこうというようなイメージでよろしいのか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"おくの委員","kind":"質問","question":"７５％とおっしゃったので、そのようなイメージなのかなということをお伺いしています。","respondent":"黒田財政課長","answer":"ちょっと金額は申し上げられませんけれども、基本的に起債をしない部分については資金を要しますので、その分を１２０億円を目標にしています。","id":"exchange-017"},{"speaker":"おくの委員","kind":"質問","question":"１５年もつ庁舎を壊すことになりますし、ＪＲ開発に便宜を図るということでありますし、また、区民にとって不便な超高層の庁舎という計画ですから、そのための基金設置ということで基金設置には反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-03","title":"請願・陳情審査","agenda":"請願・陳情審査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"その辺の基準はどのようなものなのかということをお伺いしたいということと、それから、変更金額の上限を決めていらっしゃる区が結構あると。あるいは最高どのぐらいの金額だったのか、この直近３年間で、ということを教えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問","question":"今回請願が出ているのは１０％以内ということですけれども、１０％以内に収まるものの中ではどのぐらいの額があったのでしょうか。よろしければ教えていただければと思うのですが、いかがでしょう。","respondent":"東野経理課長","answer":"今説明させていただきました契約金額の１０％以内に入っているものにつきましては、資料の契約金額変更あり、それぞれ７件、１件、３件とありますが、１２件中１１件が１０％以内に収まっているものです。","id":"exchange-020"},{"speaker":"田中委員","kind":"質問","question":"質問ですけれども、私たちもこの１０％以内のところが少し気になっていて、どちらが妥当だと考えていますか。妥当性について伺えればと思うのですけれども。","respondent":"渡辺委員長、東野経理課長","answer":"意味は分かりますので。経理課長、妥当にこだわらずお答えください。 区としては、これまで議会の再度の承認を求めてまいりましたので、妥当かどうかという判断はできかねるものです。","id":"exchange-021"},{"speaker":"田中委員","kind":"質問","question":"この１０％の案件という請願の申入れですけれども、少し意見として聞きたかったのですが、どうなのでしょうか。ごめんなさい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"たけうち副委員長","kind":"意見","question":"やはりその上で、現実今までも工事がどうしても遅れることで、いろいろな方面に実際影響が出ていたということも記憶にあるわけです。これからどうなるか分かりませんけれども、我々としては全部が全部１０％以内だから、そのような思いがあるということを意見として述べしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"須貝委員","kind":"質問","question":"このように１０％以内云々を専決処分でいきますよということに対して、理解を得られるのか、得てもらえるのですか。やるならばきちんといろいろ根回しというか、理解を得ておかないといけないのかなと少し思ったのですが、それほど考えなくて大丈夫なのか尋ねました。","respondent":"工藤区議会事務局長","answer":"軽易な金額変更につきましては、地方自治法１８０条の専決処分を使うことも可能だろうという判例も出ておりますので、規定に入れることになろうかと考えております。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問","question":"ですから、確かに一律１０％であるとか、それをしっかりとやっていただいた上でのことなのかなと。採択です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"おくの委員","kind":"意見","question":"ただし、やはり１０％以内であれば何でもオーケーというわけには、当然のことながらいかないかなとも思っております。そこには客観的な理由が当然必要なので、趣旨採択かなということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"田中委員","kind":"質問","question":"本日結論を出すで、採択でお願いします。この請願の趣旨には賛同しますので、理解するところもあるので、採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"おくの委員","kind":"質問・要望","question":"委員長、よろしいですか。私以外採択とされていますし、要するに専決処分が可能となるようご改善いただきたいというところにいろいろ含むもの、私も採択ということで結構です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"再度議題に供します。それでは、(1)第１０号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人…","agenda":"再度議題に供します。それでは、(1)第１０号議案 品川区行政手続における特定の個人を識別するための番号の利用等に関する法律に基づく個人番号の利用および特定個人…","exchanges":[{"speaker":"おくの委員","kind":"確認","question":"この改正にはそのような方への配慮があるのかないのか、確認しておきたいと思います。いかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"それぞれの事務につきまして、マイナンバーを申請書に記入しなかったからといって、サービス内容は変わりませんし、手続きの受付も可能になります。","id":"exchange-029"},{"speaker":"おくの委員","kind":"確認","question":"これまでどおりの扱いということで、これまで以上に不利益になるということもないわけですよね。それも確認しておきたいと思います。","respondent":"宮澤情報推進課長","answer":"不利益等は特にございません。","id":"exchange-030"},{"speaker":"田中委員","kind":"確認","question":"どのような経緯から区独自の事務を追加することになったのかということを確認させてください。","respondent":"宮澤情報推進課長","answer":"資料の5)の心身障害者医療費助成事務の説明からします。1)から4)につきましては、この間申請者等の増加等もありますので、併せて追加をして、区民の利便性等の向上を図っていくというものです。","id":"exchange-031"},{"speaker":"田中委員","kind":"確認","question":"先ほどもご説明があったと思うのですけれども、区独自の事務の追加、1)から4)については、転入される方の利便性が上がるということだったと思うのですが、今いる区民の方たちの利便性がどの程度上がるのかということを確認させてください。","respondent":"宮澤情報推進課長","answer":"区民の方につきましては、現在も手続きの際、所得の証明書等につきましては、ご本人の同意を得る形で添付というものは省略されている形ですので、手続きとしては変わらない形になります。","id":"exchange-032"},{"speaker":"田中委員","kind":"意見","question":"生活者ネットワーク、反対します。その情報漏えいリスクが、今回の条例改正でも払拭はできないと感じたため、反対いたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-05","title":"第１２号議案 品川区職員定数条例の一部を改正する条例","agenda":"第１２号議案 品川区職員定数条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"だから、生活福祉課の１人当たりの担当者を減らすために増やさなければいけないのではないかという点に関して、その点いかがでしょうか。ちょっと伺っておきたいと思います。","respondent":"崎村人事課長","answer":"特に感染症対応については、現場の職員に負担がかかっているということは認識をしておるところで、対応してきたところです。職員１人当たりの受持ち世帯というところの目安もありますので、全体的な人員配置の中で検討していきたいというふうに考えております。","id":"exchange-034"},{"speaker":"おくの委員","kind":"質問・要望","question":"その弱点があらわになったというだけのことですから、そのことで、保健師を増やしていくのだというような目で見るようにしてほしいと求めました。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問・要望","question":"要望としては、その点について伺いたいということが１点と、もう１回説明をいただきたいということと。１人では絶対足りないだろうなということを思っていて、この保健師の増５人、増やしていただきたいということを要望したいです。","respondent":"崎村人事課長","answer":"明後日組織改正について詳しくご説明があるかと思いますが、１つ課を設置いたしまして、障害者施策推進課という形でさらに進めていくという部分です。","id":"exchange-036"},{"speaker":"おくの委員","kind":"質問・要望","question":"児童相談所の設置に向けて十分な職員体制を求めますし、保育園の民営化や学校用務の民営化は、やはり進めるべきではないと考えております。そういう意味で、全体としては反対いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-06","title":"第１３号議案 職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例","agenda":"第１３号議案 職員の勤務時間、休日、休暇等に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"その辺の対応をどうお考えになっているのか、あるいはどうやろうとされているのか、その辺のことをお伺いしたいと思います。いかがか尋ねました。","respondent":"崎村人事課長","answer":"不妊治療に要する通院日数というものは、医師の判断や、年次有給休暇等を利用していただいて対応していただくといったことを考えているところです。不妊治療を検討している人の中には、そのような配慮から、この名称についても変更したものというふうに推察しております。","id":"exchange-038"},{"speaker":"おくの委員","kind":"質問・要望","question":"この５日、１０日ということですけれども、何らかの形で今後もやってほしいと求めました。これも希望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"田中委員","kind":"質問・要望","question":"そのアンケートについては全職員にやられたのですかということと、今回の出生サポート休暇の名称についても、その当事者の意見を聞いてほしいかなと。男性も使いやすいものであるように、その当事者の声というものを聞いていただきたいと思うのですが、いかがか尋ねました。","respondent":"崎村人事課長","answer":"国家公務員の方で昨年の１月から２月にかけてアンケート調査を実施いたしまして、それを受けて人事院の勧告の中でも触れられたところです。","id":"exchange-040"},{"speaker":"田中委員","kind":"質問・要望","question":"賛成します。様々意見を聞いていただいて、当事者の方たちが使いやすい制度になるように求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"}]},{"id":"topic-07","title":"第１４号議案 職員の育児休業等に関する条例の一部を改正する条例","agenda":"第１４号議案 職員の育児休業等に関する条例の一部を改正する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"この休業についても残されていると思うのですが、その改善についてご予定というか、お考えはあるのでしょうか。他方で給料のほうは、その休業のほうで残されている正規職員との格差を改めていく予定というか、考えがおありになるか伺っておきたいと思います。","respondent":"崎村人事課長","answer":"育児等と仕事の両立支援といったところで、先ほど説明しました不妊治療休暇の新設ですとか、会計年度任用職員の待遇改善ということで行うところです。国や他団体との均衡等も踏まえながら、適宜このようなタイミングも踏まえて、見直していきたいというふうには考えております。","id":"exchange-042"},{"speaker":"田中委員","kind":"確認","question":"ただ、例えばこの会計年度任用職員の方たちも、１年未満の方でも取れるということが確認できたのでよかったです。そのような呼びかけというか、そのような環境が整ってきているのかどうかということを確認したいのですけれども、いかがか尋ねました。","respondent":"崎村人事課長","answer":"まず職場の理解といいますか、やはり大分醸成されてきたので、取得しやすい環境は整えられてきたのかなというふうに考えているところです。","id":"exchange-043"},{"speaker":"おくの委員","kind":"質問・要望","question":"まだまだ残されている正規職員との格差の改善を求めながらも、一定の待遇の改善がされているものなので賛成いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"}]},{"id":"topic-08","title":"第１５号議案 公益的法人等への職員の派遣等に関する条例の一部を改正する条例","agenda":"第１５号議案 公益的法人等への職員の派遣等に関する条例の一部を改正する条例","exchanges":[{"speaker":"田中委員","kind":"質問","question":"この一般財団法人道路管理センターが新たに派遣先になった目的、先ほど道路管理センターのほうからご依頼があったということですけれども、その目的を伺いたいということと、これまではその派遣がなかったのかというところを伺いたいと思います。","respondent":"崎村人事課長","answer":"昭和６１年に設立されまして、ガス、区が道路管理者としての立場で行う道路管理業務を支援していただいている法人となっております。ですので、今回品川区に派遣を依頼されるのは初めてになっております。","id":"exchange-045"},{"speaker":"須貝委員","kind":"質問","question":"少しお聞きしたいのですが、２３区が輪番制で派遣をしているということですけれども、そこはそこで人を雇えばいいはずですよね。なぜ２３区にそのように派遣依頼をしてくるのか、その辺少し、どのような内容なのか説明を求めました。","respondent":"崎村人事課長","answer":"こちらに派遣する目的、区の管理業務、より使用しやすい効率的なシステムが構築できるというところがまず１つあります。区と道路管理センターとの連絡調整において、事業実施の円滑化・効率化が図られるといったところで職員を派遣しているというものです。","id":"exchange-046"}]},{"id":"topic-09","title":"第１１号議案 品川区長等の損害賠償責任の一部免責に関する条例","agenda":"第１１号議案 品川区長等の損害賠償責任の一部免責に関する条例","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"この点をどのように、バランスといえばバランスですけれども、この点どのようにお考えになっているのかということを１つお伺いしたいと思います。その点もお伺いしたいと思います。","respondent":"古巻総務課長","answer":"そのような内容のものというふうには認識しておりませんで、今までどおりの流れで、そういったものはないというふうに認識をしているところです。","id":"exchange-047"},{"speaker":"田中委員","kind":"質問・要望","question":"職員等の等の中に含まれるものをお知らせいただきたいということと、現在は継続している住民訴訟は存在しないということですけれども、過去にはあったのかなということを、もしあったら教えていただきたいです。","respondent":"古巻総務課長","answer":"教育委員であったり、そういった方々が含まれますので、等というふうにさせていただいているところです。監査請求で不服があったというようなことで、手続き上のそういった形での住民訴訟が何件かあったというふうには認識をしております。","id":"exchange-048"},{"speaker":"須貝委員","kind":"質問","question":"これは誰が判断するのですか。もう裁判で判決が出たから、きちんと司法で決められるのでしょうけれども、この一部免責するというのは誰が決めるのか尋ねました。","respondent":"古巻総務課長","answer":"最終的にはやはり司法判断という形になろうかと思います。何というのでしょう、そうした意味でいうと、裁判所の判断に基づいてということが最終的なよりどころになるのかなというふうに考えます。","id":"exchange-049"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816435?Template=document&Id=2224#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":36226,"voices":233}},{"id":"r04-20220224-6","meetingId":"r04-cm02","date":"2022年2月24日","dateIso":"2022-02-24","committee":"区民委員会","time":"午前１０時００分～午後 ０時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を15件整理しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"その上で、これを機にパラスポーツの拠点となる仮称品川障害者スポーツセンターの整備をぜひとも検討をしていただきたいと考えています。品川障害者スポーツセンターの整備をぜひご検討いただけたらと思っているのですけれども、いかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういったものを東京都に要望するとか、一緒に使えるとするほうが、お互い交ざり合う社会ができるという意味でもいいかと考えています。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"城南地区に障害者施設をという話は前からあったのですけれども、ぜひ品川区内に検討していただけたらと思っています。そういう意味では、パラスポーツへの思い切った支援や、ご検討いただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"横山委員","kind":"確認","question":"幾つか伺っていきます。どういったものを発掘されたのかというのも確認させていただけたらと思います。","respondent":"篠田文化観光課長","answer":"年度ごとに５件から８件ぐらい助成をしてきているということで、この４年間で合計２７件の助成をしてきてあります。コロナの関係で事業が縮小されたようなところもあったのですけれども、助成した団体はそれぞれ工夫しながら取り組んでいただいている状況です。","id":"exchange-003"},{"speaker":"横山委員","kind":"質問・要望","question":"そのあたりもしっかり見ていただいて、やってきたことが活かされていくように持っていっていただきたいと思っているのです。そのあたりのお考えを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"りんかい線に乗って山手線のほうに行ってしまうのではなくて、おもてなしの気持ちを伝えながら、そして区もまたにぎやかになることを今考えています。１つの目標は、そこを目標にというのは、ホッケー協会ともまた相談しながらやっていくところです。","id":"exchange-004"},{"speaker":"横山委員","kind":"質問・要望","question":"今回は本当に残念だったのですけれども、ぜひ様々な機会で活かすチャンスをねらっていってほしいと求めました。要望で終わらせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"どういう形で税金が入っているのか、収支の部分については、いずれ出てくるのでしょうか。その辺についてはいかがか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"コロナ禍で東京都も大会組織委員会のほうも、本来は契約をして実施する予定だったものが中止になったということがたくさんあるわけです。ですので、まだ今は出ていないということになりますけれども、もちろんいずれはきちんと収支報告がされるものであると考えています。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"それは品川区に求めることではないですけれども、したほうがいいですよね。そういうのが出ているわけですから、その辺もいずれ何かの委員会でちゃんと提示してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"西村委員","kind":"質問","question":"「しな助」について伺えればと思います。「しな助」を残していくということで伺いたいのですが、「しな助」にどのようなことを期待するかを伺ったアンケートなどもあったと思うのです。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"は文化スポーツ振興部の中のイベントでやっていただくというのがまず１つ大きなところです。リーグ戦等が行われたときに、そういった機会を捉えながら、だんだんとご自分でも探せるようにしていきたいと思っています。","id":"exchange-008"},{"speaker":"西村委員","kind":"意見","question":"人と人のつながりの温かみを感じる、本当にすばらしい取組だと思っています。品川区独自のボランティア制度として、ボランティアのノウハウを共有していけるような取組に広がっていくといいなと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"くにば委員","kind":"質問","question":"１点だけ「しな助」について追加でお伺いいたします。先ほどお示しした東京都のデータと同様に、どれぐらいの方々が今後品川区の様々なボランティアに参加なさりたいかというデータをお持ちか尋ねました。","respondent":"辻パラリンピック準備課長","answer":"今していることは、六百数人の登録者に対して、継続してやりたいという人に手を挙げていただくということで。そういった情報は、今までも流しておりますので、そういう方で継続する方もいらっしゃるのかなと考えています。","id":"exchange-010"},{"speaker":"くにば委員","kind":"意見","question":"シティキャストに絡めてなのですけれども、最終的にシティキャストでしようとしているボランティア活動の継続という部分で、東京都の行った枠組み、シティキャストとの連携とか、今後何かしシティキャストと関わってシナジーを生み出していくのか、その点を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"シティキャストと直接連携するということはないのですが、よろしかったら登録してくださいということでお話ししています。ダブルでやっている方もいらっしゃいますので、そういった意味では、ご自分で情報を集められるといいのかなと思っています。","id":"exchange-011"},{"speaker":"くにば委員","kind":"質問","question":"「しな助」は実際に１００名程度活動なさったということなのですけれども、それをさらに広げていく母数の増やし方として、シティキャストに告知をしていただく形での連携は可能なのか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"そういった意味では、今のところシティーキャストと連携して、「しな助」の母数を増やすことは考えておりません。「しな助」で培ったボランティアマインドを、今のところはそこまでシティキャストとの連携を強固にというのは考えていないところです。","id":"exchange-012"},{"speaker":"くにば委員","kind":"意見","question":"場所というセグメント、品川区付近に住んでいらっしゃるので品川区のイベントなら参加したいという方々に発信していただけるように、東京都のこの枠組みと連携をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-013"}]},{"id":"topic-02","title":"のその他","agenda":"のその他","exchanges":[{"speaker":"中塚委員","kind":"意見","question":"了解です。もし、委員長のほうで今後の時期の見通しがあれば、お伝えくださればと思いますとの意見を述べました。","respondent":"鈴木（真）委員長","answer":"スケジュールはちょっと正副でも話しをしたのですけれども、次の４月の閉会中でどうかなと考えています。もし、状況によっては、その後の５月にもう一回ありますから、どちらかで必ず審査するよう予定しています。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"確認","question":"確認させてください。バスは２台使うということを想定しているのかということと、あと注意事項で、雨天でも決行をするという考えでよろしいか尋ねました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"バスは大型バス２台の予定です。小雨ぐらいだったら、できるかなと考えています。","id":"exchange-015"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/227651?Template=document&Id=2922#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":17898,"voices":47}},{"id":"r04-20220224-7","meetingId":"r04-cm02","date":"2022年2月24日","dateIso":"2022-02-24","committee":"厚生委員会","time":"午前１０時００分～午後 ２時０７分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"高額介護サービス費の追加支給","agenda":"高額介護サービス費の追加支給","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"いつからいつのことなのか。支給額に不足が生じたということですけれども、計算するべきところを含めていなかったためというのは、そこを伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"今回、国のほうでもその方針を示しておりますので、基本的には過去２年分という数値となっています。本来は、システムで含めていなければいけないものが、仕様によって、それを含めていない仕様になっていたです。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"過去２年分遡れるということですけれども、支給が過少となっていたのは、介護サービスが始まってからずっとということですか。その時期を伺いたいなと思いました。","respondent":"宮尾高齢者福祉課長","answer":"参考までに、２０１７年、平成２９年１月にこちらのシステムを導入したところです。ですので、それ以来、本件に関する改修等は行っていないということが現状としています。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"判明したというのは、利用者から「何か足りないですよ」と来たのか、こちらで分かったのか。どう判明したのか、伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"１２月に入って、全国の各保険者に対して、調査の依頼がありました。それで、あるか、ないかという調査依頼があり、そこで調べましたところ、品川区も該当するということが判明したです。","id":"exchange-003"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"この公費負担医療というのは、医療で訪問看護を受けていた場合も、そこで計算するというシステムなのか、そこの仕組みを教えていただきたいです。それと、医療で訪問看護を受けている方というのはどのような方がいらっしゃるのか、分かったら教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"裏を返せば、訪問看護サービスを使っている方が公費負担の対象にもなっていたです。一部助成、補助される方と、いろいろあるというところまでは情報としてつかんでおります。","id":"exchange-004"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"公費負担医療で介護保険の訪問看護を受けているというのは、どのような意味なのか、どのような方なのか。そこがよく分からないのですけれども、その公費負担医療の対象者という意味を説明を求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"公費負担医療は、ほとんどの人が使っているではないですか。その中で、この９０人というのは、どのような方が漏れたのかがよく分からないのです。","respondent":"宮尾高齢者福祉課長","answer":"公費負担医療というのは、例えば、私たちが普通に風邪を引いて医者にかかるというものではなくて、難病指定を受けていらっしゃる方など、介護保険全体の件数からするとかなり特殊なケースになるです。","id":"exchange-006"},{"speaker":"若林委員","kind":"質問","question":"要するに、このように至った原因は、資料上もそうですけれども、システムが不十分だったのだという理由づけになっているのですが、そういうことでよろしいか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"今回は、国の調査で言いますと、３分の２の保険者に同様の事象が発生しているということが厚生労働省から報告されております。ですので、システムの設計の基に何らかのことがあったのか、これはあくまでも推測ですが、今はそのように分析をしています。","id":"exchange-007"},{"speaker":"若林委員","kind":"確認","question":"モデル的にやるという部分が、汎用的なシステムだから、品川区としては２０１９年度に入札等をやったのでしょう。内容については、簡易な確認だけで、少しマイナスの言い方をすると、区としては、稼働する前に特段の検証はしなかったということになってしまうのか。","respondent":"宮尾高齢者福祉課長","answer":"一方で、やはり一義的には、委員がおっしゃったように、採用する際に、できるところはしっかり検証をやっております。ほかにもこういったことが起きないように、再度、点検の強化を図っているところです。","id":"exchange-008"},{"speaker":"若林委員","kind":"質問","question":"医療もかかってくるということですか。区の対応がどうだったのかという趣旨の問いかけをしたのですけれども、それから、そこら辺の全体像を「そうか」と受け止められるようなお話があれば。","respondent":"宮尾高齢者福祉課長","answer":"国というのは、委員がおっしゃったとおり、厚生労働省になります。それから、国民健康保険の支払基金の事務局が全国を一手に扱っている関係があって、今回も国民健康保険中央会というところが登場してきているです。","id":"exchange-009"},{"speaker":"若林委員","kind":"質問","question":"あえて区にお聞きしているので、責任の所在というのはあまり突き詰めてもいけませんが、最後にそこだけお願いします。","respondent":"宮尾高齢者福祉課長","answer":"国は、今のところ明確な答え、態度というのは示していない状況です。ある場合には、速やかに正しい状態にしなさいというところまで、今、国としては示しています。","id":"exchange-010"},{"speaker":"高橋（し）委員","kind":"質問","question":"今、いろいろお聞きしたいことはほかの委員の方がお話ししたので１つだけ。想像に過ぎないのですけれども、それは後日で結構ですので、分かり次第教えてほしいと求めました。","respondent":"宮尾高齢者福祉課長","answer":"１つは、システムの中でもとてもシンプルなシステムを組んでいて、被保険者の数もぐっと限られてくる中で気づいた可能性があるです。それ以上の情報につきましては、今の時点では何ともというところです。","id":"exchange-011"}]},{"id":"topic-02","title":"品川区立障害児者総合支援施設併設の訪問看護","agenda":"品川区立障害児者総合支援施設併設の訪問看護","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"体制的には、訪問看護を何人でやられていたのかということ。先ほど、ほかの訪問看護に移行が進んでいるとおっしゃったと思うのですけれども、区内に精神の訪問看護がどれくらいあるのかを伺いたいと思います。","respondent":"築山障害者施策推進担当課長","answer":"人数と体制についてのご質問なのですけれども、１事業所の事業の経営の情報になりますので、詳細についてはお答えできない部分があります。移転先につきましては、品川区内だけではなく、近隣区も含めて移転を完了させたということで聞いております。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問","question":"もうやる人が本当にいないということなのでしょうか。９月まで、クリニックと一緒にできる状況ではないということか尋ねました。","respondent":"築山障害者施策推進担当課長","answer":"理事会で何とか継続できないかということを検討はしたのですけれども、やはり職員の確保が難しいということで、今回の結論に至ったです。各病院から派遣をして対応できないかということも検討したということなのですけれども、実施が困難だということで、今回。","id":"exchange-013"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"実態がよく分かっていないのですけれども、精神の患者に特化した訪問看護をされていたのでしょうかということをお聞きしたいです。その精神に特化した訪問看護ステーションがどれくらいあるのかということを、把握されていたら教えていただけたらと思うのです。","respondent":"築山障害者施策推進担当課長","answer":"日本精神科看護協会は精神の方を中心に行っていたのですけれども、介護保険のほうも対応はしておりました。精神に特化している事業所がどれくらいあるかというのは、こちらでは把握しておりません。","id":"exchange-014"}]},{"id":"topic-03","title":"住民税非課税世帯等に対する臨時特別給付金の進捗","agenda":"住民税非課税世帯等に対する臨時特別給付金の進捗","exchanges":[{"speaker":"石田（ち）委員","kind":"意見","question":"３月上旬からポスター掲示やチラシの設置とありますけれども、対象なのに給付されないということが増えていくのではないかなと思うのです。私たちもできるだけ知らせていきたいなと思っていますけれども、区の考えを説明を求めました。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"各施設等にできる限りポスターもしくはチラシ等を周知して、様々な区民の皆様の目に触れるような形で周知をしていければと考えています。令和４年９月末までという申請期間になっておりますので、長丁場というか、継続的かつ定期的に周知を行っていくことを考えております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"ぜひさらなる周知をしていただけたらと思います。給付金の申請が始まってから生活保護世帯になった方は対象にはならないのかどうかをお伺いしたいなと思います。","respondent":"櫻木生活支援臨時給付金担当課長","answer":"基本的に個別の状況でありまして、国の規定も何十ページにわたる細かい条件がありますので、一概には言えないところです。一般論としましては、生活保護になられた方でも、様々な条件に該当するということであれば、支給の可能性はあるです。","id":"exchange-016"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"石田（秀）委員","kind":"意見","question":"先に言わせてほしいです。先ほども委員長からそのような話があったので、それを踏まえて、そこだけはちゃんと区分けしてやってほしいということだけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"１００床ぐらいを整備していくなどの答弁があったと思うのですけれども、よく聞き取れなかった部分がありますので、どのような計画になっているのかを聞かせてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"認知症高齢者グループホームにつきましても、拡充の方向で検討をしています。その他の機能につきましては、地元の方、運営法人、ご利用者等のご意見も伺いながら、次年度以降、進めていきたいと考えております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうすると、八潮南特別養護老人ホームのほうは、認知症グループホームも併設ということです。さっとおっしゃったのであまり分からなかったのですけれども、元芝アパート跡地のことも私は今言いましたので、ぜひお答えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"その校庭のところは何平米くらいで、どれぐらいの建物が建つのかというところが分かっていたら教えていただきたいです。そして、これから１.５倍になるというと、それがどれぐらいになるのかということを具体的に教えていただきたいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"５０床ぐらいの特別養護老人ホームということになるのか、その点をお聞かせいただきたいのと、個室しつらえの多床室になっていますよね。それで、今、グループホームは何床あって、これから何床になるのかということも説明を求めました。","respondent":"寺嶋福祉計画課長","answer":"９人掛ける２ユニットで１８床ですので、今の認知症高齢者数の今後の見込みも考えると、少なくとももう１ユニットは増やしてトータル２ユニット。","id":"exchange-021"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"確認させていただきたいのは、今、増改築によって５０床しか増えないということになるということでいいのか。その確認をお願いします。","respondent":"寺嶋福祉計画課長","answer":"既存の建物の改築につきましては、今、まさに検討中なので、どうなるかというところは、まだこの場で申し上げられる段階にはございません。それから、全体の数が、今、ショートステイで１００床が１５０床で、我々としては５０床も増やせるのだという認識でやっております。","id":"exchange-022"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"私は、とてもいいなと思っているのですけれども、そこが変わるのかどうかということを教えてほしいと求めました。それから、元芝アパート跡地での開設はいつ頃かという見通しがあったら教えてほしいと求めました。","respondent":"寺嶋福祉計画課長","answer":"メリットだけではない部分もありますので、そこはしっかり両面から検討していければと考えています。３,０００平米で何階のものが建つかというところから計算せざるを得ないのかなと考えております。","id":"exchange-023"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"都有地なので、東京都の土地を使って、民設民営という形にしていくことになるのでしょうか。それから、いつぐらいの開設をめどに、これからどう進めていくのかというところも伺いたいです。","respondent":"寺嶋福祉計画課長","answer":"これからどのように進めていくかというのは、まさに来年度、一歩ずつ進んでいくことなのかなと。我々としては、やるのであれば早期にやっていただきたいと思いますので、しっかり手続きをしていきたいと考えています。","id":"exchange-024"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"区がそこのところを定期借地で、都有地を活用して、区立の特別養護老人ホームを造ることも可能だということですよね。区立の特別養護老人ホームを造って管理するということもご検討いただけたらと思うのですけれども、そこら辺の区の考え方としてはいかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"定期借地ということで区立の特別養護老人ホームを造るというのは可能ではないのかなと思うのですけれども、どうでしょうか。その点をお願いしたいと思います。","respondent":"寺嶋福祉計画課長","answer":"私が記憶している範囲では、民間の力を活用ということはあったと思いますが、区が借りるというスキームは恐らくなかったと記憶しています。来年度のことにつきましては、それ以上のことはまだ全く示されていないので、今の段階でスケジュール的に申し上げられることはありません。","id":"exchange-026"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"先ほども、八潮南特別養護老人ホームについては、ぜひ個室しつらえの多床室は残していただきたいということで要望をしておきたいと思います。多くの皆様が本当に待望しているので、できるだけ早い開設に向けて、区は取り組んでいただけるようにお願いをしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"石田（秀）委員","kind":"確認","question":"そこで、１点だけ確認なのだけれども、これは、私の知識が間違っていたら教えてください。これは、現制度では致し方ないことなので、それはそのとおりで結構なのだけれども、その１００円という概算が大体合っているかどうかという確認。","respondent":"寺嶋福祉計画課長","answer":"私も委員と同じような認識でおります。施設整備に関しては、建築コスト等々の割り返しになっていると思いますので、それが大きく変動しているとは認識しておりません。","id":"exchange-028"}]},{"id":"topic-05","title":"後期高齢者医療制度における窓口負担割合の改正","agenda":"後期高齢者医療制度における窓口負担割合の改正","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"２割負担になるというところでは、多くの方から、また団体から、本当に反対の声が上がってきていたと思います。１割負担の方、２割負担の方、３割負担の方の人数を教えていただけるか尋ねました。","respondent":"池田国保医療年金課長","answer":"それで、１割負担の方が３万４,７８１人いらっしゃいます。その１割負担の３万４,７８１人の方のうち、９,２２０人の方が２割負担になるという形で推測しています。","id":"exchange-029"},{"speaker":"石田（ち）委員","kind":"質問","question":"保険料が１割負担だった方が２割負担になるということで、倍になるわけですけれども、これによって受診控えが起こる。区としては、区民の方が２割負担になることで受診控え、そして健康悪化が起こるという状況をどのように考えられているか尋ねました。","respondent":"池田国保医療年金課長","answer":"３年間ではありますけれども、３,０００円を超えないようにという緩和もついておりますので、それほどの受診控えはないだろうと考えているところです。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こういうところに、区としてもしっかり声を上げていくべきだと思うのです。これ以上の負担増の範囲が広がらないようにということを求めていただきたいと思うのですが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"先ほどご説明したような「全世代型社会保障改革の方針について」に基づき、２割負担が導入される形になってあります。国の方針で行っているものですので、特別区長会等を通じまして、これからも要望はしてまいります。","id":"exchange-031"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"特別区長会等に求めてまいりますとおっしゃるのですけれども、それぞれの自治体が声を上げていかなければならないなと本当に感じています。これまでの国庫負担を今までの４５％に戻すことを求めていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"私どもとしましては、特別区長会等を通じまして、高齢者の医療に関する要望について、引き続きお願いします。","id":"exchange-032"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですので、７５歳以上の方へのさらなる負担増というのは、ここで止めておいていただきたい。２割負担増も本当にひどい話だと思うのですけれども、これ以上にならないということを、ぜひ区から強く求めてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"その区民の実態に関しては、大変厳しい状況があると思うのですけれども、そこら辺はどのように考えられているでしょうか。ゆとりがあるとはならないのではないかと思うのですが、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"先ほどの課税所得２８万円以上のところでは、収入としては１８０万円から２００万円を超えたところが、課税所得２８万円以上になってくると思います。","id":"exchange-034"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"それから、介護保険料で５,０００円ぐらい取られるのではないですか。高齢者の大変な実態に対しての認識と、２割負担がそれにどれほど追い打ちをかけるものになるのかという辺りの認識について伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"医療費の増大が見込まれていること、後期高齢者医療の負担割合を２割ということで、１０月から追加で導入しますという形になってきているところです。私どももそれだけとは考えておりませんで、区から都、国に対しての要望はこれまでどおり出していくことを考えているところです。","id":"exchange-035"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現役世代の負担がどれくらい減るのかというのは、国会審議の中でも数字が出されていますが、それをご存じでしょうか。ご存じだったらお答えほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"現役世代の人が多いですから、現役世代と高齢者の世代間の対立を図るようなやり方を、私はやめていただきたいと思うのです。老人保健制度から国庫負担の割合を大幅に引き下げてつくった差別の制度ですから、保険料を２年に一遍ずつ上げ、高齢者の健康。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"}]},{"id":"topic-06","title":"国民健康保険料収納サービスの一部変更等","agenda":"国民健康保険料収納サービスの一部変更等","exchanges":[{"speaker":"若林委員","kind":"確認","question":"確認です。これは、利用者にとって特段気をつけなければいけない内容なのか尋ねました。","respondent":"池田国保医療年金課長","answer":"こちらの「請求書支払い」、「請求書払い」、それと括弧つきの「請求書支払い」ですけれども、これは各会社の個別の言葉遣いでございまして、それを引用しているところで、全く影響はないところです。","id":"exchange-038"}]},{"id":"topic-07","title":"ＨＰＶワクチン定期接種の個別勧奨再開に伴う区の対応","agenda":"ＨＰＶワクチン定期接種の個別勧奨再開に伴う区の対応","exchanges":[{"speaker":"若林委員","kind":"質問・要望","question":"接種の間隔が言われておりまして、これはホームページでも確認したのですが、ほかのワクチンと何週間間隔を空けなさいというところがあります。２回目、３回目を何らかの事情で受けていないという方がいらっしゃるのかどうか、確認をさせてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"３月末までを予定しているところですが、その中で、その辺りも分かりやすく記載されるものと考えているところであります。全額公費で支援していた時期がありますけれども、３回目を接種していない場合は、今準備を進めております。","id":"exchange-039"},{"speaker":"若林委員","kind":"意見","question":"後段のほうは分かりました。資料を作成中とのことで、これに合わせて、そういったものも随時更新していくということで理解をいたしましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-040"}]},{"id":"topic-08","title":"新型コロナウイルス感染症に係る保健所・保健センターの対応","agenda":"新型コロナウイルス感染症に係る保健所・保健センターの対応","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"今の報告の中で、品川区の感染者数も、１日の感染者数の最高が２月７日の８０７人でいいですよねという確認です。自宅療養者数の最高が３,７６９人かという確認もお願いします。","respondent":"鷹箸保健予防課長","answer":"なお、黒三角の１番目の抗原定性検査キットで陽性だった方というのは、区の全体の統計の中で区別することができない状況になっています。１日に８０７名の患者を確認させていただき、２月９日が最も多くて、３,７６９人という数です。","id":"exchange-041"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"たしか応援職員がこれまでの合計で２５０人という答弁があったと思うのですけれども、その内訳で、職種別の人数が分かれば教えていただきたいです。ここが、去年の１０月の数で止まっているのですけれども、今のところのオンライン診療と往診の利用者の数が分かれば教えていただきたいです。","respondent":"鷹箸保健予防課長","answer":"常勤の数と応援の数については、正確に言うと３日ごとぐらいに変わっていますので、また改めてお伝えできればと考えております。申し訳ございませんが、今この場で正確な数をお伝えするのは難しいと考えておりますので、また改めてお伝えできればと思います。","id":"exchange-042"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"入院患者、これは２月１３日なので、直近の一番新しい数値で分かるものがあったら教えてほしいと求めました。死亡者も、１月末で１５２人で、死亡者も第６波で現在のところ何人ぐらいの方が亡くなられているのかということも教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"１週間ごとに更新させていただいているところですが、申し訳ありません、先日の２月２０日までの分を本日中に更新する予定にしています。亡くなられた方が１６６名ですので、第６波が１月と２月と考えますと、２１名ということになります。","id":"exchange-043"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"自宅療養者の一番多いところが２月９日で３,７６９人ということだったのですが、これは一般質問か代表質問で何人かの方が聞かれている数字と少し違うのですけれども、こちらのほうが正しい新しい数字ということで考えたらいいのか尋ねました。","respondent":"鷹箸保健予防課長","answer":"考え方として夜中の１２時で締めると考えていただくとよろしいと思うのですが、入院中であっても、実は１日のうちに数十人の単位で変更があります。２週間前ぐらいまで遡って、２週間前とか、場合によっては１か月前に遡って数を変更することがあります。","id":"exchange-044"},{"speaker":"鈴木（ひ）副委員長","kind":"確認","question":"今までもそのように数がいろいろと変動する仕組みは聞いていましたので、改めて確認させていただいて分かりました。保健所でずっと経過観察をしなければならないのはどれくらいで、東京都がどのような状況になっているのかという辺りを教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"宿泊施設療養中の方が５３０人、入院または宿泊施設に調整中の患者が２９人、保健所で直接対応させていただいている患者が１７５人。これが２月１９日の夕方４時の速報値がそのような形で、本当に数が常に動いている状況になります。","id":"exchange-045"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"前は、本当に深夜までというところで、そこら辺の状況がどうなっているのかについてもお聞かせほしいと求めました。それともう一つ、それは１週間に何日で、１日何人くらいまでの体制でやっているのかという点についてもお聞かせほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"多い職員では２００時間に近い職員もいますし、５０時間前後という職員もいて、担当業務によって相当違うという現状になります。どちらかの曜日に動かすのですが、基本は週３日で、１日６０名までを基本として検査をお願いしている状況になります。","id":"exchange-046"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"月２００時間といったら、そういう状況が今でもあるということに対しては、本当に改善できるような体制をとっていただきたいなと思っています。返ってこないのが何件もあるとも伺っていたのですけれども、何台あるのかということも含めて教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"３００回線で始めたということですが、１週間以内にＵＲＬが公開されて、それから届くという方針に今は変わっています。正確な数を今お答えできませんが、もちろん１台で十分という形になりますので、必要な方になるべく早く届くような形で対応をしているところです。","id":"exchange-047"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"連れていくこともできないというときに、オンライン診療ですごく助かって、薬も届けてもらって本当に助かりましたということも伺っているのです。増えているのであれば、その数も合わせて教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"基本的には、その当時の数の中で対応していただいています。オンライン診療は、区の枠組み以外にも、かかりつけ医の先生からオンライン診療していただいたという事例ももちろんあります。","id":"exchange-048"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"もう一つ伺いたいのが、東京都のホームページを見ると、たしか１０か所ぐらいまで増えていると思うのです。私は、そこが具体的にどのような状況なのかを１か所伺ったのです。","respondent":"鷹箸保健予防課長","answer":"薬局で手を挙げていらっしゃるところが多いと認識しているのですが、特にこの第６波に間に合っているのかなと思うと、疑問なところもありました。公開する予定もないというのが、あくまでも都の方針のようです。","id":"exchange-049"},{"speaker":"鈴木（ひ）副委員長","kind":"質問・要望","question":"ぜひ無料で検査が受けられるところの拡大を求めていってほしいと求めましたし、区としても、いかがでしょうか。これが今、２７％ぐらいになっているのですかね、これも最新の状況でどれくらいになっているのかが分かったら教えていただけたらと思います。","respondent":"鷹箸保健予防課長","answer":"地元といいますか、地域密着の保健所といたしましては、感染者の個別の対応に力を注いでいきたいなと思っています。１月にその方針が出まして、この事業の方針が示されたときから、保健所の方針としてもお伝えしているところです。","id":"exchange-050"}]},{"id":"topic-09","title":"品川区新型コロナウイルスワクチン追加接種","agenda":"品川区新型コロナウイルスワクチン追加接種","exchanges":[{"speaker":"石田（ち）委員","kind":"確認","question":"解熱剤を飲んでも熱が下がらないということがあったりもしたので、そういう問合せは、３回目で何か特徴はあるのかなというのを伺いたい。確認ですけれども、小児用の接種のところで、５の実施場所の（２）の保健センターは、日曜日だけということでいいですかという確認です。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２点目、３回目ワクチンの副反応についてのお問合せなのですが、そういったお問合せは来ておりません。３点目、小児用のワクチンの保健センターについては、現時点では日曜日のみの運用ということで準備を整えております。","id":"exchange-051"},{"speaker":"鈴木（ひ）副委員長","kind":"質問","question":"保健センターということだったので、日曜日ということになると、保健センターの職員が関わるわけではないですよね。ということは、これは、どこかに委託するのか、どのような体制でやるのか、誰がやるのか、その点だけ説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"各医師会等を通じて出務調整は行っているところですが、昭和大学の先生が出務をしてくださるですので、その辺りで、今、調整を進めているところです。","id":"exchange-052"},{"speaker":"鈴木（博）委員長","kind":"質問・要望","question":"私から質問したいのですけれども、１つは、接種に来ている方の数はどうなのでしょうか。これは要望なのですけれど。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"集団接種会場のモデルナ枠についてご説明します。うまく使っていただければと考えていますが、その辺りはうまく調整しながらということで、進めさせていただければと考えています。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/567724?Template=document&Id=3622#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":51505,"voices":205}},{"id":"r04-20220224-8","meetingId":"r04-cm02","date":"2022年2月24日","dateIso":"2022-02-24","committee":"建設委員会","time":"午前１０時００分～午後 ０時０６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を57件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"塚本委員","kind":"意見","question":"前例どおりの、冒頭に自席からの撮影でお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"}]},{"id":"topic-02","title":"令和４年請願第６号、リニア新幹線の中止を求める請願","agenda":"令和４年請願第６号、リニア新幹線の中止を求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そこで、今実際に余り進んでいないように思うのですけれども、今これが掘り進めて何ｍ進んでいるのか伺いたいと思います。そして、余り進んでいないというところで、何かトラブルなどがあったのかどうか、そこを伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"国がリニア中央新幹線の必要性ということで決定したというところで、区としましては、国が決定したということを認識しているところです。トラブル等についても、特に区のほうに報告はございません。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"丁寧に進めているのでそれほど進んでいないという説明だったと思うのですけれども、そうすると１か月経っても位置は変わらないということなのですか。そういったことはないかどうか伺います。","respondent":"中道まちづくり立体化担当課長","answer":"１日に進んでいるメートル数、今２０ｍという数字がございましたけれども、それは多分、一番順調に行ったときのマックスのスピードかと考えています。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"改めて、そうした状況の変化も踏まえて、区が必要だと考えているのかどうか伺いたいと思います。東海道新幹線の４倍と請願にも書かれておりますけれども、これからの社会と逆行するものだというふうに思うのですけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"現在、コロナというところで、リモートであったり、出張も減っているというところは、もちろん区も認識しているというところです。やはり車を減らして、こういった鉄道が増えることで、環境負荷は軽減されていくものと考えております。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問","question":"負荷が軽減されるというお話でしたけれども、この間、東海道新幹線の乗降客はそれほど増えているわけでもないということなのですね。車から乗り換えるということがそれほどあるのかなというふうに思うのですが、もう少し具体的な方向、数値などがあれば伺いたいと思います。","respondent":"中道まちづくり立体化担当課長","answer":"これがモーダルシフトの考えなのですけれども、柔軟性というところは、鉄道や船が車に負けてしまうというところです。やはりそこの活用については、もちろんそれはＪＲ東海が考えることですが、環境には非常にメリットというふうに考えております。","id":"exchange-005"},{"speaker":"のだて委員","kind":"質問","question":"国会で共産党の山添拓参議院議員が文書質問をしまして、実際に品川区内のルート上でボーリング調査を行った件数というのは０件という回答でした。そうした下でやはり陥没事故などが起こってくる危険性があるのではないかと私は思いますけれども、区のお考えを伺います。","respondent":"中道まちづくり立体化担当課長","answer":"区といたしましても、もちろん外環道での陥没事故というところもありまして、令和３年１月に要請書をＪＲ東海に送っております。実施検証もしているということで、ＪＲ東海も外環工事の陥没事故を同様に起こさぬよう、様々な視点で今取り組んでいるというところです。","id":"exchange-006"},{"speaker":"のだて委員","kind":"質問","question":"そうした下で、ボーリング調査も基準どおりには行われていないという状況で工事を掘り進めていくのはやめていくべきだというふうに思いますけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"今も調査掘進をしているというところで、シールド工法において通常行わないような委員会を立ち上げたりなどして、丁寧に様々な視点で調査をしながら進めているというところです。","id":"exchange-007"},{"speaker":"のだて委員","kind":"質問","question":"ＪＲ東海自身が安全な工事を進めていけるのかという疑念が湧いてくるのですが、区としてはどのようにお考えなのでしょうか。伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"のだて委員","kind":"質問","question":"事故の安全性、しっかりできるのかという、事業者として、それがしっかりと工事できる事業者なのかどうかというのを、区がどう見ているかということをお伺いしたいのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"私は別の質問だというふうに思いますけれども、このリニア新幹線自体が事業として成り立つのかどうかという問題も今出てきております。そうした下で、実際に事業として成り立つのかどうかというふうな状況になっていますけれども、区としてはどのように考えていらっしゃるのか伺います。","respondent":"中道まちづくり立体化担当課長","answer":"平成２３年５月に、国土交通大臣がＪＲ東海を営業主体および建設主体に指名しております。不測の事態が発生しても、経営の安定性を維持しながら事業を遂行することも可能ということで、ＪＲ東海が指名をされているというところです。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"実際、東海道新幹線の収益が減っているという下で、国からも既に３兆円の財政投融資ということで税金を投入していくということになっています。さらに投資が増えていく、住民への負担が増えていくということはあってはならないというふうに思いますけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"国からの財政投融資３兆円を受けているというところですけれども、原則と言いますか、一時的にお金は借りているというところです。税金で補助金などを出しているわけではなくて、お金を貸しているということで、それは返ってくるということになります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"貸して返ってくる予定ですけれども、実際のベースとなっているのが東海道新幹線の年間３,０００億円の売上げ、収益が上がるというのが前提になっている下で、今事業が悪化しているというところで返せなくなってしまうのではないかということを言っているのですけれども、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"先ほどの答弁の繰り返しになってしまうのですけれども、そういった不測の事態があっても、安定的に事業を遂行できるというところで国がＪＲ東海を指名したということで、区は認識しております。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"そこを伺いたいと思うのですが、終了時間になっても手を挙げている方がたくさんいらっしゃるという状況の下で終了になったという状況がありました。しっかり、この説明会というのが十分に行われていないというふうに思うのですが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"説明会ですけれども、前回の説明会は１回ずつで、同じ説明会を３回行ったのですけれども。ＪＲ東海はオープン型の説明会をして、空いているときにそういった細かい説明もできるようにというところで、オープン型説明会を開催して。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問","question":"説明会をしっかり行ってお知らせをしていくことは、まず大前提だというふうに思いますので、そこはどうしてもお願いしたいと思います。最後に、区が区民への被害が出ると思っているのかどうか、そこを伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"請願趣旨の中に、地下４０ｍというところなのですが、地下は結構掘っていますよね。どこと同じレベルなのでしょうかということと、どこまで国としての裁量で任されているのかという、その権限の範疇を説明を求めました。","respondent":"中道まちづくり立体化担当課長","answer":"今、大深度法を適用していますので、今のインフラを行っているものの一番最下段に位置するというところです。地上から４０ｍ、もしくは支持地盤から１０ｍ、そこの部分が公共的に使える空間になるというところです。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"地下を掘っているからという形になって、どうしてもやはり心配になってしまうと思うのですけれども、そこはどうなのでしょうか。大丈夫ですよとはっきり言えるものなのか、ちょっと心配はあるのですということなのか、それはどうなのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"３ｍから５ｍぐらいの間の中に穴があって、穴ができないかという、それを事前に防ぐというところです。そうした技術的な積み重ねというところで、事故が起こらないように、さらにこういった委員会も開いて丁寧に進めていくというところです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問","question":"ですから、いろいろ技術革新はあるのだろうなという思いもあるのですね。この補償というのはどういう形で、そうすると何か起きたときの補償というのは何かあるのか、そういう細かいお話などは詰められているのか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"その工事に起因して何かあったら、そのときには補償をするということも、ＪＲ東海は説明会等で皆様に説明しております。まず１回ビラを配って返信を待つのですけれども、それを今３回繰り返して、順次地域ごとに前に進めるというような状況です。","id":"exchange-017"},{"speaker":"芹澤委員","kind":"確認","question":"ＪＲ東海の資料も拝見した上でお伺いしたいのですが、安全性の確認という意味で言うと、そこの連携をどうされているのかお伺いしたいのですが。","respondent":"中道まちづくり立体化担当課長","answer":"目の前の都道に直接大型車が出られますので、区道のような細いところではなくて、すぐに大きい道路に出ていけるというところがまず１つあります。","id":"exchange-018"},{"speaker":"芹澤委員","kind":"質問・要望","question":"もう１点、抽出して幾つか行っていくのか、全戸にお願いをされていらっしゃるのかをお聞かせいただきたい。","respondent":"中道まちづくり立体化担当課長","answer":"シールドマシンが１４ｍになりますので、両側約２５ｍぐらいの部分が家屋調査の範囲に……。その範囲に入っている家屋につきましては、全軒調査対象というところで、今ＪＲ東海でビラを配っているというところです。","id":"exchange-019"},{"speaker":"大沢副委員長","kind":"質問","question":"今、課長のお話の中で、もし陥没があった場合ということをおっしゃっていたのですけれども、その「もし」がないために、どのように安全が担保され、安全策が講じられているのか、そこの現状を説明を求めました。","respondent":"中道まちづくり立体化担当課長","answer":"その都度、土質を先行的に見て、そのときにどういうふうに対処したらいいかというというような工夫なども行っております。もちろん、先ほどのお話にあった有識者委員会とか、学識経験者の方などともいろいろ意見交換を交わしながら行っているというところです。","id":"exchange-020"},{"speaker":"大沢副委員長","kind":"質問・要望","question":"質問は分かりますか。話合いのかたちづくりをどのように考えていらっしゃるのか説明を求めました。","respondent":"中道まちづくり立体化担当課長","answer":"専門的になってしまうのですが、そういうことも現地で今やりながら、調査しながら施工を実地検査しているというところです。そういう段階に来ているというところです。","id":"exchange-021"},{"speaker":"のだて委員","kind":"確認","question":"トンネル工事を２４時間やられるということを聞いているのですが、その確認と、そこを伺いたいと思います。残土の処理なのですけれども、どこに運搬するとか、処理の仕方というのは決まっているのかどうか伺います。","respondent":"中道まちづくり立体化担当課長","answer":"２４時間施工の件、今回のリニア中央新幹線ですけれども、こちらは２４時間施工というところで工事を進めていくというふうに聞いてあります。残土ですけれども、こちらは新本牧ふ頭の埋立工事、公共事業のほうで残土利用されるというふうに聞いております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問・要望","question":"２４時間施工のほうは、外環道ではやはりあったというのが実態ですので、そうしたところをしっかりと鑑みていただきたいと。ぜひ２４時間でないようにするべきではないかと思いますが、いかがか尋ねました。","respondent":"中道まちづくり立体化担当課長","answer":"こちら、そういったことも今調査掘進で行っておりますけれども、基本的に２４時間施工で行くというふうに聞いております。","id":"exchange-023"},{"speaker":"芹澤委員","kind":"意見","question":"ご説明いただいたとおり、国が許可をして、民間が今進めている事業というのが、まず第１点にあります。周辺の公園も含めて、必要なことは連携が既にとれているかと思いますが、お話をしていってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"塚本委員","kind":"質問・要望","question":"区も、国ともしっかり連携をとって、そういったことに努めていただきたいというふうに思います。一定程度それは確認ができましたし、事業そのものを中止というところまではすべきというふうには考えませんので、不採択でお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"大沢副委員長","kind":"質問","question":"国から許可が下ろされた事業でありまして、ここのところを中止ということは、まだ拙速ではないかなと考えます。これが１つの願いでありますから、それを行いながら、この事業を進めていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"のだて委員","kind":"意見","question":"実際に陥没事故というものが起きていますので、そうした危険を生み出していますし、そもそもの必要性も私はないと思います。説明自体も不十分で、知らない方もたくさんいるという状況ですので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、技術革新はかなりしているので、安心感とか、いろいろな対応はできている状況だと思います。やはり、情報開示の方法などというのをこまめにしていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-03","title":"東京都市計画下水道［東京都公共下水道］（浜川ポンプ場）の廃止","agenda":"東京都市計画下水道［東京都公共下水道］（浜川ポンプ場）の廃止","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回の目的の１つに流域の浸水対策というのがあるのですけれども、これがどういうことなのか、もう少し詳しく伺いたいと思います。切替えが実際にされるのはいつ頃になる予定なのか伺います。","respondent":"栗原河川下水道課長","answer":"勝島ポンプ場ができたのが平成２４年で、浜川ポンプ場が昭和４７年ということで、浸水対策に資するものです。切替えの工事ですが、現在、品川区が下水道局より受託して切替え工事を行っておりまして、今年の６月に完了する見込みとなっております。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問","question":"水質改善のところも目的とされていますけれども、これももう少し詳しく、どう改善されていくのか伺いたいと思います。","respondent":"栗原河川下水道課長","answer":"浜川ポンプ場は閉鎖性水域である勝島運河へ雨水を排出しているわけですけれども、今回、勝島ポンプ場に切り替えることで、水域としては開けた場所で雨水を排出することになりますので、水がよどまなくなるという面で、水質改善ということを目的としているところです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"浜川ポンプ場の後は、どういう活用というのは決まっているのでしょうか。これからなのか尋ねました。","respondent":"栗原河川下水道課長","answer":"浜川ポンプ場の跡地ですけれども、今後、立会川の高潮、津波対策のために、こちらに樋門と排水機場を整備する計画があります。浜川ポンプ場の跡地につきましては、その排水機場を整備する予定であると、東京都から聞いております。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"そうすると、後は東京都のほうでそれらの事業を進められるということで、立会川の水質、前から問題になっていると思うのですけれども、それが良くなっていく方法も考えられているという認識でよろしいか尋ねました。","respondent":"栗原河川下水道課長","answer":"下水道局で実施しております立会川幹線雨水放流管、こちらが完成いたしますと、立会川への放流が大幅に減る見込みとなっております。そういった事業と今回の切替え工事と併せて、立会川、それから勝島運河の水質改善が進むものと認識しております。","id":"exchange-032"}]},{"id":"topic-04","title":"新防火区域の拡大","agenda":"新防火区域の拡大","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"これから行政手続きがどういうふうに進められていくのか、また、それに加えて必要なところがあれば伺いたいと思います。住民の方にはやはり影響が出てくる、しっかりと理解していただけるように説明をしていただきたいと思うのですけれども、いかがか尋ねました。","respondent":"長尾建築課長","answer":"冒頭ご説明した不燃化特区支援事業を令和３年４月から、今年度からスタートしておりますが、その不燃化特区支援事業に関わる計画です。８月に実施予定としている地元への説明会につきましては、今回、支援もありますというところはしっかりご説明していきたいと考えております。","id":"exchange-033"},{"speaker":"のだて委員","kind":"意見","question":"知らなかったということがないようにお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問","question":"分からなくなってきたので教えてください。ブルーにしなければいけないよということで、今まではどうだったのかなど、指定された意味合いを説明を求めました。","respondent":"長尾建築課長","answer":"今回の指定予定エリアの赤枠で囲んでいるところにつきましては、西品川一丁目全域ということでこの赤枠の範囲となっております。そこが、今回の新防火区域の指定によって変わってくる大きな部分となっております。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問","question":"この敷地の面積にも関わってくるのですか。不燃化をするときに、狭いところだとたくさんできてしまうので、何m2以上などという規制がかかっていて、というようなことはないのか尋ねました。","respondent":"長尾建築課長","answer":"６０m2以上であるとか、そういった敷地面積の制限というのが設けられている地域が、品川区内にもあります。あくまでも、建物の燃えにくさに関わる規制を高めるというところだけになります。","id":"exchange-036"},{"speaker":"西本委員","kind":"質問","question":"そうなってくると、１つの逃げ方ではないのですけれども、建替えではなくてリフォームにする可能性もあるのですよね。ですから、そういう方法も可能なのか、そこはどうなのか尋ねました。","respondent":"長尾建築課長","answer":"やはり建築確認申請が必要なものもあれば、例えば内装の壁紙を変えるとか、そういったものまで幅も様々あると思います。そういった、趣旨をご説明しながらできるだけその方向性に沿ったリフォームになるような助言であるとか、指導というのはしていきたいと考えています。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問・要望","question":"ただ、いわゆるそこで生活をしているということ、それから、なかなか建替えと言っても、お金がなかったら建替えはできないというところとか。システムというか、相談のほうをしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"耐震化とか、不燃化とか、もう問題がないところだと思うので。これは、どういうところにあるのかなというのはよく分からないのですけれども、そこのところをもう少し詳しく教えてほしいと求めました。","respondent":"長尾建築課長","answer":"実際は、資料の４で書いている耐震化の支援事業が、直接支援として働くものではございません。不燃化特区の支援事業だけですけれども、状況をお聞きしながら、そういった選択が可能になるというところが支援になっていくと考えております。","id":"exchange-039"},{"speaker":"塚本委員","kind":"質問・要望","question":"５００m2以下というのも、私の認識で間違っていたら教えてほしいのですけれども、この準耐火建築物になるのではないかなと思うのですよね。狙いというのはどういうところにあるのかというのを、どういうところに狙いを定めているのかということを、詳しく教えてほしいと求めました。","respondent":"長尾建築課長、中村都市環境部長","answer":"それもありまして、今、委員がおっしゃったように、もう準耐火建築物に建て替わっていくという認識になられているのかなと感じております。今回の新防火区域を定めることで、この西品川一丁目もなれるというところが… ２枚目の資料の上の緑色の網がかかったところは、不燃化特区指定区域と言いますが、その分余計にお金がかかるわけですね。きちんと差額もお支払いしますと、そういう制度２つが整うと、こういうことになるです。","id":"exchange-040"},{"speaker":"塚本委員","kind":"意見","question":"話が広がってしまうかもしれないのですけれども、防災という面でいくと、大変いい形の規制かとも思います。今後やはり品川区内としては、新防火区域を指定していくに当たってどういったことが前提で決まっていくのか、最後に説明を求めました。","respondent":"長尾建築課長","answer":"は不燃化特区支援事業の計画の中で、新防火区域を導入していきますというところの位置づけもありますので、そういったところから定めております。","id":"exchange-041"}]},{"id":"topic-05","title":"令和４年請願第３号、感震ブレーカーを品川全域につけることを求める請願","agenda":"令和４年請願第３号、感震ブレーカーを品川全域につけることを求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ私たちも全域に広げてほしいということで求めてまいりました。ぜひ広げてほしいのですけれども、いかがか尋ねました。","respondent":"山本防災課長","answer":"先ほどご説明したとおり、現状、そちらの地域を区といたしましては重点的・集中的に行っていきたいというふうに考えているところです。今後の地域展開に関しましては、現状の対象エリアの設置状況等も見ながら考えていきたいと考えています。","id":"exchange-042"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ広く拡大をしていっていただきたいと思うのですが、全体としてもやっていくということは可能ではないかと思うのですが、いかがか尋ねました。","respondent":"山本防災課長","answer":"新たに３地区、対象エリアに加わっておりますが、そういったところで町会長と町会への説明等も丁寧に行っているところです。こちらの設置状況等を見ながら、今後の拡大というところは考えていきたいと考えています。","id":"exchange-043"},{"speaker":"のだて委員","kind":"質問","question":"実際に通電火災がどこで起きるかというのは分からない状況ですから、進んでいるところはあると思うのですが、さらに進めていくための対策ですね。あるいは、今進んでいないと言っていいのか、進んでいないとすれば、その課題が何なのか伺いたいと思います。","respondent":"山本防災課長","answer":"それから感震ブレーカーの役割、重要性、こういったところを丁寧に周知していきたいというふうに考えているところです。個別で付けている方もいらっしゃるというところで、そのあたりをどう進めていくかというところはしっかり考えていきたいと考えています。","id":"exchange-044"},{"speaker":"のだて委員","kind":"質問・要望","question":"現状を把握することで、そこはぜひ現状を把握してほしいと求めましたし、請願の中でも全額を支給してほしいということで書かれております。こうした全額支給にすることで、さらに設置が進んでいくという効果もあるのではないかと思いますが、そのお考えを伺いたいと思います。","respondent":"山本防災課長","answer":"現行の補助率と補助内容をご覧いただきますと、現行でもかなりご自身の負担が少ない自己負担額になっているというふうに考えております。","id":"exchange-045"},{"speaker":"のだて委員","kind":"質問・要望","question":"全額にしない理由を改めて、さらに具体的なところでお話があれば伺いたいと思います。この簡易タイプがなかなか進んでいないという状況がありますけれども、こうした現状、区の分析、課題などを含めて伺いたいと思います。","respondent":"山本防災課長","answer":"件数が伸びていない理由といたしましては、ご自宅のアース付きコンセントの数がそもそも限られているということが１つ理由かと思います。それから、工事等で設置することも可能になるのですけれども、申請をこちらに変更しているということで。","id":"exchange-046"},{"speaker":"西本委員","kind":"質問","question":"大体、どのぐらいの規模を考えていて、実績はここに書いてありますけれども、それがどういう評価をされるのか。まだまだですねという評価なのか、気持ちはやはりもっと広げていきたいという思いがあるのか、いかがか尋ねました。","respondent":"山本防災課長","answer":"簡易タイプにつきましても、５０件を見込んでおりまして５件というところになっております。実績は５０件というところ、１２０件というところで令和２年度予定をしておりましたが、２件が実績となっているところです。","id":"exchange-047"},{"speaker":"西本委員","kind":"意見","question":"多分、この現状把握、確かに現状把握が必要な状況なのかなというふうに思っております。今後ともとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-048"},{"speaker":"芹澤委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。その現状の把握というのは、区も引き続き進めてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問・要望","question":"区が木密地域を重点的にと、燃え広がらない面的な効果ということをこの政策に求めて進めているということについては、一定理解ができます。現時点で品川区全域に、また全額助成でということについては、不採択ということでお願いをいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"大沢副委員長","kind":"質問","question":"本日結論を出すで、不採択でお願いします。先ほどの西本委員の質問の中で、これは特化をして様子を見る段階であると私は思っておりますので、不採択ということでお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"のだて委員","kind":"意見","question":"やはり、大地震への備えというのも急務ですし、請願にもあるとおり、通電火災がどこで起きるか分かりません。区内全域に対象を広げて、防災対策を進めていくべきだと考えますので、採択ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"西本委員","kind":"質問","question":"これは認識の問題が大きいのだろうと思うのですね。まだこの指定されているところでさえこういう状況ですから、それを見極めるという、ある一定の時間は必要かなというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"西本委員","kind":"質問","question":"説明は若干、簡単でいいので、説明をしていただくことは可能でしょうか。現状の１つの視野を広めるという形でも、せっかく準備していただいたのにと思っているのですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"}]},{"id":"topic-06","title":"の３、報告事項を再び聴取いたします。 (3)目黒川安全航行啓発活動の実施","agenda":"の３、報告事項を再び聴取いたします。 (3)目黒川安全航行啓発活動の実施","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これは今回で６回目ということなのですけれども、通常、問題、マナー違反などの問題があったというケースはあるのでしょうか。ある場合は、どのぐらいあるのか、もう少しお聞きしたいのですが。","respondent":"栗原河川下水道課長","answer":"航行マナーに関する苦情の件数ということですけれども、昨年度ですと１件あったということです。そういったことが起こらないような取組を続けているところでして、苦情の件数としては少なくなってきていると認識しているところです。","id":"exchange-055"},{"speaker":"西本委員","kind":"質問","question":"今回、２６日・２７日に航行する場合には申請が必要ですよということなのですけれども、この目黒川は結構行き来はできるものなのでしょうか。その自由度はどういう形に、申請などは必要なのか尋ねました。","respondent":"栗原河川下水道課長","answer":"今回の啓発活動ですけれども、船の航行を制限して実施するものでございまして、啓発活動を行うための占用です。通常、啓発活動を実施していないときは、運航そのものに関して特に制限はございません。","id":"exchange-056"},{"speaker":"西本委員","kind":"質問","question":"その中で、余り問題が起きないなという、そのような感じはしているのです。毎年、皆さん、マナー良く使われているのかなというふうに思っているのですけれども、その辺の評価というか、それを最後に説明を求めました。","respondent":"栗原河川下水道課長","answer":"この啓発活動の実施もそうですし、マナー向上に取り組んでいるというところが、継続してこういった委員会での活動を実施していきたいと考えております。","id":"exchange-057"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/985406?Template=document&Id=4344#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":35050,"voices":155}},{"id":"r04-20220224-9","meetingId":"r04-cm02","date":"2022年2月24日","dateIso":"2022-02-24","committee":"文教委員会","time":"午前１０時００分～午後 ２時５２分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件整理しています。","topics":[{"id":"topic-01","title":"令和３年度品川区教育委員会事務事業の点検および評価の報告書","agenda":"令和３年度品川区教育委員会事務事業の点検および評価の報告書","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"３つの点についてまとめて質問したいのですが、ＩＣＴ支援員の雇用形態は、会計年度任用職員なのか委託なのか伺いたいと思います。テスト対策に追われて、私はこういう方向でどんどん進めていいのかという疑問があるのですが、いかがか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-001"},{"speaker":"安藤委員","kind":"提案","question":"授業提案や授業の支援というと、そこら辺はどうなのかということと、そこら辺もお伺いしたいというのがあります。希望者は先ほどの数に比べてどれぐらいニーズがあるというのを伺ったので、伺いたいと思いますとの意見を述べました。","respondent":"勝亦学務課長、矢部教育総合支援センター長","answer":"学校現場のＩＣＴの技術的な支援、そういった支援になっておりまして、そういった教育内容に介入という考え方はございません。そういった意味で、学校の中で指揮命令系統になるものではございませんので… ただ、学期末で、もう来年度になるということもありまして、概数ですけれども、５人ぐらいお待ちいただいているという認識です。ただ、見学は受け入れております。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"現時点でありましたら、お伺いしたいと思います。これは改善が必要だと思いますけれども、いかがか尋ねました。","respondent":"矢部教育総合支援センター長、工藤指導課長","answer":"小学生の対応については、来年度は１年かけて、研究していきたいというスタンスでおります。専門家や巡回相談員も特別支援学級に行っておりますので、それぞれ専門分野の中で研修を進めている、ＯＪＴを進めているという現状があります。 知的障害の特別支援学級への教員の配置については、免許を持つ者をぜひ配置いただきたいということで要望していますので、引き続き要望したいと考えているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"こういうのが出ていますけれども、これはモデル校５校ということですが、それぞれ何人ずつ、合計何名の配置になるのでしょうか。伺って、終わります。","respondent":"矢部教育総合支援センター長","answer":"５校に配置します。会計年度任用職員で、計１０名になります。","id":"exchange-004"},{"speaker":"吉田委員","kind":"質問・要望","question":"それに対するどういう評価を求めてこられたのか、伺いたいと思います。必ずしも１年で終わるものではないということは承知しておりますけれども、教育委員会としてはどのように考えておられるかお伺いいたします。","respondent":"矢部教育総合支援センター長","answer":"特別支援教室、２年目もあるというのは、東京都の示しもあります。何とか今までの特別支援教室の学習を活かせるように、発達障害教育支援員を中心に、担任と連携して支えてまいりたいと考えております。","id":"exchange-005"},{"speaker":"吉田委員","kind":"質問・要望","question":"それから、保護者の方もいろいろなことを求めておられるのは十分承知しておりますので、ぜひこれからも拡充をしていってほしいと求めました。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"松本委員","kind":"質問・要望","question":"そこの経緯をまずもう一度、事業目的との関係で大事だと思うので、少し令和２年３月２３日の要綱の改正の流れについて伺いたいと思います。オンラインである程度できるような体制を取っていただきたいと思うのですけれども、どのようにお考えか、お願いいたします。","respondent":"矢部教育総合支援センター長、吉田品川図書館長","answer":"マイスクールの目的のことですが、同時期に文部科学省のほうから、社会的な自立を示す通知がございましたので、それを受けての要綱改定です。 通常の、図書館に来ていただいて、図書館員が読み聞かせるというのも、継続もしております。安全性や一般的なコロナ対策をしながらというところで進めているところと、今年の１月に、その話を伝えるということもやったところです。","id":"exchange-007"},{"speaker":"松本委員","kind":"質問・要望","question":"読み聞かせもオンラインでやられたということが確認できたので、来年度も引き続きお願いできればと思います。以上、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"図書館としてどういう受け止めをして、お考えが案として上がっているのであれば、それを説明を求めました。","respondent":"吉田品川図書館長","answer":"これを借りてみようと思うような見せ方、そういうことも大事なものだと思って、今後もディスプレイなど見せ方等については研究してまいります。そういうところは、またこれも利用者の意見を聞きながら等も含めまして、今後も検討してまいります。","id":"exchange-009"},{"speaker":"つる委員","kind":"確認","question":"すまいるスクールとかで、児童センターもそうなのですけれども、その辺の本の回し方というのでしょうか。ここはどうなっているか、説明を求めました。","respondent":"吉田品川図書館長","answer":"８割ぐらい本を置いて、その残り２割のところで本の表面を見せるだとか、特集として見てほしいとかということもやれるのではないかというところです。","id":"exchange-010"},{"speaker":"つる委員","kind":"確認","question":"それについて区の施設の中でも回せることができるのかと思ったので、そこを改めていろいろ自分でも確認したいと思います。やった上で、広く展開をしているという理解でいいか、確認させてください。","respondent":"吉田品川図書館長","answer":"リサイクルのところにつきましては、実際に各所管へのお渡しというところも、今後は調整してまいりたいと思います。それから、オンラインの読み聞かせにおける著作権の問題につきましては、解決した状態で、行ったところです。","id":"exchange-011"}]},{"id":"topic-02","title":"区立児童相談所の開設時期および「児童相談所開設に向けた計画書 骨子（案）」","agenda":"区立児童相談所の開設時期および「児童相談所開設に向けた計画書 骨子（案）」","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"それと、職員の配置について伺いたいと思うのですが、現在の児童相談所の国の配置基準はどうなっているのか、教えてほしいと求めました。それと、こういったことに関して、検討委員会での検討委員の意見などはどんな意見があったのか、伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"１つ目にご質問いただきました区立児童相談所設置・運営計画検討委員会のメンバーについてですが、こちら、現在。区といたしまして、来年度、令和４年度に、こうした検討委員会を使って、実務的な検討を進めていきたいと考えているところです。","id":"exchange-012"},{"speaker":"安藤委員","kind":"確認","question":"４８時間以内に子どもの安全確認を行うことが定められていますので、場合によっては、緊急保護が必要な場合もあると。やはり委託化すべきではなく、行うべき業務かと思いますけれども、いかがか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"業務の専門性の向上といったところ、必要なところは民間の力を借りながらというところで、委託化の検討をしていきたいと考えております。夜間休日における対応・通告窓口につきましては、有識者の意見等も聞きながら、こちらは検討を進めてまいりたいと考えているところです。","id":"exchange-013"},{"speaker":"安藤委員","kind":"確認","question":"そういう情報共有や様々な統一化というのはすごく重要だと思うのですけれども、その辺りはどういう体制で担保するお考えなのでしょうか。そのようなことを分かるような工夫というのは必要だと思うのですけれども、そちらについてはいかがか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"１つ目の質問にお答えする前に、夜間休日対応をはじめ、委託の可否を検討しています。２つ目のケースの基本方針につきまして、児童相談所と子ども家庭支援センターの間で、設置区を見ながら考えているところです。","id":"exchange-014"},{"speaker":"安藤委員","kind":"質問","question":"線引きがなかなかできない点もあるわけですから、人事の、いろいろあると思うのです。そういったことも含めて、連携、交流のところはぜひお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"そういう手続前の相談みたいなことを既に始めておられるのか伺いたいのが１点と、マスコミとかでもいろいろ報道されていて、大変だと。バーンアウトしてしまう方もいると聞いているのですけれども、その辺についてどうなのか、伺いたいと思います。","respondent":"加島児童相談所移管担当課長","answer":"１点目の計画確認作業前の相談というところなのですけれども、今、定期的な情報共有を東京都とは図らせていただいているところです。２つ目の、こちらも既に設置されている自治体の話を聞きますと、そういった情報収集に努めているところです。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問・要望","question":"それはどうするのでしょうねみたいな、いや、その辺についてはしっかり話合いをしていただきたいと考えています。その辺もしっかりやっていただきたいのですが、このようなことで効果を上げたみたいな事例があったら伺いたいと思うのですが、いかがか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"やはり足元ですね。それから、そういったものを活用してまいりたいというのが、検討の過程の中で出てきているところです。","id":"exchange-017"},{"speaker":"吉田委員","kind":"質問・要望","question":"かつ、職員としても仕事が継続できるような体制を、区としてはぜひこれからも頑張ってやっていただきたいと。今はもうそれをお願いするしかないのですけれども、ぜひ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"松本委員","kind":"質問","question":"１点だけお伺いしたいのですけれども、２５人に対して１２人だと少し足りないのかと思うのですが、ここはいかがか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"こちらの児童福祉司の配置数３０人の中には、被措置児童虐待対応の児童福祉司の数を含めており、若干計算が合わない部分があります。","id":"exchange-019"},{"speaker":"松澤委員","kind":"質問","question":"それとも、もっともっといろいろなところとの連携の中で総合的に判断するのか。すみません、そこだけ説明を求めました。","respondent":"加島児童相談所移管担当課長","answer":"児童心理司による子どもの心理診断等、総合的な判断をした上で、子どもが家庭に復帰するかどうかというのを決定いたします。品川区として独自のアセスメントシートを開発していくか、今、検討中のところです。","id":"exchange-020"},{"speaker":"松澤委員","kind":"質問・要望","question":"その中で、先ほど吉田委員からも質問がありましたけれども、私も児童相談所の職員のメンタルというのですか。そういう部署というのは必ず必要だと考えていますので、そういったことを委託するか、そういったものをしっかりつくっていただきたいという要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"一緒にお仕事をして、自然な形でそのまま区立の児童相談所のほうで引き継いでいく、そういう流れでいいのか。最初、確認です。","respondent":"加島児童相談所移管担当課長","answer":"現担当者からの聞き取り、併せて都区担当者双方で家庭等に訪問させていただきまして、担当機関の変更を周知していく。そのようなものが、おおむねの流れとなっていると把握しております。","id":"exchange-022"},{"speaker":"つる委員","kind":"質問","question":"今度私が、誰それが何がしが担当しますという。そういうケースもあるのかと思うのですが、そのときの選別というのでしょうか、そういったところもあるのか尋ねました。","respondent":"加島児童相談所移管担当課長","answer":"今、現況を把握している限りなのですけれども、区が児童相談所設置市になりますと、品川区の子どもに関する措置権限が全て区のほうに移ってまいりますので、基本的に全てのケースを東京都から引き継ぐことになります。","id":"exchange-023"},{"speaker":"つる委員","kind":"質問・要望","question":"そうなってくると、当然ですが、開設した後も、他自治体への研修というのは、これはある程度続けていくものなのでしょうか。人材を継続的につくっていくという部分では、その後の研修というのもある程度考えているのか、教えてほしいと求めました。","respondent":"加島児童相談所移管担当課長","answer":"まさに１枚目の資料でマークを入れさせていただいたこの期間で、東京都と区と伴走的なケースワークを行っていきたいと考えているところです。２つ目の人材確保で、児童相談所は１つしか区の中にはございませんので、他自治体の交流という面も検討してまいりたいと考えております。","id":"exchange-024"},{"speaker":"つる委員","kind":"意見","question":"区の１つのセクションとなって、やはり開設後も、今の既存の職員の方とか新入職員の方も含めて必要になってくるのかと。いただいているＡ３の２枚目の通告窓口の既存のしながわ見守りホットライン、平成２２年ぐらいから設置されていて、無料化になっていますかとの意見を述べました。","respondent":"山下子ども家庭支援センター長","answer":"委員よりございましたしながわ見守りホットラインにつきましては、いわゆる「０３」発信の番号になっておりますので、今現時点としましては、無料通話とはなっておりません。","id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"いろいろ分かれると思うのですけれども、国のほうで、何年も前に「１８９」については無料化という。おっしゃっていたように「０３」から始まるのでというので、所管が違うので、予算特別委員会で伺っていきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問","question":"心理司とスーパーバイザーの目標の確保数に照らして何人ずつ今確保されているのかというのを伺いたいのと、どのように今考えていらっしゃるのか。少し特例的にこの分野については期間を延ばすとか、そういったことはどうお考えなのか、そこだけお願いします。","respondent":"加島児童相談所移管担当課長、山下子ども家庭支援センター長","answer":"こちら、児童相談所と子ども家庭支援センターと両輪の体制を考えておりますので、両機関に必要な職員の専門職の数として５割と申し上げました。ここについては多少所管が異なる部分もありますが… 児童相談所ならびに子ども家庭支援センターということで、一定、この業務に専門性があるところは、委員ご質問のとおりです。","id":"exchange-027"},{"speaker":"あくつ委員長","kind":"質問・要望","question":"ほかはよろしいでしょうか。安藤委員の質問に加えてなのですけれども、人員体制のところを私も伺いたかったのですが、ここについては資格は必要ないのか。","respondent":"加島児童相談所移管担当課長","answer":"こちらのほうでは、１日の中の２４時間３６５日、３交代のローテーション勤務が可能となるような人数をこちらで算出いたしました。一時保護所は確かにこちら１所しかございませんし、部内、庁内の全庁的な人事配置の検討が必要であると考えております。","id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/921668?Template=document&Id=5060#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":34383,"voices":87}},{"id":"r04-20220224-5","meetingId":"r04-cm02","date":"2022年2月24日","dateIso":"2022-02-24","committee":"総務委員会","time":"午前１０時００分～午前１１時２２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件整理しています。","topics":[{"id":"topic-01","title":"冒頭に申し上げたとおり、取り上げる順番を変更し、まず(5)住民税収納サービスの一部変更等","agenda":"冒頭に申し上げたとおり、取り上げる順番を変更し、まず(5)住民税収納サービスの一部変更等","exchanges":[{"speaker":"渡部委員","kind":"確認","question":"こういうふうになるのだなというのは確認したのですけれども、もう１回説明してほしいのは、1)2)の両方ともにかかってくるのですか。公金支払いのときはそもそも上限３０万円だったかどうかというのと、いわゆる決済手数料、もう１回そこを教えてほしい。","respondent":"提坂税務課長","answer":"決済手数料につきましては、約１％前後ということでご説明しましたけれども、金額区分により負担額が変わってございまして、従来のYahoo！","id":"exchange-001"},{"speaker":"渡部委員","kind":"質問","question":"それと、そういう方々に対して、今回仕組みががらりと変わってしまうわけだから、どういう説明が行くのか。この決済手数料がどうかかってくるかが大事だと思うのですけれども、どういうふうに考えているのか、お願いします。","respondent":"提坂税務課長","answer":"ポイントにつきましては、納付額によって若干ばらつきがありますけれども、実際には大体０.５％ぐらいつくということで聞いております。先ほども申し上げましたが、ホームページ、広報しながわ等で変更内容というものを分かりやすくご説明させていただきたいと考えています。","id":"exchange-002"},{"speaker":"渡部委員","kind":"意見","question":"Yahoo！できれば今度新しい住民税の納付書が送付されるときに、ある程度細かい説明みたいなのも入れてほしいと思うのですけれども、その辺のところも併せてとの意見を述べました。","respondent":"提坂税務課長","answer":"その中で、いわゆるキャッシュレスというのですか、コンビニ系の中の比率ということでは、若干多くありまして、約１５％です。裏面になるべく細かく説明は載せますけれども、同封するお知らせ等でなるべく分かりやすくご説明したいなとは考えてあります。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"増えている傾向にあるのでしょうか。どうなのか尋ねました。","respondent":"提坂税務課長","answer":"キャッシュレス決済ということですが、銀行、郵便局、区役所の窓口、コンビニ窓口の窓口納付が大体３５％、あと、口座振替が大体３０％なので、逆算しまして、大体全体の３５％ぐらいの割合です。","id":"exchange-004"},{"speaker":"田中委員","kind":"質問","question":"エヌ・ティ・ティ・データにもまたヤフーと同じようなサービスの突然の終了ということがあり得て、そのお知らせをまた区が区民の方にしなければいけないということが今後生じる可能性もあるということか尋ねました。","respondent":"提坂税務課長","answer":"４月１日からサービスが切り替わるということで、当面サービスが終了するということは考えてございませんけれども、長期的には絶対にあり得ないことではないと思いますが、そのときにはもちろん周知を徹底したいと思います。","id":"exchange-005"},{"speaker":"渡部委員","kind":"確認","question":"母数の確認ですけれども、特別徴収も含めた全体の納税者に対するパーセンテージという認識でよかったですか。普通徴収の中だけの話ではなくて全体のというイメージか尋ねました。","respondent":"提坂税務課長","answer":"これはあくまでも普通徴収の中での数字です。特別徴収は別の納入書を使って、各事業者の方からお支払いいただいている人です。","id":"exchange-006"}]},{"id":"topic-02","title":"固定資産税および都市計画税の軽減措置の継続","agenda":"固定資産税および都市計画税の軽減措置の継続","exchanges":[{"speaker":"おくの委員","kind":"意見","question":"これは前にも議論になったと思うのですけれども、物すごく長く続いている特別措置ですよね。なぜ恒常的な制度にならないのかみたいなことが、そこら辺の議論を簡単にでもご紹介いただければありがたいなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"}]},{"id":"topic-03","title":"最低制限価格の設定範囲の拡充","agenda":"最低制限価格の設定範囲の拡充","exchanges":[{"speaker":"おくの委員","kind":"質問","question":"対象契約を拡大していくのがたしかこれで３度目ですし、それから算定方法の見直しも二度やられて、とにかく制度が拡大してきていると。あるいは、そのときに考慮されている要素とかが一体どういうものなのかを伺えれば伺いたいなと思いまして、お願いいたします。","respondent":"東野経理課長","answer":"それにつきまして、検討を重ねた結果としまして、今日ご報告させていただいた内容となっています。そういったものです。","id":"exchange-008"},{"speaker":"おくの委員","kind":"質問・要望","question":"では、業者のご要望、あるいは具体的な状況を見ながらというような、大ざっぱに言うとそういう理解でよろしいか尋ねました。","respondent":"東野経理課長","answer":"大きくは請願が出たことに対しまして、区としてお答えしたということになります。そういった状況です。","id":"exchange-009"},{"speaker":"須貝委員","kind":"確認","question":"確認ですけれども、その中で、企業規模が違うではないですか。３番目の当該契約ごとにこの７５％から９２％の範囲において、契約担当者が最低制限価格を決めるというのは、区のほうで決めるわけではないか尋ねました。","respondent":"東野経理課長","answer":"その代わり、ここで言ういわゆる７５％以上の平均落札率で契約している、委員がおっしゃるのとはまた逆の傾向があったです。予定価格を事前公表しておりますので、あえてこういう７５％から９２％の範囲で、そのような措置を取っているものです。","id":"exchange-010"},{"speaker":"須貝委員","kind":"質問","question":"決めていくわけですから、より固定化されるというような心配もされるのですが、そういうことはないか尋ねました。","respondent":"東野経理課長","answer":"委員がおっしゃるような操作をしているという事実はございません。それから、落札業者が固定化されるということにつきましても、この制度を入れることによりまして、固定化されるということはないと考えています。","id":"exchange-011"},{"speaker":"たけうち副委員長","kind":"質問","question":"分かりました。こういう最低制限価格を設けて、ある意味ではしっかりやっていくというのは大事なのかなと思いますけれども、そういうことでよろしいか尋ねました。","respondent":"東野経理課長","answer":"特に支障はなかったということで聞いているところです。ただ、この目的とする労働者の雇用環境、そういったところを重視しまして、拡充に踏み切っておりますので、その辺をご理解いただければと思います。","id":"exchange-012"}]},{"id":"topic-04","title":"令和４年度組織改正（案）","agenda":"令和４年度組織改正（案）","exchanges":[{"speaker":"田中委員","kind":"意見","question":"１ページ目、地域振興部のところですが、なぜ八潮まちづくり担当がこの地域振興部の中に設置されるのか。八潮のまちづくりのソフト面ということ、なぜここに新設されるのかが分からなかったので、ご説明ほしいと求めました。","respondent":"佐藤（憲）企画調整課長","answer":"八潮まちづくり担当を設置する理由ですが、先ほどご説明したとおり、地域振興部のほうに設置をしております。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"なぜ土木のほうに、この八潮のまちづくりというのが設置されないで、地域振興部になったのかというのが、いまいち今の説明でも、ごめんなさい。私の理解が悪かったのか分かりづらかったのですけれども、教えていただけたらと思います。","respondent":"佐藤（憲）企画調整課長","answer":"建物を建てるという認識ではなくて、ソフト面も含めて考えていくという視点で、地域振興部の中に設置をするです。","id":"exchange-014"}]},{"id":"topic-05","title":"品川区総合実施計画の策定状況","agenda":"品川区総合実施計画の策定状況","exchanges":[{"speaker":"田中委員","kind":"質問","question":"前回の実施計画が第４次の２０１６年から２０１８年で、それからこれまでの間、総合実施計画がない状態で進んできたわけではないですか。そのときに、年度を変更しますなどの報告がどこかであったのかということも併せて教えていただけたらと思うのですが、いかがでしょう。","respondent":"佐藤（聡）計画担当課長","answer":"その後令和４年からの総合実施計画になったことにつきましては、なかなか計画的に事業が実施できないのではないかというところがありまして。","id":"exchange-015"},{"speaker":"田中委員","kind":"確認","question":"これまでも長期基本計画が変わる時期は、この総合実施計画の間隔が空いてしまっていたのかというところを確認したいです。","respondent":"佐藤（聡）計画担当課長","answer":"総合実施計画は、長期基本計画を実現するため、併せて策定しております。総合実施計画はないですけれども、その間総合実施計画はないですけれども、今回改めて長期基本計画の実現のために策定するという形になっております。","id":"exchange-016"},{"speaker":"田中委員","kind":"質問","question":"その間も総合実施計画の策定が止まってしまっていた時期があるのかどうかというのを伺ったので、そこのところをすみません。頂けますか。","respondent":"佐藤（聡）計画担当課長","answer":"以降総合実施計画も併せて改定を含めてやっておりますけれども、総合実施計画がない期間というのはこれまでもあったところではありますが。","id":"exchange-017"},{"speaker":"田中委員","kind":"確認","question":"例えば総務委員会などで、次の長期基本計画の関係から総合実施計画がつくれませんなどの報告は、どこかであるのでしょうか。そこのところを確認させていただけたらと思うのですが。","respondent":"佐藤（聡）計画担当課長","answer":"その後総合実施計画の策定までに期間があったということにつきましては、計画的に事業を進めることが難しいところがあってというお話につきましては、今回に限らずスケジュール的にどうなっていくのかというところは適宜ご報告しながら進めていきたいというふうに考えています。","id":"exchange-018"},{"speaker":"おくの委員","kind":"質問","question":"そこら辺はどう対応しているのでしょうか。伺いたいと思います。","respondent":"佐藤（聡）計画担当課長","answer":"変化に対応する区政運営の主な施策として、今回お示ししましたデジタル化の推進および新庁舎の整備についてかと思います。総合実施計画の方向性といたしましては、限られた資料ではありますけれども、ご説明するという形になっております。","id":"exchange-019"},{"speaker":"おくの委員","kind":"質問・要望","question":"指摘されている問題点への対応を盛り込むものにしていただきたいというふうに私は思いますということを述べておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"須貝委員","kind":"質問","question":"そして、商店街も大きく変化しているではないですか。本当にチェーン店化して、これからどういうふうにまちづくりをしていくのかというような取組みは、書かれていくようになっているのか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"先ほど、ご説明したアンケートもそうですけれども、１つは基本的なところで人口がどうなっていくかというところがあろうかと思います。","id":"exchange-021"},{"speaker":"須貝委員","kind":"質問","question":"本当に町の中が、うちの近くもそうですけれども、急激に変わっているのです。知らない間に「ここ確か４０坪５０坪のお宅があった」というところが急にマンションになったり、それだけ質問させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"たけうち副委員長","kind":"意見","question":"大体９割を超えてきて、１回９割を少し切ったかもしれないですが大体９割、８９％ぐらい。例えば、リモートが増えてもういいやというふうになったのかもしれないが、この辺りをどのように分析されていますかとの意見を述べました。","respondent":"佐藤（聡）計画担当課長","answer":"今住んでいらっしゃる方の定住意向については、影響がありましたけれども、まだ相対的には高い状況にあるというふうに考えております。２年に１度、区民世論調査をやっておりますので、そちらの数値を注視していく必要があるというふうに考えております。","id":"exchange-023"},{"speaker":"たけうち副委員長","kind":"質問","question":"８番の物価が高いからというのがあるのだけれども、一番数値が高いのは３番の４３.２％、住宅に不満があるから。そういった部分もしっかりどういう形にせよ入れ込んでいくのが大事なのかなと思うのですけれども、その辺のお考えはいかがか尋ねました。","respondent":"佐藤（聡）計画担当課長","answer":"住宅確保要支援者の方に対する支援というところをやっておりまして、そちらは総合実施計画のほうにも盛り込んでいきたいというふうに考えております。総合実施計画の導入の段階でも、もちろん年度年度の予算の段階でも、実現可能であれば実施したいというふうに考えております。","id":"exchange-024"},{"speaker":"渡部委員","kind":"質問・要望","question":"そのように確認をして、住み替えの意向に変化はありましたか」と聞いていて「分からない」が５６％、多分５０％ぐらいの人たちはそちらなのだと思う。ですから、これも要望だけですけれども、例えばこの問題を聞くことが適切じゃないでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-06","title":"令和４年度都区財政調整","agenda":"令和４年度都区財政調整","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"その対策を求めていらっしゃる方が増えているというお話も伺っていまして、コロナで格差は非常に拡大しているのだなということを思っております。その点に関する区の認識を、これをきっかけにもう一度お伺いしたいなと思ったのですけれども、いかがか尋ねました。","respondent":"黒田財政課長","answer":"当初見込みより税収が伸びてきたというところが、令和３年度の再調整の中で、そういった景気動向も含めて見込まれているというふうに認識しています。","id":"exchange-026"},{"speaker":"おくの委員","kind":"質問","question":"格差が拡大しているという認識について、お伺いしたのですけれども、その点はいかがですか。どうか尋ねました。","respondent":"黒田財政課長","answer":"あくまでも財調の原資、言わば固定資産税と法人住民税、特別土地保有税。この３税がいわゆる調整３税と言われている中で、当然収益が伸びているところに税はかかりますし、なかなか見えてこないというふうに考えております。","id":"exchange-027"},{"speaker":"須貝委員","kind":"質問","question":"その一部でも、もうマイナス何十億と出ているわけですから、将来に備えてくださいというようなことがあってしかるべきじゃないかなと思うのです。いやそれは２３区でそれぞれやってくださいというのは、将来にどうぞ積み立てて残してくださいと、見解だけ聞いていいか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"須貝委員","kind":"質問","question":"ただ、将来に備えていってほしいし、例えば市なら、地方自治体でもちゃんと国がふるさと納税のマイナス分を補填してくれるではないですか。意見だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/816435?Template=document&Id=2226#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":25771,"voices":106}},{"id":"r04-20220225-14","meetingId":"r04-cm02","date":"2022年2月25日","dateIso":"2022-02-25","committee":"行財政改革特別委員会","time":"午前１０時００分～午前１１時２８分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件整理しています。","topics":[{"id":"topic-01","title":"会議の運営上、予定表の順序を入れ替えまして、初めに、(2)新庁舎に関すること","agenda":"会議の運営上、予定表の順序を入れ替えまして、初めに、(2)新庁舎に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問・要望","question":"職員の使い勝手と言うのでしょうか、いろいろな場で聞き取られていると思うのですけれども、そういうものがまとまった形にはなっているのか。形になっていれば、出していただきたいなと、知りたいなと思うのですけれども、いかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"それをオフィスにどう生かしていくべきか、そういったことにつきましても、ワークショップの中で様々検討をしてきているところです。それから動線に関することにつきましてご説明させていただきましたが、働き方であるとか、資料を示しながら検討をしてきたいと考えていますので。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしたら、まとまった形というよりは、それぞれの出されている構想などの中に、もう既に声が入っているというふうな捉え方でいいのでしょうか。その辺のご検討をいただきたいと思うのですけれども、いかがか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"そういった移動等のお話につきましては、職員よりまず先に、区民がどういった移動を望んでいるのかという部分をまず考えていきたいと考えています。その後、職員の動線につきましても十分検討をしていきたいと思っているところです。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今分析中だから次の委員会でご報告ということでしたけれども、分析が終わって結果が出るのはいつ頃になるのか、教えていただきたい。お願いします。","respondent":"東野庁舎計画担当課長","answer":"次の委員会では結果をご報告したいと考えているところです。ご意見等が出そろってまだ分析を進めているところでして、そういった結果につきましても、併せて次回ご説明をさせていただければと思います。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"防災にもしっかりと役立つ、そして安全な庁舎にしていただきたいというのは、改めて申し上げておきたいと思います。代表質問等でも出されていたのですけれども、スケジュール感でいいのですが、いつ頃決まっていくものなのかというのを伺いたいと思います。","respondent":"東野庁舎計画担当課長","answer":"設計業者が決まってくるタイミングですが、令和５年度から令和６年度にかけまして、基本設計、実施設計を行っていくスケジュールになっております。基本計画で設計についてどういった手法を用いるか、その辺が固まってから決定する手続きに入っていきたいと考えているところです。","id":"exchange-004"},{"speaker":"石田（秀）委員","kind":"提案","question":"必ずこれはセキュリティも違うのでしょうから、感染症対策、やはり新しい庁舎には求められていくのだろうと思っています。ぜひこういうことも検討しながら、いろいろ提案をしながらやっていきたいと思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-005"},{"speaker":"あくつ委員","kind":"確認","question":"１点確認なのですけれども、現状の策定委員会の検討状況についてということでお伺いをしたのですが、今日はやるのでしょうか。それとも、先ほど報告のあった、環境とか、そういうところに限ってやったほうがいいのかというところで、お伺いをしたいのですけれども。","respondent":"つる委員長","answer":"前提として、事前にもお伝えしたとおり、この場で、その他の参考資料として配付していますので、その部分を含めて、ご提案とご意見等をいただきたいというふうに考えています。","id":"exchange-006"},{"speaker":"あくつ委員","kind":"確認","question":"そうすると、これから先も何回かこういう場があると。私どもは、項目立てをして７項目立てて出しているのですけれども、何か特筆すべきことを言うべきなのかどうかというところだけ確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"あくつ委員","kind":"質問・要望","question":"先ほどの報告のとおり、これから反映をご検討いただくという部分もあると思うので、幾つか確認をさせてほしいと求めました。もしこの場でお答えいただけるのであれば、今どういう方向性なのか、教えてほしいと求めました。","respondent":"東野庁舎計画担当課長","answer":"具体的に、食堂につきましては、次回３月の委員会でゾーニングについてお話をしたいと考えています。その中で、どういったゾーニングの中で食堂が要るのかどうか、そういったところも策定委員会の議論にしていきたいと思っているところです。","id":"exchange-008"},{"speaker":"あくつ委員","kind":"提案","question":"１つの品川区のアピールとして、こういうものを設置してはどうかという、１つの提案です。ぜひ参加をしたいというご要望もありますし、大きなものですから、ぜひこれは参加をしていただきたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"大倉委員","kind":"質問・要望","question":"環境に配慮した建物にしていただきたいということと、あとは食堂は、ぜひそうした利用が進むようにしていただければというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"須貝委員","kind":"意見","question":"やはり区民の皆さんや職員の皆さんが使い勝手がいい、利用しやすい、そういうような庁舎というのを基本的に考えてほしいと。やはり対応できるような庁舎機能にしてほしいと、それは添えてほしいというので、そういうものができればいいかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"せお委員","kind":"質問・要望","question":"私も聞いてほしいなと思っていて、全てお聞きした上で検討してほしいなというのは、要望であります。障害者の方たちの雇用という面でもすごく厳しいところがありますので、そういったところも含めて検討していただきたいと、要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"}]},{"id":"topic-02","title":"区有施設、公有地等の活用に関すること","agenda":"区有施設、公有地等の活用に関すること","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"それを伺いたいのと、保育園が想定規模として１,０００m2というふうに、この利用方針ではなっています。そうすると、４,６００m2を高齢者施設でというふうに考えていいのかというのを伺いたいと思います。","respondent":"佐藤企画調整課長、寺嶋福祉計画課長","answer":"私からは１点目のご質問の、現在検討しているということを、議会のほうにご報告させていただいているというところが１点目です。行政需要を検討した結果、４月１日現在で空きも出ているという状況がありますので… 保育園の１,０００m2の保有部分につきましてですけれども、検討が始まったというところで、今日の段階ではまだ未定ということになります。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"確認","question":"保育園がどうなっていくのか、高齢者施設がどうなっていくのかというのが、おおよそ決定していくのはいつ頃になるのでしょうか。ここは変わりなく想定どおり進んでいくということでいいのでしょうかという確認をお願いします。","respondent":"寺嶋福祉計画課長","answer":"今回、検討を始めるという部分につきましては、この間の行政需要が変化している可能性が十分にあるというところが出発点になってあります。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、全体的に検討しているというところだと思うのですけれども、要は、それが整う頃というのは、まだ分からないのか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"資料の３、今後の予定というところですけれども、現在検討中から令和４年８月頃を予定しているということで記載させていただきましたので。当然、この間に地域の方のご意見等もいろいろと伺いながら、この期間までに計画が策定できればというふうに考えております。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"この陳情第２号のほうですね。令和４年８月頃までというような、そうすると説明会はいつ頃になるのか、伺いたいと思います。","respondent":"寺嶋福祉計画課長","answer":"本日ご報告させていただきまして、今まさに検討中というところです。しかも８月頃までには基本計画を固めたいと考えていますので、その間ということに、しかるべき時期を見計らって行う予定です。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"小山台住宅等跡地の利用についての説明は、十分に行われてきたという思いでしょうか。その考えを伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"特定事件調査でもご説明したとおり、５月の説明会では９０名ほどの方にご参加をいただき、２時間ほどご説明をしています。区といたしましては、区民の方に十分説明を尽くすということは、これからも引き続き取り組んでまいる姿勢に変わりはございません。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"それが説明会でしっかり進むようにしていただきたいというのを改めて思いますので、ぜひお願いしておきたいと思います。それで、陳情第３号のほうの、伐採する木を最低限にということですけれども、今伐採している部分というのがあるのか、そこを伺いたいと思います。","respondent":"佐藤企画調整課長","answer":"先ほどの特定事件調査でもご紹介したとおり、令和４年１月から解体工事ということで、今囲っている状況で、木のほうはまだ伐採には取りかかっていないというふうに聞いております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"そうしますと、計画というか、解体等も進んでいくにつれて、伐採する木の本数というのはあるのでしょうか。ですので、そうしたことも考えると、より丁寧な説明が必要なのではないかと思うのですが、いかがか尋ねました。","respondent":"寺嶋福祉計画課長","answer":"今後の進め方については、委員ご指摘のとおり丁寧な説明、これはしっかり努めていくというところには変わりございません。この基本方針を定めて、公園拡張等も東京都が行ってくれるということで進んでいるという計画なので、その中でご理解をいただきたいと思っています。","id":"exchange-019"},{"speaker":"須貝委員","kind":"質問・要望","question":"説明会の案内と、きちんと説明会を真摯に開いて、これまで以上に気を遣って開いていただきたいと私は思います。以上で、意見だけ言わせていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"のだて副委員長","kind":"質問・要望","question":"検討中ですね、年度明けぐらいに説明会を行うというお話ですから、ぜひそういったところで説明会をやっていただきたいというふうに思います。移植とか、そういった計画があれば伺います。","respondent":"寺嶋福祉計画課長","answer":"繰り返しになりますが、まず緑を残すということにつきましては、全体計画の中でというところがまず基本的な考えになっているということ。全体の方針の中で、別途福祉ニーズに対する対応はしっかりやっていくと、こういったところでの全体の進め方になろうかと思います。","id":"exchange-021"},{"speaker":"芹澤委員","kind":"質問","question":"１つお願いとしては、これはしっかりと地域の皆様に、やるというお話をまずお伝えほしいと求めました。こちらで不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"塚本委員","kind":"確認","question":"説明をもっとしてほしいということだと思うのですけれども、それはスケジュールに則った形で、こちらの説明会をしっかりやっていただくと。これまで出ているように、説明会をやっていただけるということで確認がとれましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"せお委員","kind":"質問・要望","question":"８月までに説明会を行っていただくということですので、そちらに関しては丁寧に行っていただきたいと要望いたします。もし、こういったお話を区のほうが聞くことがありましたら、丁寧に誤解を解いていただきたいというところも要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"今回の陳情もそうですけれども、やはり住民への説明が品川区は大変不足しているなというのはずっと思っていましたし、その改善も求め続けてきました。そして幅広く、そうした説明会を、これを機に尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"須貝委員","kind":"意見","question":"私も、本日結論を出すということと、不採択でお願いしたいと思います。ですが、先ほども区のほうからもありましたが、きちんと今までどおり進めているということなので、それはご理解くださるようにお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。８月までには行っていくということで、ぜひしっかりと、より多くの方々に納得していただけるような説明会をしてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"芹澤委員","kind":"質問・要望","question":"恐らく方針としては、最低限にとどめるというお話かと思いますので、そこに関しても要望を満たされているのだろうと思います。かつ、緑を守るようにというところでもありますが、これも利用方針に入っているというような答弁もいただきましたので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"塚本委員","kind":"意見","question":"今の自民党の意見と全く同じです。必要以上にむやみに切るということも行われないということですので、特にこの陳情に関しては不採択でお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"せお委員","kind":"質問・要望","question":"公園を広げるなどして、また増えていくと思いますので、そちらで要望は満たされるのかなというところを考えております。今度イベントを行うというのも、すごくすてきな事業だなと思っていますので、そういったところも検討していただければと要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、ここもやはり説明が必要だなというふうに思います。同じ思いだと思いますので、ぜひ採択した上で、さらにご説明もお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"須貝委員","kind":"意見","question":"最小限の行為をして、皆さんのために利用できるような施設を作るということで、賛同しております。趣旨は分かりますが、その辺はどうぞご理解くださるようにお願いいたしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"大倉委員","kind":"意見","question":"こういうことも含めて、先ほどの陳情のほうでもありましたが、説明をしっかりしていただいて理解をしていただければいいと思います。丁寧な説明をしていただくようにお願いして、終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/474872?Template=document&Id=6124#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":25906,"voices":87}},{"id":"r04-20220228-19","meetingId":"r04-cm02","date":"2022年2月28日","dateIso":"2022-02-28","committee":"災害・環境対策特別委員会","time":"午前１０時００分～午前１１時０４分","status":"正式会議録","sourceType":"formal","overview":"災害・環境対策特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"おくの委員","kind":"質問・要望","question":"この協定を結ぶに当たって、どういう団体とどういう協定を結んでいったらいいかという、そこら辺はどうでしょうか。４番の今後の方針を見ますと、そこら辺、どうか尋ねました。","respondent":"山本防災課長","answer":"協定の方針ですが、より実効性のある協定を結べるようにというところで、区内事業者等との協定を締結するというところを大きな方針として今まで進めてきたところです。","id":"exchange-001"},{"speaker":"おくの委員","kind":"質問","question":"今後、協定として強化すべき部分などについて、今分かっている部分はどういった点でしょうか。お教え願えればと思います。","respondent":"山本防災課長","answer":"例えば、あとは帰宅困難者対策の一時滞在施設、そういったところはまだまだこれから区としても強化していかなければならないと考えているところです。きちんと区として体制等を今後考えまして、現状を分析して、新たな分野というところをしっかり精査していきたいと考えています。","id":"exchange-002"},{"speaker":"おくの委員","kind":"質問","question":"質問が分散して申し訳ないですけれども、そういうものを一つの文書にするようなご予定はあるのでしょうか。むしろ区がきちんと負担するぐらいの心構えでやっていくべきではないかとも思ったのですけれども、そこら辺、いかがか尋ねました。","respondent":"山本防災課長","answer":"１点目の文書化というところですが、具体的に検討等はしてございませんが、地域防災計画の修正等も予定しておりますので。それから入替えというのをお願いしていますけれども、そういったところの実費の部分は、きちんと費用負担をしています。","id":"exchange-003"},{"speaker":"おくの委員","kind":"質問","question":"費用負担の部分についても、ある程度積極的に考えていかないと、この協定の実効性、意味がなくなったりする場合も出てくるのではないかと思うのですけれども、その点、いかがか尋ねました。","respondent":"山本防災課長","answer":"おっしゃるとおり、協定の実効性を確保するというのは非常に重要だと我々も思っているところです。対応もしていただいているところですので、そういったお声が出れば、今時点では特にそういった部分は必要ないのかと考えています。","id":"exchange-004"},{"speaker":"おくの委員","kind":"質問・要望","question":"これから方針、どういうところの協定が必要かということを考えていく際は、協定を結ぶに当たって明確な方針の下にやっていただきたいという点と、それから、費用負担の点も十分配慮しながら、実効性を確保するようにやっていただきたいということを要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"吉田委員","kind":"確認","question":"私からも同じことを伺いたかったのですけれども、今の質疑の中身をもう一回確認させてください。意思のそごがないように、最低限の手続きが踏まれていると思ったのですけれども、その点について確認させてください。","respondent":"山本防災課長","answer":"署名をして、それを書類でやり取りして、きちんと協定を締結しています。文書化の部分は、区の方針としての文書化がまだきちんとされていないというところで、今後考えていきたいというところでご説明したところです。","id":"exchange-006"},{"speaker":"吉田委員","kind":"確認","question":"1)から6)までのそれぞれの協定の中身が、今日は具体的に示されていないですけれども、確認することはできるのでしょうか。伺います。","respondent":"山本防災課長","answer":"ほぼ同じような内容というか、書式も決まっておりまして、こちらについて締結をしていくというところでやっております。例えば、これと似たようなものを、地域防災計画の資料編という形でホームページ等で公開しています。","id":"exchange-007"},{"speaker":"吉田委員","kind":"確認","question":"公開しているというのと、議員として確認ができるというのは、少し性格が違うかと思うのですけれども、私としては、こういう協定を結んだ片方の当事者の議会として、中身の確認はしたいと思うのですが、その辺についていかがか尋ねました。","respondent":"山本防災課長","answer":"協定書の確認です。これまでそういった対応をしたことがないので、この中で情報公開等も含めて対応ができるのではないかと思いますが。","id":"exchange-008"},{"speaker":"吉田委員","kind":"確認","question":"やはり中身をきちんと確認した上で、改めてもう一回、その辺の見解を伺いたいと思います。このままでは確認できないかと思うのですが、具体的にどうしてもこういうことが必要であれば、その辺についても伺いたいと思います。","respondent":"山本防災課長","answer":"別紙の資料のところで協定名、協定先、こちらの内容について協定の締結をしているというところでご理解いただければと思います。説明は省略していますが、大前提として、当事者同士の合意が書面でなされているというところでご理解いただければと思います。","id":"exchange-009"},{"speaker":"吉田委員","kind":"質問・要望","question":"契約ほど強い拘束力というのですか、先ほどおくの委員からもありましたけれども、この協定の中身もぜひ議会には示してほしいと求めました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"こんの委員","kind":"確認","question":"何点か質問したいと思いますが、今、質問された委員と少しかぶるところもありますけれども、確認します。民間のどういったものを活用し、もっと強化しなければいけないという具体的な課題が見えているのか、その辺のところをお聞きしたいと思います。","respondent":"山本防災課長","answer":"この人は具体的にこの福祉避難所に避難する、また、区民避難所なのかというところの準備等を進めているところです。その計画を策定しながらも、こういった福祉避難所の拡大というところは、区としてもしっかり行っていかなければならないと考えているところです。","id":"exchange-011"},{"speaker":"こんの委員","kind":"質問・要望","question":"助産師会とはどういう協定というか、どのように関係、連携が図られているのか。そうした体制も、できれば協定を結んでおいたほうがいいのではないかと考えるのですけれども、いかがか尋ねました。","respondent":"山本防災課長","answer":"ただ、災害発生時の妊産婦の方への対応というところは非常に重要だと思ってあります。今考えているのは、緊急の医療救護所等に搬送して対応するですが、そういった対応がどれだけ取れるかというところがありますので。","id":"exchange-012"},{"speaker":"こんの委員","kind":"質問・要望","question":"まだ今は連携を取られていないということなので、徐々に連携を取っていただきながら、そうした体制も構築してほしいと求めました。どれだけ実効性、いわゆる供給量とか、そういうのはどうなっていらっしゃるのか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"冒頭のご説明にありましたとおり、年１度の協議確認書、そういったところの話合いをさせていただいているところです。できる限り、協同訓練なんかも実施して、どういった商品をどのような形でいつも持っているかといったところの確認をさせていただいているところです。","id":"exchange-013"},{"speaker":"こんの委員","kind":"確認","question":"年１回、そうした協議内容の確認をしながら、災害時に供給してもらう。そのことも年に１回の確認ということですが、あるいはこれだけできますということになっているのか、その辺も説明を求めました。","respondent":"平原防災体制整備担当課長","answer":"１つ目には、そういったことなども含め、様々な物資が１００％供給可能という状況にないことはこちらも把握しております。そういったところの知見も含めまして、民間事業者の知見を活かしつつ、公助と共助の両面から取組みをさせていただいているところです。","id":"exchange-014"},{"speaker":"こんの委員","kind":"質問","question":"そうしますと、１者２者３者、同じようなものをいろいろな事業者から少しずつ供給してもらうような体制を取っていくという考え方でいいのでしょうか。そういう理解でよろしいか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"ご指摘のとおり、様々な事業者と幅広く協定を締結することによって物資の量を確保するという考え方の下、進めております。で、東京都と品川区のそれぞれ役割分担といったところもそこで考えながら進めてまいりたいと考えています。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"なぜこのような形で増やすことができたのかという、その経過について伺いたいのですけれども、これは区から様々なところに働きかけたのか。どのような形で増えてきたのかということを伺いたいのと、３.３倍に増える中で、その点についても伺いたいと思います。","respondent":"山本防災課長","answer":"帰宅困難者の対応というところは、補完避難所等、そういったところを少しずつ増やしてきたというところで現状に至っているところです。避難所に来ざるを得ないというところで、そういった部分、避難収容の部分というところはこれからも充実させていきたいと考えているところです。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"何が足りないか、ここと協定を結んでいこうみたいな形で増えていったら、結果これだけになったという状況の捉え方でいいでしょうか。具体的なところで伺いたいのが、一時滞在施設開設訓練、協定を結んだところとどういう形でされているのかということについても伺いたいと思います。","respondent":"滝澤災害対策担当部長、山本防災課長","answer":"相互負担を進めているというものですので、自分たちが提供できるものは何かということが分かって、それぞれ協定がどんどん拡充してきたのが現状です。全て協定の力で災害時対応をするわけではなく、しっかりと仕分をしながら… それから、総合防災訓練につきましては、医師会や薬剤師会等にご協力いただきながら、訓練のほうにも参加をいただいているところです。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"こういう震災が起こったときに、これだけの量を品川区に供給できるということで確保しますという協定になっているということでいいのでしょうか。例えば、１７番の災害時等における簡易間仕切り等の供給に関する協定というのがありますけれども、例として具体的に教えていただけたらと思います。","respondent":"平原防災体制整備担当課長","answer":"一般の製紙工場、災害の状況に応じて工場を回して供給するというようなところで、こちらの団体がそういうルートをつくったというようなものです。ニーズ量をこちらの団体にお伝えして、運んできていただくというような中身のものです。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ということは、ここにある協定は、そのことによって新たな負担にはほとんどなっていない形での協定という考え方になるのか。そしてまた、そういうことで、具体的にそれがいざというときに足りるのかというあたりの考え方はいかがか尋ねました。","respondent":"平原防災体制整備担当課長","answer":"あるいは先ほどご説明させていただきましたとおり、一定量を確保していただくという内容の協定となってございまして、一定量の確保分の保管料を区が通常お支払いさせていただいているところです。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"議会から要求があったときにはぜひ出していただいて、私たちとしてもそういうことを考えられるようにということで、提供していただけたらと思います。さらに充実させていくということですので、ぜひそこの想像も含めてしていただいて、充実をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"たけうち委員","kind":"質問・要望","question":"５８番で、以前も少し要望させていただいた、そういった電源としてお借りするみたいなこともお考えになっていらっしゃるかどうか。もしくは、だけどこうなのだみたいなのがあれば、教えてほしいと求めました。","respondent":"山本防災課長","answer":"今後、そういった連携強化というところも含めまして、区としても対応等は考えていきたいと思っているところです。基本的に、そういった電源の確保の部分というところも今後対応等が必要になってくると思いますので、区としても考えていきたいと思ってあります。","id":"exchange-021"},{"speaker":"たけうち委員","kind":"質問・要望","question":"そういった時に補完避難所が必要になった場合の手順というのですか、そういったこともぜひやってほしいと求めました。時間の継ちかたによって違ってくると思いますので、その辺のものもつくられたらいいのではないかと思うのですけれども、いかがか尋ねました。","respondent":"山本防災課長","answer":"区としては、災害時の業務マニュアルの各災害対策対応の部分で、マニュアルごとに協定先とのやり取り等の手順等も載せているところではあります。","id":"exchange-022"},{"speaker":"たけうち委員","kind":"質問・要望","question":"今回、この特別委員会で、今まで我々も個別に把握していたものを、一括でこういう形で防災協定というのをやる意味は非常に大きいかと思いました。資料の３番でこれから全協定先との連絡先の確認を含めて、ぜひ頑張って進めていただきたいと、要望して終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"吉田委員","kind":"質問","question":"みんな困るのですけれども、この中での優先供給というのが可能なのでしょうかというのと、どのような協定になっているのか。内容、簡単で結構ですので、教えていただけないか尋ねました。","respondent":"山本防災課長","answer":"品川区だけではなく、都内全域ですので、なかなかこの１事業者だけでは対応が難しいのかと区としても考えているところです。基本的に特別区のほうで、こちらの１事業者だけではなく、区としてはそういった収集車の確保というのに努めていきたいと考えているところです。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"そうなると、今度、特別区の中での配分計画のようなものが同時につくられていると考えてよろしいのでしょうか。その補完として、品川区としてこの業者と優先協定を結んだという理解でいいか尋ねました。","respondent":"山本防災課長","answer":"具体的な計画というところ、マニュアル等、こちらは特別区が策定をするというところで聞いているところです。プラスで補完として、特別区の協定を活用していくというところで、収集は考えているところです。","id":"exchange-025"},{"speaker":"吉田委員","kind":"確認","question":"協定の中身をぜひ私たちは確認したいと思いますけれども、そういう努力を区としてしているということは、区民にも公表していただけたらと思います。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-02","title":"議会閉会中継続審査調査事項","agenda":"議会閉会中継続審査調査事項","exchanges":[{"speaker":"渡辺委員","kind":"意見","question":"今、資料を拝見して、非常に項目が整理されているので、このとおりにうまく進めていただければいいと思いますし、また、他の常任委員会の報告等も参考にしながら、正副でまとめていただいて、ここの項目立てが本当に行き届いているので、お任せしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"おくの委員","kind":"意見","question":"この主な意見の洗い出しというものですよね。もう少しサーマルリサイクルに関して、それが反映されていないような気がするのですけれども、これでは不十分かと私は思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-028"},{"speaker":"たけうち委員","kind":"確認","question":"確認というか、お聞きしたかった。（２）がないけれども、今日の内容が（２）ということですね。","respondent":"安藤委員長","answer":"そのとおりです。ほかはありますか。","id":"exchange-029"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"特別委員会ということで１年間やってきたわけですので、いつも特別委員会のほうからは、まとめという形で区のほうに提出するという形でしていますので、ぜひこの委員会でもまとめを提出していくということで、委員長、副委員長の言われた方向でぜひお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/781505?Template=document&Id=6610#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=19&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":19909,"voices":73}},{"id":"r04-20220302-3","meetingId":"r04-c-budget","date":"2022年3月2日","dateIso":"2022-03-02","committee":"予算特別委員会","time":"午前１０時００分～午後 ５時４３分","status":"正式会議録","sourceType":"formal","overview":"予算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を166件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"あくつ副委員長","kind":"質問","question":"１人当たりの質問時間は、２０分のいずれかとし、１日につき１０分となります。残り時間がなくなった時点で振鈴を２回鳴らしますので、質問の途中でありましても、直ちに取りやめていただきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"芹澤委員","kind":"質問","question":"私からは４７ページ、６７ページのオリンピック・パラリンピック開催周知事業で、レガシーについてお伺いをしたいと思います。今３回目の接種が年末から始まっていますけれども、この３回目の接種について、どういった効果が期待されるのかをお聞かせほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"まだ、受けていない方がいらっしゃるかもしれませんので、その辺りをどうするかということを今後検討していきたいというふうに考えております。３回目の接種につきましては、その辺りも含めまして接種を進めていくということで、全庁を挙げて体制を整えているところです。","id":"exchange-002"},{"speaker":"芹澤委員","kind":"質問・要望","question":"９０％とまた高い目標値を設定するのかお聞かせいただきたいということと、この３回目の接種が、それをお聞かせください。例えば６か月以降の３か月以内となって、あと、そのワクチンの効果がどうなるのかも併せて説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"ただ、この追加接種の事業が９月３０日までということになっておりますので、区としては全力を挙げて整えていきたいというふうに考えてあります。９月３０日までに打てるように、希望される方が打てるように、何とか体制を整えていきたいというふうに考えております。","id":"exchange-003"},{"speaker":"芹澤委員","kind":"質問・要望","question":"そういった方は９月末までの、この公表だと３回目の接種というのはできないのかなと思うのですが、そこの考えをお聞かせほしいと求めました。３回目に関しては、この効果の違いというものがあるのかお聞かせいただきたいということと、どういったご見解をお持ちなのか説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後もし延長等々があれば、それはそれで柔軟に対応していければというふうに考えてあります。追加接種を進めてまいりましたので、会場等々につきましては、今回は集団接種会場を少し限定的に運営をさせていただいたです。","id":"exchange-004"},{"speaker":"芹澤委員","kind":"質問・要望","question":"今の区が把握している５対５で進んでいるのかということをお聞かせいただきたいということと、恐らくバランスが取れないのだろうと思っています。１,０００人ほどの保護者にアンケートを取って、これはなかなか課題が大きいのかなと思うのですが、まず目標数を説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その中で、区内のモデルナ会場で打った方が約４万人いらっしゃいますので、大体半々ぐらいかなというふうには考えております。接種体制を整えていきたいというふうに考えてありますので、現時点では、特にこの数字まで持っていくということは考えてはございません。","id":"exchange-005"},{"speaker":"芹澤委員","kind":"質問・要望","question":"少し不便な部分も一部あるのかなと思うのですが、接種会場の選定について、どういった経緯だったのかをお聞かせほしいと求めました。小児接種を推奨する際に、医療的ケア児もぜひ優先的に接種するべきだというようなお話があって、どういったものがあったのか説明を求めました。","respondent":"有馬庶務課長、豊嶋新型コロナウイルス予防接種担当課長","answer":"子どもへのワクチン接種の学校への対応ですけれども、文部科学省から通知が来まして、それを学校に通知してあります。それから、具体的に何かをこのようにやっていきましょうということには、取組はまだしていないところです。集団接種会場等々につきましての設置の方法ですが、事前に医師会の先生方、どこで接種をするべきかということをいろいろ協議いたしました。","id":"exchange-006"},{"speaker":"つる委員","kind":"確認","question":"５歳から１１歳のワクチンについてでありますが、若干芹澤委員のほうからも質疑で確認されていたところがありましたけれども、まず予約です。ホームページを確認すると、３月７日以降から予約ということで提示があって、予約の開始時期もばらばらというようにホームページ上ではなっています。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"個別接種会場が実施しております予約方法につきましては、各クリニックの予約方法に準じます。もしくは１枠ずらした時間枠を希望すれば、あとはその接種会場で柔軟に対応することで、実施をしてまいりたいというふうに考えております。","id":"exchange-007"},{"speaker":"つる委員","kind":"質問","question":"予約のやり方はこれまでと、そのような意味では変わらないと思うのです。例えば５歳から１１歳のお子さんがいたときに、順番に打てるようになっているのか、もう１回それを説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もちろん接種医師もそこは認識をしておりますので、これからもお話をしてまいりますし、実際にそのように運用をしてまいりたいというふうに考えております。","id":"exchange-008"},{"speaker":"つる委員","kind":"質問","question":"それだけで１日大変なことになってしまうので、多胎のお子様についての対応は、しっかりとお願いしたいと思います。ドクターの手配もあろうかと思いますし、この接種時間については今どのようになっているのか、ここを説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"もしくは５歳から１１歳といっても、１１歳に近い方も含めて、今予約枠をつくっているところです。１５分で大体１人ないし２人ぐらいで接種が進んでいくもので、次回以降の予約枠の作成の際に調整をしてまいりたいというふうに考えております。","id":"exchange-009"},{"speaker":"つる委員","kind":"質問・要望","question":"薬剤師の方とか、ただスムーズにその辺に接種体制が進んでいくにあっては、接種の時間などについても工夫が今後求められるのかなと思います。ただキャンセルになってしまって、でもその日に打ちたいというときの全体の調整というものは、どこが担うのか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"１バイアル１０人、確かにきちんとうまくいけばいいのですけれども、当日のキャンセルであったり、いろいろな事象が出てくることは考えられます。どのようにするのが適切か、接種が始まってからも、様子を見ながら適宜改善をしてまいりたいというふうに考えております。","id":"exchange-010"},{"speaker":"つる委員","kind":"質問・要望","question":"ちょっと求めていた十分な答弁ではないのですけれども、また、これもやりながら考えていただきたいなと思います。そのようなこの辺のご指摘、アドバイスに対して、どのような工夫を今考えているのか説明を求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"集団接種会場の設置が、３月末からということで運用していくところです。現状、会場の下見が始まったところですので、今委員ご指摘のことも踏まえまして、会場設置で十分な体制に整えていきたいというふうに考えております。","id":"exchange-011"},{"speaker":"つる委員","kind":"質問・要望","question":"１日２日で収まる人、４日ぐらいは何となく様子見てくださいねなどということが、子ども向けの書面でも出ている。そうしたときに、その学習の支援という部分ではどのように今考えているのか説明を求めました。","respondent":"勝亦学務課長","answer":"副反応、コロナ等でお休みになっている児童・生徒への学習の支援としては、まずオンライン、ハイブリッドの授業等を行う等々で、可能な限り学習の継続支援をしていくような体制を整えてあります。","id":"exchange-012"},{"speaker":"つる委員","kind":"質問","question":"次に７３ページの産後ドゥーラ資格取得費用助成について伺いたいと思いますが、当初予算から見ると６６％強の執行率の現状ということで、品川区。２０２２年度予算については、当初比では１１２.３％の予算をつけていただいて、区としてどのように今受け止めているか説明を求めました。","respondent":"山下子ども家庭支援センター長","answer":"一定講習が修了しておりまして、７名の方のご申請をいただくということで、計１０名の方にご申請をいただいたところです。実際こちらの供給体制を拡充していくというところでは、一定受講につながりまして、こちらとしても大変うれしく思っているところです。","id":"exchange-013"},{"speaker":"つる委員","kind":"質問・要望","question":"残った時間で平和使節派遣費、ここを１点伺いたいと思います。一般質問でも伺いまして、今年度と前年度、昨年と一昨年という言い方でしょうか、交流が中止になってしまった。","respondent":"古巻総務課長","answer":"平和使節派遣につきましては、現地に行くという意味も大変大きいのかなとは思いつつも、様々な理由で行けないというケースも考えられますので、オンラインを含めて、様々な手法で効果が出るような形でのやり方を追求していきたいなと考えています。","id":"exchange-014"},{"speaker":"つる委員","kind":"質問","question":"区民の心の中にしっかりと平和の心を植えていくという意味での品川区の平和事業の推進を、しっかりお願いしたいなと思います。すまいるスクールのお弁当については、別の款でしっかりと伺っていきたいと思いますので、今日は以上で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"初めに４７ページ、新型コロナウイルス感染症の予防接種費についてお伺いいたします。１バイアル１０回、１０人接種可能ということで、どのように今進めていかれているのかということだけを１点お聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"それから希釈のやり方も全く違います。その辺りにつきましては、心配は特にはしておりませんが、そこについては大丈夫かというふうに考えております。","id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"確認","question":"分かりました。最後に１点だけちょっと確認したいというか、お尋ねなのですけれども、今後どのようになっていくのかということだけちょっとお聞きしたいと思います。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"その次が３月１７日に５８箱、２,９００人分が到着いたします。それ以降は、４月以降の配送という形になっております。","id":"exchange-017"},{"speaker":"高橋（伸）委員","kind":"質問","question":"続いて３７ページ、財政全般についてお伺いをしたいと思います。令和３年度の執行率ですが、これが今マイナス補正になっている中で、どの程度の執行率があるのかということをお尋ねしたいと思います。","respondent":"黒田財政課長","answer":"執行率につきましては、この補正予算の後に、年度末までの執行状況を勘案して、大体９５％の執行率を想定しています。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"行事ができないということも１つありますけども、やはり早急にやらなければいけない工事とか、工事だけではなくてもいろいろあると思うのです。対応方法というのですか、マイナスになったのだけれども、どのように対応していたということをお尋ねしたいと思います。","respondent":"黒田財政課長","answer":"補正予算の見積りに当たりましては、年度の予算ですので、３月までの執行見込みを、工事関係であれば出来高等も含めて、所管のほうで事業者と調整して、執行できるところまでを予算として計上するという形で、補正予算を編成しています。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問","question":"最後に６７ページ、経済センサス活動調査についてお伺いをしたいと思います。内容は大体把握しているのですが、これは毎年やっているものではないと思うのですけれども、そこのところを１点お尋ねしたいと思います。","respondent":"川島地域活動課長","answer":"こちらの経済センサス活動調査につきましては、５年置きに実施されるというものでございまして、平成２４年度から始めて今回３回目に当たるです。","id":"exchange-020"},{"speaker":"高橋（伸）委員","kind":"意見","question":"これはマイナス９００万円余というものが出ているのですけれども、大体あらかじめこの金額というものは分かっているかと思うのですが、このマイナス９００万円余というのはどのようなところでマイナスになったのかということをお尋ねしたいと思いますとの意見を述べました。","respondent":"川島地域活動課長","answer":"４１０人の予定で予算編成しておりましたけれども、２１９人の配置で調査が無事完了したということで、減額補正をするものです。調査のほうはしっかり行って完了しております。","id":"exchange-021"},{"speaker":"高橋（伸）委員","kind":"意見","question":"分かりました。この回答を区がアンケート結果をまとめて、何かちょっと見えないところがあるので、そこがどのようになっているのかお尋ねしたいと思いますとの意見を述べました。","respondent":"川島地域活動課長","answer":"地方公共団体の各種施策の政策立案、民間企業においても経営計画等に活用される基礎資料として、利用されているものです。","id":"exchange-022"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ぜひ今後も何か見える形で、ほかの関係機関、部署とも連携をしていただきながら、やってほしいと求めました。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"杉並区や世田谷区のように、区自らが区民がいつでも誰でも無料で受けられるＰＣＲ検査等の体制をつくることを求めましたが、区の答弁は。では伺いますけれども、区内ではどのようなところで、１日に何人の方が受けられる規模なのか伺います。","respondent":"鷹箸保健予防課長","answer":"ゲリラ的に、特に場所を公表せずに実施するという、その形で都から話を承っております。あるいは１日何人やるか、そういったことについても、特段区については報告は受けておりません。","id":"exchange-024"},{"speaker":"安藤委員","kind":"質問・要望","question":"常駐でやるべきだと私は思っています。都に求めてほしいと求めましたが、そちらについては１日何人の方が受けられ、どこでやっているのか伺いたいと思います。","respondent":"鷹箸保健予防課長","answer":"この薬局については、いわゆるチェーン店の薬局であったり、個人の薬局でやっていただいているという部分は理解しております。２か月程度かかるというところで、ふだんの調剤業務等が終わった後、多くても１日５人から１０人程度という形でお伺いしているところになります。","id":"exchange-025"},{"speaker":"安藤委員","kind":"質問","question":"１日にせいぜい二、今の感染高止まりの状況や区民のニーズから考えても、あまりに不十分だと。それなのになぜ都が行っていると区で実施しないということになるのか、これは区としても行う必要があると思うのですけれども、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"感染者の方への対応に一番力を注ぎたいと思っているところでございまして、そのような対応を駆使しながら、あくまでも感染者の方への対応に一番力を入れていきたいというふうに考えているところです。","id":"exchange-026"},{"speaker":"安藤委員","kind":"質問・要望","question":"質問しますけれども、ＰＣＲ検査は有効であると、拡大すべきであるという立場に認識が変化したということなのでしょうか。伺います。","respondent":"鷹箸保健予防課長","answer":"これまでの認識を変更したということではございません。あるいは障害者施設等の従事者については定期的に実施しているところですし、その方針については、その方針で進めるということで。","id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"世田谷区ではこうしたことをやっているわけですが、区はなぜそうした立場に立たないのか伺います。今からでもその体制実施を求めますが、いかがか尋ねました。","respondent":"鷹箸保健予防課長","answer":"特にここ数週間の中で、高齢者への感染が改めて広がっている現状の中、重症化されている方もいらっしゃいます。そういった方が自宅療養をされている場合もありますので、感染者への対応に注力していきたいと思います。","id":"exchange-028"},{"speaker":"吉田委員","kind":"質問","question":"７６ページ辺りに見えています都支出金の減について、７６ページ、７７ページの保健予防費について伺います。なぜ一般財源を減らしたのか、そして減額した一般財源はどうなったのか、併せて、答えるよう求めました。","respondent":"黒田財政課長、崎村人事課長","answer":"一般財源の減額のところです。その分一般財源が予定したところがつかなくなるというところ、この財源は、この財源を何かに特別に充てて使っているというところではございません。令和３年度当初予算につきましては、令和２年１０月１日現在の職員数を基に、令和３年度の各課職員給与費を算定していたところです。","id":"exchange-029"},{"speaker":"吉田委員","kind":"質問","question":"必要なお金、当然いずれ庁舎建て替えは必要なわけですから、そのようなものについては当初予算で検討すべきだったのではないでしょうか。同じような質問をさせていただいているのですけれども、改めて最終補正で３０億円という多額を１つの基金に積み立てる考え方について見解を伺います。","respondent":"崎村人事課長、黒田財政課長","answer":"７７ページの保健予防課の職員給与費の雇用形態というご質問なのですけれども、常勤職員と会計年度任用職員の給与費の部分になってあります。人事課の６３ページのところで、代替職員雇用経費といったことで… 庁舎の整備の必要性が検討されまして、起債等の活用も検討しておりますが、補正予算として３０億円を計上させていただいたところです。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問・要望","question":"地方財政法第７条でしたか、繰越しが、剰余金が出たときにはその半分ぐらいは積み立てるべきということを、前の議論のときにご答弁で伺いました。その辺についても伺いたいと思います。","respondent":"黒田財政課長、川島地域活動課長","answer":"改めて資金の計画を明らかにするというところで基金を設置して積立てするというところでございまして、令和３年度の補正予算とさせていただいたです。そういった一般財源が増えたことによりまして… 区民活動助成制度のところですが、こちらは歳出の部分、当初予算５００万円あったものが、応募数が少なかったため、４００万円減額するものです。","id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほど別の委員からご質問ありましたけれども、しながわネウボラネットワークのことで、産褥期への支援が減っていることが大変気になっております。この減額の要因について、ちょっともうあまり時間がないのですけれども、ぜひ時間のある限りお答えいただけたらと思います。","respondent":"寺嶋福祉計画課長、宮尾高齢者福祉課長、山下子ども家庭支援センター長","answer":"１６節から１９節の３つ、残念ながら令和３年度は該当の事業者がなかったので、減額補正という形になってあります。私からは高齢社会対策事業のマイナス減額についてお答えをいたします。こちらは、今年度八潮南特別養護老人ホームに導入を予定しておりますＩＣＴシステム… ある意味最大のところを見込みまして予算編成に臨んだところですけれども、実態としまして、このような減額の結果となったところです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"需要を満たしつつあるとしてのマイナスなのでしょうか。それとも他の要因があるのか伺いたいと思います。","respondent":"若生保育支援課長","answer":"こちら開設数が、当初見込んでおりました開設数よりも少なくなったというところでの減になってあります。これは開設予定だった園を３園ほど減らしているところなのですけれども、そのうち１園は、当初予定していなかった土壌汚染等が発生したことによって。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問・要望","question":"どう条件が合わなかったのか伺いたいところですが、ちょっと時間がないかなと思います。そのようなことで、条件が合わないということで区が求める質までに至っていなかったのだったら、それは無理に開設すべきではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこから約１か月半強が経つ現時点ですけれども、６５歳以上の接種率、また、現在の接種実績について、どのような状況なのかお聞きしたいと思います。今回の追加接種は、１回目、２回目の接種実績と比べて、その進み具合、どのような状況と捉えているのか、現状をお聞かせほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"６か月の前倒し等々も含めまして、１月２１日より集団接種会場を開設しまして、接種を実施してまいりました。そういった意味では、現在、区の想定どおりというか、考えていたとおり順調に進んでいるものというふうに考えております。","id":"exchange-035"},{"speaker":"こんの委員","kind":"質問・要望","question":"おおむねモデルナも予約を埋めながら進めてくださっているということが確認できました。そうした声も伺っている中ですので、２回目を終えた、現状をお聞かせほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"およそ２１万人の方がファイザーのワクチンを打っておりますので、大体３分の２程度、約７割弱の方がファイザーを打っていると。ざっと７割弱がファイザーで、それ以外がモデルナという形で、初回接種は終了いたしました。","id":"exchange-036"},{"speaker":"こんの委員","kind":"質問・要望","question":"配分されているか、現在配分されているモデルナ製とファイザー製の供給割合については、どのようになっていますでしょうか。今後のスケジュールなども、参考のために教えてほしいと求めました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"今後来ることが決まっているワクチンも含めますと、およそになりますが、４５％がファイザー、５５％がモデルナという形になっております。３回目、追加接種の際は、前倒し接種でモデルナワクチンを使っていたです。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問・要望","question":"私どもとしては、６か月に接種を前倒したのであれば、ワクチンの配分も前倒して供給をしていただくように要望しているところであります。いま一度区として、このタイミングを見ながらするのは大変だと思いますけれども、そのところの対策というものをいま一度確認させてください。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"モデルナは集団接種会場で主に使っているワクチンです。初回接種でも行いましたように、他区との合同接種ということも行ってまいりましたので、検討をしてまいりたいというふうに考えております。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"抗体の降下率というのでしょうか、区民の方にモデルナも有効なのだということをお知らせをしていただきたい、このように思います。一応９月まで、この情報発信に努めてほしいと求めましたが、ご答弁お願いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"皆さん関心が非常に高いものというふうに我々のほうでも認識しておりますので、今後も引き続き、鋭意進めてまいりたいというふうに考えてあります。","id":"exchange-039"},{"speaker":"こんの委員","kind":"質問・要望","question":"そこで、当初のスケジュールから、完成までのスケジュールはずれ込むということになってしまうのでしょうか。そうしたお声もきちんと対応していただきながら、完成を予定どおり進めていただきたいと思うところですが、現状を説明を求めました。","respondent":"高梨公園課長","answer":"年度末の完了というスケジュールは変わらずに、４月上旬の開園に向けて、現在予定どおり進めているところです。周辺の皆様にも、その辺のご案内のほう、丁寧にさせていただきたいと、このように考えています。","id":"exchange-040"},{"speaker":"こんの委員","kind":"意見","question":"様々、近隣の方への対応を細かくやってくださっていることは承知しておりますので、引き続き双方が、区民の公園として区民の方が使える、その公園の整備について、ご苦労でしょうけれども、よろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"西村委員","kind":"質問","question":"４７ページ、７４ページ、コロナウイルス感染症における保育現場の現状について伺ってまいります。濃厚接触者や陽性者が保育園にいた場合、個別の家庭の連絡は園がやり、保健所にまとめて連絡をしているかなどをお伺いいたします。","respondent":"若生保育支援課長","answer":"保健所による行政検査というものは実施しておりませんが、保育課および保育支援課が保健所と連携いたしまして、ご案内をしています。保育課および保育支援課のほうから園に聞き取りを行いまして、保健所と連携しまして、濃厚接触者を特定して園に通知いたします。","id":"exchange-042"},{"speaker":"西村委員","kind":"質問・要望","question":"コロナ禍で従業員が足りず、保育基準を下回ってしまうというような相談ですとか、事例、休園する園はあったでしょうか。感染者が出た場合の区や保護者、内部などへの連絡ですとか、事務手続にも、イレギュラーな多くの時間を要すると保育現場より伺っております。","respondent":"若生保育支援課長","answer":"第６波の広がりを受けまして、区内の保育園の保育従事者に対する３回目のワクチン接種の優先予約制度についても、２月９日から開始しています。心身ともにリフレッシュができるよう、環境整備を今後も充実してまいりたいと考えております。","id":"exchange-043"},{"speaker":"西村委員","kind":"質問・要望","question":"続きまして、私立認可、認証、小規模園などの在り方と、保育園の形態に合わせて、それぞれの課題をお伺いしてまいります。昨年度４０点以上でないと入園できなかったところが、今年度３０点台でも入れたと、区民の方より伺いました。","respondent":"若生保育支援課長","answer":"こういった検討会の結果なども区としても参考にさせていただいて、こういったこともスペースの活用というところでは有効な方策の１つと考えています。今後、他自治体の先行事例なども参考にしながら、研究してまいりたいと考えています。","id":"exchange-044"},{"speaker":"西村委員","kind":"質問","question":"小規模園が大変な状況を伺いますと、国の補助が１人単価で換算されるので、小さな園は園児が１人でも入園しないと経営が圧迫されると伺っております。小規模園の保護者が３歳児の壁に悩まないで済むように、この際に、区内に８園あると伺っております。","respondent":"若生保育支援課長","answer":"保育園と同じ時間帯まで預かり保育を実施している園につきましては、８園ございまして、窓口等でご案内しています。区が関与していないところでありますので、何らかの形で連携できるような方策、こちらは区としても考えてまいりたいと思います。","id":"exchange-045"},{"speaker":"西村委員","kind":"提案","question":"幼稚園も含まれてくると、親御さんにとっても混乱している部分があるのではないかというところ、ご提案させてほしいと求めました。入園検討段階でホームページや窓口案内で活用していただきたいと思うのですが、こういった新しい取組に関しまして、区の見解を説明を求めました。","respondent":"立木保育課長","answer":"ただ、チャートのようなものをご用意していませんので、これは例えば他の自治体等のものを参考にしたりなどして、研究をしてまいりたいと思います。当面は、より一層丁寧なご案内ということを心がけたいと考えています。","id":"exchange-046"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本日は、補正予算書４７ページの新型コロナウイルス感染症対応地方創生臨時交付金から、子どものコロナウイルスワクチンについてお伺いいたします。本日はまず、今月から開始されることになった小児用コロナワクチン事業についてお伺いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"２０２２年１月の新規感染者では、全体のおよそ４分の１が１０歳代以下という統計も、厚労省のホームページから拾うことができます。２０２２年１月２１日に、５から１１歳を対象とした小児用新型コロナワクチンが薬事承認をされまして、接種が始まることとなりました。","id":"exchange-047"},{"speaker":"鈴木（博）委員","kind":"質問","question":"アメリカに引き続いて、日本でも子どもにおいて新型コロナウイルスの流行がだんだん増えているという現状が、今お話を伺って理解できました。区の責務として、小児用コロナワクチンに対する正しい情報の提供をどのように進められるおつもりなのか、お伺いいたします。","respondent":"豊嶋新型コロナウイルス予防接種担当課長","answer":"各ご家庭で判断をするために必要な客観的な情報の提供が不可欠と考えておりまして、Ａ４、送付をいたしました。他区、他自治体のホームページも参考にしながら、様々研究をしていきたいというふうに考えております。","id":"exchange-048"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"このようなことも検討すべきと考えますが、区のお考え、取組はいかがでしょうか。これに対する取組なども、教育委員会のご見解としては、ご検討としてはいかがか尋ねました。","respondent":"豊嶋新型コロナウイルス予防接種担当課長、有馬庶務課長","answer":"東京品川病院、それから東邦大学医療センター大森病院などの感染症の専門家等の先生方のご講演につきましては、可否について、今後先生方とご相談の上、検討してまいりたいというふうに考えております。児童・生徒へのワクチン接種については、保護者の同意を得ることが重要だということは通知にも書いてあります。","id":"exchange-049"},{"speaker":"鈴木（博）委員","kind":"質問・要望","question":"いろいろ悩み、心配されている多くの区民の保護者と子ども本人に、区としても最大限親身に寄り添っていただきたいと心からお願いしたいと思います。教育委員会、子ども未来部も含めて、全庁で対応することを強く要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７７ページの生活困窮者自立支援事業についてと、４７ページの都補助金、エッセンシャルワーカーの抗原検査キットの活用について伺いたいと思います。この申込みが２月７日から３月１８日までということで、区が把握をされているのか、把握していたらその数についても伺いたいと思います。","respondent":"宮尾高齢者福祉課長、有馬庶務課長","answer":"一時的に休止等をした事業所数ですが、第６波を受けてというところでいいますと、全て通所系の施設で５か所というふうになってあります。ただ、日々の中で聞いているところでありますと… 取りあえず今のところ２校、これは２月の半ばの情報ですけれども、２校が申込みをしたという情報は得ているところです。","id":"exchange-051"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"締切りが３月１８日までとなっているので、周知をさらにしていただきたいということと、把握をするという考えについてはいかがでしょうか。そのようなところで、見逃すことがないようにという点でも、周知の工夫もぜひしていただきたいと思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"復帰するに当たって、待機期間の明ける前に、２日間続けて抗原検査キットで陰性を確認して復帰をするという対応をしているそうなのですけれども。それからＮ９５マスクや防護服などを現物支給するか、区としてぜひ支給していただきたいと思うのですが、いかがか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"あるいは随時、お声をいただいたときにお配りをさせていただいたりということも組み合わせて、支援をさせていただいているです。臨時的に、例えば一時的に少し検査キットが欲しいというようなニーズにお応えするために、先週から希望する事業所に対してお配りをしています。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"Ｎ９５ですとか、何というのですか、製品として出されるという仕組みになっているということなのでしょうか。そのようなことでご要望を伺ったのですけれども、検査キットも配っていただけるということで、その確認をお願いしたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"補助金につきましては、東京都の補助要綱を見ますと、ヘルパーステーションも当然ながらご利用いただけるという制度設計になっているかと思います。東京都の週１回の定例的な活用もお願いすると同時に、お配りをする、このようなことも支援をさせていただいているところです。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"それであれば、それを事業者が活用できるようにということで、周知もお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問・要望","question":"ここで一気に５倍にもなった、自宅療養も１,２４５人に、１０倍以上ですか。逆に、そういった派遣職員では行えない業務はどのようなものか、確認をさせてほしいと求めました。","respondent":"鷹箸保健予防課長","answer":"考えつつ対応してきたですが、２月１日からは、もう年齢に応じて健康観察の方法を変える。職員の対応の違いですが、電話対応が終わった後に、応援職員を中心に電子カルテにその日の対応内容を夜遅くまで残って入力していただいて。","id":"exchange-056"},{"speaker":"若林委員","kind":"確認","question":"それは１つ確認をさせていただいて、そのような体制については、この１年間どういう強化をされてきたのかと。こういった第６波、今後ＢＡ.２というのですか、そういったものも懸念をされております。","respondent":"鷹箸保健予防課長、古巻総務課長","answer":"特に第６波におきましては、度重なる国および都の変更に対して、日々対応しています。 ＢＣＰに関しましては、今第６波のいろいろな応援体制の中で、どういった対応を庁内で取ったらいいのか、その辺りも含めまして、今まさに現在進行形で検討しています。","id":"exchange-057"},{"speaker":"木村委員","kind":"質問","question":"大変この質問も難しいのですが、それとも、それほど労力と費用は必要ないのでしょうか。そして、過去にこのような前例などがあったのかどうか、そのようなことも説明を求めました。","respondent":"黒田財政課長","answer":"コロナ収束後の事業展開というご質問ですが、令和４年度当初予算におきましては、コロナ収束を見据えた予算編成としておりますので、そういった意味では、費用については予算としては計上させていただいているところです。","id":"exchange-058"},{"speaker":"木村委員","kind":"質問","question":"この一、二年間の事業の休止状態から本来の姿に戻るには、どれぐらいの労力と時間が必要でしょうか。説明を求めました。","respondent":"黒田財政課長","answer":"１つイベント事業ですと、そういったところをどのようにしていくかというところは、費用とは別に問題としてあるのかなというふうに感じております。","id":"exchange-059"},{"speaker":"木村委員","kind":"質問","question":"高齢者が幅広く社会に溶け込むこと、溶け込むという意味もあると私は思っていますけれども、この事業の真の目標はどこに置いてあるのでしょうか。医療の進歩などにより健康寿命が延びることで、これからの目標はどのようなところに置くのか、お考えを説明を求めました。","respondent":"菅野高齢者地域支援課長","answer":"６９ページの高齢者社会参加促進事業のマイナスの補正についてのお答えを、私のほうからします。９月に開催をさせていただいたのですが、無観客によるオンライン開催という形の新しい試みもさせていただいた次第です。","id":"exchange-060"},{"speaker":"木村委員","kind":"質問・要望","question":"考えやアイデアが活かされるときがやってくると思いますけれども、このことに対して、本区の理事者の皆さんはどのようにお考えでしょうか。高齢者の皆さんがこれからも頑張っていただくことを心から願っている１人でありますが、どうぞお答えをほしいと求めました。","respondent":"菅野高齢者地域支援課長","answer":"やはり高齢者の方が元気よく活躍していただくことは、今までの知見やそういったものも活かして、よりよい社会になると思います。そして介護予防の推進になると考えていますので、そういったところが少しでも活発に活動できるように支援していきたいと考えているところです。","id":"exchange-061"},{"speaker":"木村委員","kind":"質問・要望","question":"力強いそのお言葉、大変うれしく思います。家族、そして社会が１つになって、これからの高齢者をしっかりと守っていただきたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"松本委員","kind":"質問","question":"私からは、５５ページ、子どもの未来応援事業、７３ページ、同じく子どもの未来応援事業について伺います。この指定寄附金の制度の仕組みが、この追加で出てくる３００万円などというものは、あるいは会計上どのように計上されていくのかをご説明ください。","respondent":"伊東子育て応援課長","answer":"一応１２月末までに寄附をいただいて、それが食の支援ということで、しあわせ食卓事業のほうに活用させていただいているというのが現状です。予算的には５００万円と組んでいますけれども、８００万円余の寄附が集まったという状況です。","id":"exchange-063"},{"speaker":"松本委員","kind":"質問","question":"そうすると、例えば今回３００万円だったわけですけれども、これが物すごく多額に寄附が集まりましたなどという場合には、その寄附を受けたものというのは、どのタイミングでどのような使われ方をしていくというように考えればいいのか尋ねました。","respondent":"伊東子育て応援課長","answer":"企業などから品物の寄附があった場合等に関しましては、その配送料等に関しては、こちらのほうで費用を持つというような形を取っております。そのような形で年に数回、令和３年度でいいますと、年に数回配布をしたという形で使われていくということになります。","id":"exchange-064"},{"speaker":"松本委員","kind":"質問","question":"その辺が会計の仕組み上、なかなか難しいのですけれども、１２月に結構集まったわけですよね。そうするとちょっと何か、あまり予算上に計上されていないようにも見えるのですけれども、この辺りの仕組みというのはどうなっているのか尋ねました。","respondent":"伊東子育て応援課長","answer":"基本的には、当初予算上５００万円と組んでいましたけれども、実績としては８００万円とか、昨年でいえば９００万円という形になってあります。実績としては、やはり入ってきたお金の部分に関しては、支出するというような形になってあります。","id":"exchange-065"},{"speaker":"松本委員","kind":"質問","question":"では、想定よりもたくさん入れば入るほど、たくさん使えるというように理解してよろしいか尋ねました。","respondent":"伊東子育て応援課長","answer":"ここ２年、３年やってきておりますけれども、翌年以降は上回る寄附があったところです。それに関しては、年度内に使い切るという形で支出しております。","id":"exchange-066"},{"speaker":"松本委員","kind":"確認","question":"やはり寄附をした方から、どのように使われているのかということを聞かれることも多いので、確認をさせていただきました。明日以降、令和４年も５００万円と維持しているのですけれども、この辺りはいかがお考えか尋ねました。","respondent":"伊東子育て応援課長","answer":"３００万円からスタートしたわけなのですけれども、その後５００万円、５００万円で来てあります。ちょっとコロナの関係ですとか、現状維持ということでもございませんが、５００万円ということで予算要求させていただいています。","id":"exchange-067"},{"speaker":"松本委員","kind":"質問","question":"これをふるさと納税でやるのはどうかと思うというような感じもあるというか、知識、自分の実感としてほとんどない。あれは区民向けなので、もっと区民の方もできますということを強調していただいてもいいのではないかなと思うのですけれども、いかがか尋ねました。","respondent":"伊東子育て応援課長","answer":"発信していくことは必要かなと思っていますので、その辺はなお一層、ちょっと工夫しようかなというところではあります。区民も全然オーケーなのですよということで、それを広めてもらう意味で、その時々の会合等でお話はしています。","id":"exchange-068"},{"speaker":"松澤委員","kind":"質問","question":"補正予算書の６７ページ、品川区独自ボランティア「しな助」の活動、そして８５ページの密集住宅市街地整備促進事業についてお聞きいたします。今回この減額補正を計上している用地取得費、これについて当初の考え方と、減額に至った経緯を説明を求めました。","respondent":"森木密整備推進課長","answer":"広場用地として２か所、道路用地として５か所の取得に関する経費として、９,６００万円余の予算をいただいておりました。地権者との交渉が進まなくて、年度内の取得の見込みが立たないというところでございまして、今回減額補正を計上しています。","id":"exchange-069"},{"speaker":"松澤委員","kind":"質問・要望","question":"人と人の話合いのあることですから、事業の目的から手続の方法まで丁寧な周知をしていただいて、理解を得ながら進めていただきたいと考えています。この開放広場の今後の予定、これを説明を求めました。","respondent":"森木密整備推進課長","answer":"この児童遊園の隣の土地も、ＵＲがまちづくり用地として取得しておりまして、この街区の中で広場用地が点在しているです。そのため、地域として一体的な広場整備ができないかということで、周辺の地権者の方へも声をかけさせていただきながら、ご意向を確認しています。","id":"exchange-070"},{"speaker":"松澤委員","kind":"質問・要望","question":"防災性向上の１つとして、この地域からずっと要望があります、消防団が常に必要としています格納庫の設置があると思っています。開放広場を今後防災広場として整備していく中で、消防団の格納庫の設置というものは、まず可能なのかどうか、ご見解をお伺いいたします。","respondent":"森木密整備推進課長","answer":"今後、ある程度方向性が見えたところで整備の検討ということを本格的に進めていくということになると考えておりますが、それぞれご意見を伺いながら。設置の要望があった際には、地域の意見を聞いて、設置の可否等について検討をしていきたいというふうに考えております。","id":"exchange-071"},{"speaker":"松澤委員","kind":"質問・要望","question":"十分に要望を聞きながら、いろいろと対応して、必要な設備について検討していただければと考えています。これは主に東京オリンピック・パラリンピックが無観客となったために出たマイナスというものか、当初の考え方と減額に至った経緯を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおり、夏の東京２０２０大会、無観客となった関係上、しな助の活動の機会というものが大幅に減少してしまいました。そのことによる減額です。","id":"exchange-072"},{"speaker":"松澤委員","kind":"質問","question":"今回ちょっとしな助に対しては随分しつこく質問してしまいましたが、一体どのような話合いがあって継続に至ったのか、この経緯の説明をお願いいたします。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"東京２０２０大会の機運醸成のイベント等で、大会が終了した時点でもうその役割は終わりということで、終了する予定でございました。今後もさらに活動の機会を提供しながら、また研修の機会もつくりながらやっていこうということで、一旦継続ということに決めたところです。","id":"exchange-073"},{"speaker":"松澤委員","kind":"質問","question":"今回のオリンピック・パラリンピックの運営に関わったこの満足度、これは７割を超えたという調査結果が出ております。それともスポーツボランティアでやっていくのか、また期日といいますか、これからの方向性というものを説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"ボランティアマインドを醸成するような研修ですとか、またリーダーシップをもうちょっとつけていくような研修等も、併せて行うような予定です。そして、大体２年程度を目途に力をつけていただいて、しな助のほうは解散したいというような、そのような予定でおります。","id":"exchange-074"},{"speaker":"松澤委員","kind":"質問","question":"このボランティアセンターの中の品川区地域貢献ポイント事業というものがあるのですけれども、この対象者は６０歳以上とあったのですが、この年齢制限がある理由というものを説明を求めました。","respondent":"宮尾高齢者福祉課長","answer":"男性２６％、女性７４％ということで、女性が多くなっているところです。それから年齢構成ですが、中心は６０代、７０代の女性が、全体の大体半分近くを占めていると、このような状況だというふうに聞いております。","id":"exchange-075"},{"speaker":"松澤委員","kind":"質問","question":"何というのですか、研修であったり、このようなものは本当に必要だと思っています。ただ紹介するのではなくて、そういったような専門性を持った活動を支援していくべきではないかと思いますけれども、ご見解を聞かせてください。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"卒業していろいろな面で活躍していただくためにも、そういった専門家の方と連携をしながら、いろいろな方向性を決めていきたいと思っています。一緒に連携しながら、気づいたら社会貢献していたというような、そのような状況ができるといいかなというふうに考えています。","id":"exchange-076"},{"speaker":"松澤委員","kind":"質問・要望","question":"しっかりと連携して、課長のおっしゃる楽しむということは本当に非常に大事だと思っていますので、頑張っていただきたいと思っています。これはとても大変いい取組になると私は思っておりますが、可視化で分かりやすいこのシステムのご見解を説明を求めました。","respondent":"辻オリンピック・パラリンピック準備課長","answer":"正直縦割りといいますか、個別になっていて、なかなかその連携というものはできていない状態かなと考えています。今後そこも、いろいろなボランティアのジャンルが一緒に連携して大きなものをつくるということは、研究していきたいと考えています。","id":"exchange-077"},{"speaker":"横山委員","kind":"提案","question":"１点目に、児童相談所移管推進事業についてお伺いをいたします。私たち会派の提案、要望を受け止めていただいて、私はほかのメンバーとともにとても感動しましてうれしかったですとの意見を述べました。","respondent":"加島児童相談所移管担当課長","answer":"こちらは大きくハード整備とソフト面の体制検討に分かれまして、今後、令和５年１月の竣工を予定しています。ソフト面の体制検討につきましては、現在児童相談所、それから一時保護所の運営面の検討を行っているところです。","id":"exchange-078"},{"speaker":"横山委員","kind":"質問・要望","question":"必要であれば同行支援を行い、今後も引き続き区職員の方々には実行いただきたいということを要望いたしますが、区はどのようにお考えでしょうか。広く区民の方々、感謝をお伝えできるような機会があるといいなというふうに考えておりますけれども、現在の取組と区のご見解をお伺いいたします。","respondent":"山下子ども家庭支援センター長","answer":"子ども家庭支援センターのほうにも連絡が参りまして、一緒に面談をするというようなことも、緊急な場合であっても対応しているところがあります。今後も引き続き、同行支援等を含めまして、丁寧な対応に取り組んでまいりたいと考えています。","id":"exchange-079"},{"speaker":"横山委員","kind":"質問・要望","question":"２点目に、代替職員雇用経費についてお伺いをいたします。代替職員雇用経費について、こちら予算書の内容を簡潔にご説明ください。","respondent":"崎村人事課長","answer":"育児休業を取得することになった職員がいる職場、または業務が一時的に繁忙になった職場に対して、人材派遣を配置するための経費です。今回のコロナの第５波、第６波の感染症対応強化に伴う保健予防課への増員のほかに、約６,０００万円の増額補正をお願いしています。","id":"exchange-080"},{"speaker":"横山委員","kind":"質問・要望","question":"１日でも２日でもいいかなと思うのですけれども、交代でリフレッシュ休暇やチャレンジ休暇を取っていただきたいというふうに要望いたします。休んでほしいというようなお願いだけをしても、より促進してほしいと求めましたが、区のお考えを説明を求めました。","respondent":"崎村人事課長","answer":"令和２年に策定しました特定事業主の行動計画の中でも、充実した区民サービスを実施していくためには、取り組んでいるところです。意義について、休みを取りやすい職場環境の整備に努めるといったところで、年休取得の促進についても引き続き取り組んでいきたいと考えています。","id":"exchange-081"},{"speaker":"おくの委員","kind":"質問・要望","question":"私からは、６１ページ、非核平和都市品川宣言事業に関わって、ウクライナを侵略したロシアに品川区が抗議することを求めて質問いたします。ロシアのプーチン政権に対して強く抗議をし、軍事行動を直ちに中止することを求めるべきだと思いますが、いかがか尋ねました。","respondent":"古巻総務課長","answer":"核兵器廃絶、それから恒久平和確立といったことがうたわれておりまして、状況としては憂慮すべき状況なのかなというふうには認識をしております。","id":"exchange-082"},{"speaker":"おくの委員","kind":"質問・要望","question":"やはりプーチン政権に対して、ウクライナ侵略には強く抗議し、軍事行動を直ちに中止することを求めるべきだと私は思います。もう一度伺います。","respondent":"古巻総務課長","answer":"この非核平和都市品川宣言の趣旨にのっとって区としての取組を進めていくということで、現時点におきましては、そういった形でやっていきたいというふうに考えているところです。","id":"exchange-083"},{"speaker":"おくの委員","kind":"質問","question":"それに加えて、このプーチン大統領の態度、２月２４日に、現代のロシアは今や世界で最も強力な核保有国の１つだと。この点も伺います。","respondent":"古巻総務課長","answer":"状況につきましては、非核平和都市品川宣言の趣旨からすると憂慮すべき状況なのかなというふうには考えております。そういったところから、しっかりと非核平和都市品川宣言への取組が進むようにやっていきたいというふうに考えております。","id":"exchange-084"},{"speaker":"おくの委員","kind":"質問","question":"品川区は、核兵器を使うというロシアに対して、宣言の立場でなぜ抗議をしないのか。宣言にのっとって抗議すべきだと思うのですけれども、いかがか尋ねました。","respondent":"古巻総務課長","answer":"繰り返しになってしまいますけれども、国として専ら取り組むべきことを、国としてしっかり取り組んでいただくということは重要かと思います。","id":"exchange-085"},{"speaker":"おくの委員","kind":"質問・要望","question":"コメントですか、平和的解決の道を探ることを求めます」と、コメントを出しました。この点、伺います。","respondent":"古巻総務課長","answer":"それぞれの自治体において、それぞれの考え方があろうかと思います。品川区におきましては、品川区としてしっかり区の役割を取り組んでいく、そのような形で進めていきたいというふうに考えております。","id":"exchange-086"},{"speaker":"新妻委員","kind":"質問・要望","question":"６５ページ、シルバー大学、７３ページ、すまいるスクール運営費、７５ページ、八潮中央保育園改修工事実施設計委託について伺ってまいります。平成５年よりこの事業が展開をされております、高齢者が人生の生きがいを求め、シルバー大学を設置するとの目的が明記をされています。","respondent":"篠田文化観光課長","answer":"前期が１７講座、それから後期の分が１３講座という形で、こういった形で補正を組ませていただいたものです。令和３年度の実施状況ですけれども、途中の感染状況によっては１回、基本的に設定した講座については全て実施をしているという状況です。","id":"exchange-087"},{"speaker":"新妻委員","kind":"質問・要望","question":"私はこれまで、このシルバー大学の充実を求めて、議会でも質問をしてまいりました。このことについても、この終活がテーマになったことの経緯なども確認をさせていただき、このシルバー大学の充実を求めてきました。","respondent":"篠田文化観光課長","answer":"次年度の予定です。それから昨年度、予算上は、来年度につきましてはそれ以前の状態にできるだけ戻せるような形で実施をしていきたいというふうに考えているところです。","id":"exchange-088"},{"speaker":"新妻委員","kind":"質問・要望","question":"高齢者地域支援課が中心となりまして、これからは高齢者も、このスマホを使える方が多くなることがやはり求められていると思います。スマホの活用などのテーマを設けて、ぜひ開催をしてほしいと求めましたが、見解を伺います。","respondent":"篠田文化観光課長","answer":"そういった講座としての実施につきましても、今のところは取り組んでいないというところは思っています。今後どういった形で取り組めるのかということは研究をしてまいりたいというふうに考えているところです。","id":"exchange-089"},{"speaker":"新妻委員","kind":"質問・要望","question":"課題があったということで、この調査をしていただいたことの課題について、令和４年度にどのように反映をされていくのかをお伺いをいたします。受け入れられる場所があるのかどうかというところ、場所の確保をされているのか、併せてお伺いをいたします。","respondent":"廣田子ども育成課長","answer":"その他、２か所については改築工事の対象となりましたので、改築に向けて要望等を入れながら取り組んでもらおうと思っているところです。一緒に使っていくという、学校等と協力しながらということで、連携を強めるという形で取り組んでいこうと思っているところです。","id":"exchange-090"},{"speaker":"西本委員","kind":"質問","question":"昨年の暮れですか、結局５万円の給付金で決まったわけでありますけれども、結局その後また臨時議会で１０万円一括給付があったのです。すまいるスクールというものは、何のためにあるのか尋ねました。","respondent":"黒田財政課長、廣田子ども育成課長、佐藤企画調整課長","answer":"歳出予算は予算がありませんと執行できませんので、例年、９５％程度であろうということで見込んでいるところです。 すまいるスクールに関しましては、放課後の児童の安全・安心で過ごせる居場所としています。 東京都との連携、関連のところです。各所管においては、各部局との連携を十分深めて、積極的に連携を取っているところです。","id":"exchange-091"},{"speaker":"西本委員","kind":"質問","question":"その後福祉部のほうですか。どのようなことで、いわゆるどのように子育て、いわゆる保育ですから。","respondent":"佐藤企画調整課長、廣田子ども育成課長","answer":"各所管との対応、例えば要望しているというわけではなく、区としてしっかりやっていることをまず伝えているです。今後も引き続き財調協議等もありますので、しっかり区のやっていくことを伝えていきたいと考えています。文化的な、体を動かしたりという活動も盛り込みながら、生活の一部として暮らしていくというようなところの役割があろうかと考えています。","id":"exchange-092"},{"speaker":"西本委員","kind":"質問","question":"今どうなのでしょうか。いかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"今は特別支援のお子さんであるとか、これからは医療的ケア児についても受け入れてまいりますので、ということは認識しています。","id":"exchange-093"},{"speaker":"西本委員","kind":"質問・要望","question":"ただそれというのは、子どもの育ちからするとどうなのだろうか。そのようなことで、やはりあまりに子どもを無視している状況ではないかと思いますが、その辺の考え方はいかがか尋ねました。","respondent":"廣田子ども育成課長","answer":"預けっ放しというような形にならないように、コミュニケーションを取っていくというところは譲らないでいきたいと思っているところです。今後どのような在り方が望ましいかということについては、一定の議論が必要かなというところは思っているところです。","id":"exchange-094"},{"speaker":"小芝委員","kind":"質問","question":"私からは７９ページの収集運搬事業と、８１ページの新型コロナウイルス感染症対応特別助成についてお伺いをいたします。品川区では、現在外国人による、主に定住の外国人によるごみ出しについて、どのような案内、啓発をされておるのか、説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"基本的にはこれを見ていただいて、ごみの出し方を見ていただいて、それに沿って出していただくというような方式を取ってあります。清掃職員のほうが訪ねまして、やはり同様のごみパンフレットを持って説明をして、大体しばらくすれば改善がされているような状況です。","id":"exchange-095"},{"speaker":"小芝委員","kind":"質問","question":"そうなりますと、要は言葉そのものが分からないのか、それともそのパンフレットの意味がなかなかそしゃくできていない、伝わっていないのか。今の所長の答弁を聞いていますと、なかなかその、伝わっていなかったのかなというような認識でよろしいのか尋ねました。","respondent":"品川品川区清掃事務所長","answer":"家族で住んでいるときに、パンフレットを見ていない家族の方がごみ出しをするというようなこともあるかと思います。いろいろなやり取りをすることによって、その外国人のごみの出し方というものは、基本的には改善されている方向であるというふうに考えております。","id":"exchange-096"},{"speaker":"小芝委員","kind":"意見","question":"そのマンションやアパートに、住むところに貼っておくとか、目に見えるところに。そういった取組を事前にやっておくということも１つの手かなとは思いますが、その辺のお考えのほう説明を求めました。","respondent":"品川品川区清掃事務所長","answer":"様々方法は考えられるかと思います。それに全部対応した紙を貼っていくということになると、ただ、これからもいろいろ方法については検討していかなければいけないと思いますし。","id":"exchange-097"},{"speaker":"小芝委員","kind":"質問・要望","question":"当初予算では１,０００件分の見込みをされていましたが、感染を防ぐためのツールに使い道を求めてきたのに対しまして、２年目については。この経緯、理由等を教えてほしいと求めました。","respondent":"遠藤商業・ものづくり課長","answer":"令和２年度と同じ予算で当初出させていただいたのですけれども、見込みを昨年１,４３８件の申請があったのですが、今回補正予算として上程させていただいたようなところです。","id":"exchange-098"},{"speaker":"小芝委員","kind":"質問・要望","question":"先ほど更新された、延期された助成金のほうで、使い道というのは具体的に何か顕著なものがありましたら、ぜひ教えていただきたいのですけれども。","respondent":"遠藤商業・ものづくり課長","answer":"衛生部門のものが非常に多いところではあるのですが、特に１０月、１１月ぐらいに一時収まった時期があったかと思います。そのような部分で、広告宣伝に使われるというところが非常に増えてきたなというふうに感じているところです。","id":"exchange-099"},{"speaker":"小芝委員","kind":"提案","question":"で情報空間の流れている、この点に着目した広告も、新たな時代の流れではないかなと思います。専門スタッフを紹介するような案内を、ホームページ等で掲示することを提案したいと思いますが、ちょっとお考えのほう説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"私どもも昨年度から、いわゆる簡単にホームページで販売ができますよというような、会社と連携したセミナーなどもやらせていただいているところです。引き続きそのような部分の周知なども使いながら、新しい販売方法という部分について周知をさせていただければと考えています。","id":"exchange-100"},{"speaker":"小芝委員","kind":"意見","question":"商店のお店の方々には横のつながりがあるところもありますが、そのような中ではお互いに切磋琢磨して、この助成金にたどり着くこともあると思いますけれども、より多くの個人事業主、店舗の方が等しく機会を得られるよう。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-101"},{"speaker":"渡部委員","kind":"質問","question":"人事のことで少しお伺いしたいということと、産業支援について伺っていきますが、先ほど若林委員の質問だったでしょうか。区の事業計画というものは、どの辺でどのようにこしらえていくのか、ちょっと分かれば説明を求めました。","respondent":"古巻総務課長","answer":"現在の感染症の対策に対しての事業継続計画を少し改訂しなければ駄目かなということで、今検討を始めたといいましょうか、現在の状況に合わせた形での事業継続計画が策定できるような体制は考えていきたいというふうに考えているところです。","id":"exchange-102"},{"speaker":"渡部委員","kind":"質問","question":"様々人事に関わることでお伺いしていきたいなと思ったのですが、１課というのでしょうか、係というのでしょうか。そのようなことがあったのかどうかというのが１点、ちょっと知りたいということと、なければないが一番いいのですけれども。","respondent":"崎村人事課長","answer":"進めてきたところですが、区民との窓口対応、問合せ対応が必要な業務というものはテレワークに不向きな部分がありまして。やはり有効な手段ではあると認識しておりますので、引き続き試行しながら検討して、取り組めるところから進めていきたいと考えております。","id":"exchange-103"},{"speaker":"渡部委員","kind":"質問・要望","question":"現状コロナ禍における対策の中で、先ほどＢＣＰのお話もお伺いしましたけれども、その中で取れる対策を取って続けていただきたいなと思います。その中で第１希望から第３希望まででしょうか、第何希望まででしょうか、任期付対応などで入られている方々がいらっしゃいますよね。","respondent":"崎村人事課長","answer":"ただ、また一定の期間、そういった知識・経験を活用するというような職について採用できるといったものになってまいります。そういったものについては、こういった任期付職員の採用というものを活用しながら、区の職員の育成等々も図っていきたいと考えております。","id":"exchange-104"},{"speaker":"渡部委員","kind":"質問・要望","question":"この２０万円もらえるものというのは非常に評判がよくて、ん、と思うような記載があったのです。会社であれば会社で１回という意味合い、２０万円を超えてもそこが対応になっているかどうなのかというところをちょっと説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"それから、もう１点目の１事業主あたり一遍かというところなのですけれども、基本的には１事業主１回と。そのような形で対応していますので、１という形であれば、１回だけのご利用でお願いしています。","id":"exchange-105"},{"speaker":"渡部委員","kind":"質問・要望","question":"融資あっ旋がずっと品川区はよくて、ほぼほぼこれは無理なのではないかと思うようなところも出てきているのかなというふうに危惧をしています。当然返せないものは貸せないわけですから、案内ができるようになっているのか、そこだけ説明を求めました。","respondent":"遠藤商業・ものづくり課長","answer":"基本的には追加で融資という部分もあるかと考えています。いろいろな方法があろうかと思いますので、そのようなものを活用して、次年度以降も事業者様を全力でサポートするという形で考えているところです。","id":"exchange-106"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、令和３年度補正予算の国民健康保険、後期高齢者医療、そして介護保険について伺いたいと思います。この当初予算の１０億円余から、今回の補正予算のマイナス６億円余を引いた３億９,５４６万９,０００円ということになるのか、伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-107"},{"speaker":"石田（ち）委員","kind":"質問","question":"私からは、令和３年度補正予算の国民健康保険、後期高齢者医療、介護保険について伺いたいのですが、ではまず介護保険から伺いたいと思います。これは深刻な矛盾だと思うのですけれども、区の見解をまず伺いたいと思います。","respondent":"宮尾高齢者福祉課長","answer":"補足給付の見直しにつきましては、今、委員からお話ありましたように、昨年８月１日から基準の見直しが行われたところです。在宅で暮らす方との食費、居住費に係る公平性、それから負担能力に応じた負担を図るという観点だというふうに認識をしています。","id":"exchange-108"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"第２段階で６５０万円以下、第３段階の１つ目が５５０万円以下、２つ目が５００万円以下というふうに引き下げられました。この対象から外れてしまう人が区民で何人ぐらいいるのか、分かれば教えていただきたいのですが。","respondent":"宮尾高齢者福祉課長","answer":"委員からお話のあった第３段階の２つ目に該当している方の人数ですけれども、３月１日時点ですが、５７８人の方がこの段階に該当をしています。","id":"exchange-109"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"どの人も安心して老後を迎えられるように、こうした改悪はやめるべきと、ぜひ国に求めてほしいと求めました。令和３年度の区の法定外繰入れというものは、この当初予算から今回の補正予算のマイナスを引いたものになるのかということを確認したいと思います。","respondent":"池田国保医療年金課長","answer":"法定外繰入金につきましては、今回の補正で３億９,０００万円ということでお願いするところです。その繰越金を多く使ったがために、いろいろなところに使いまして、法定外繰入金のほうを補正で減額させていただいたものです。","id":"exchange-110"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"加入者の７割、８割が低所得者層、それなのにほかの協会けんぽなどの保険と比べても一番高い保険料が国保です。引下げこそすべきですし、そのための税金投入をしてほしいと求めましたけれども、いかがか尋ねました。","respondent":"池田国保医療年金課長","answer":"コロナ関連ということで激変緩和率を９６％ということに抑えまして、１％を一般財源から入れるというような形でやっておりまして、毎年多くの金額をつぎ込んでいるところです。","id":"exchange-111"},{"speaker":"石田（ち）委員","kind":"質問","question":"さらに令和元年度には、平成２８年度に４,２００円だった保険料が令和元年度には４万３,０００円と、１０倍に値上げをされているわけです。令和３年度で終了されたというところですけれども、これに対して、値上げに対しては区としてどう対応されたのか伺いたいと思います。","respondent":"池田国保医療年金課長","answer":"令和２年度、３年度の保険料についてのことだと思いますが、これについて従っていくことは致し方ないということは考えております。それから全国市長会のほうに向かって、区長会を通じて、低所得者の生活を守るというような要望はずっと出しています。","id":"exchange-112"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"区長会などで要望していくということなのですが、今回のこの令和３年度で、区が軽減のために負担したものというのはあるのでしょうか。分かれば教えてほしいと求めました。","respondent":"池田国保医療年金課長","answer":"令和４年、令和５年の保険料についても、各自治体のほうで負担をするということでやらせていただいているところです。","id":"exchange-113"},{"speaker":"石田（ち）委員","kind":"質問","question":"今伺ったのは、今課長が答弁されたのは、いつも入れている、入れなければならない軽減対策のお金です。これだけ３倍にも値上がってしまう、そのような状況に対して、軽減のために入れた額はあるのかということをお聞きしたのです。","respondent":"池田国保医療年金課長","answer":"ですから今私がお話ししたものについては、軽減のために一般財源のほうでずっと入れさせていただいているです。","id":"exchange-114"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"法定外繰入れは、マイナスするのではなく、さらなる投入を求めたいと思います。第３号議案、第４号議案、介護保険に反対の態度を表明して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-115"},{"speaker":"たけうち委員","kind":"質問・要望","question":"９８ページの子育て世帯臨時特別給付金について、この２,０００万円の内容について教えていただきたいということと、今の進捗状況というか。それから９９ページのほうは、２月下旬から相談を開始されるというふうに聞いていますけれども、そうした状況について説明を求めました。","respondent":"伊東子育て応援課長","answer":"昨年１１月ぐらいからお話があって、その後いろいろな変更がありまして、３万３４９名分を１２月２８日に支給したというような状況になってあります。その後２月１８日、そして２月２８日ということで、支給をしたところです。","id":"exchange-116"},{"speaker":"たけうち委員","kind":"質問・要望","question":"区でも児童手当、難しいと思いますが、今所得制限についてどのようなお考えを区としてお持ちなのかということを教えてほしいと求めました。見込みでは４,０００世帯分ぐらいの見込みを出しておりますけれども、周知が足りているのかどうか、どのような評価を今されているか説明を求めました。","respondent":"佐藤企画調整課長、櫻木生活支援臨時給付金担当課長","answer":"限られた財源の中で、全ての方へ支援をするのは難しいこともありますので、福祉や安全確保の観点から、一定の所得基準は必要と考えております。社会保障に関わる所得制限について検討しているというところも把握しておりますので… ４,０００世帯というものは、ある意味都のほうから来た、一方で生活にお困りの方にこの制度を周知していくことはとても大切なことだと考えています。","id":"exchange-117"},{"speaker":"たけうち委員","kind":"質問・要望","question":"お聞きする中で、周知のほうもしっかり取り組んでいただきたいと、これは要望とします。要望として終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-118"},{"speaker":"高橋（し）委員","kind":"質問","question":"もう一つ、ちょっと順不同ですが、５５ページの繰入金についてお尋ねします。この条文が、つまり寄附金について含んだというところは、何かお考えがあってのことか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"その中の基金の目的のために寄附された寄附金の額、こちらにつきましては、区民の方から実際に既に申し出がございました。ということで、これを区民の方からのご意向に沿った形での寄附という形で使いたいということで、こちらに載せさせていただいたものです。","id":"exchange-119"},{"speaker":"高橋（し）委員","kind":"質問","question":"この基金をこの条例の中にそれが入れることの可能な項目、つまり寄附、それを目的とした寄附が入るような文言を入れたということですね。あるいは幾つかのというようなことですから、ごめんなさい、事実として申し出があるということでよろしいか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"実際に申し出がございました。まだ１件ですが、今後増えていくことが想定されますので、活用させていただければと思います。","id":"exchange-120"},{"speaker":"高橋（し）委員","kind":"質問","question":"想定としては４００億円かかるというような想定が出ています。総務委員会の資料だと１２０億円ということなのですが、残りの２８０億円の財源はどのように調達するという、現時点で想定をされているのか尋ねました。","respondent":"黒田財政課長","answer":"総務委員会のほうでも１２０億円というようにお答えさせていただきまして、基本的に庁舎ですので、起債を検討しております。その庁舎の中で、その分担金というところも発生しようかというふうに考えられますが、そういったところも財源として考えられるです。","id":"exchange-121"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"起債ができる部分、そしてできない部分、そして基金、それから、先ほどあった国なり都からの分担金ということですが、そのできる部分という話で、具体的にはどのような起債が想定され、それが起債可能という見込み、そちらをご説明いただきたいのですが。","respondent":"黒田財政課長","answer":"いわゆる一般事業債での起債を検討しておりまして、これは制度で決まっておりますので、２５％部分は起債できないというところで資金が必要です。","id":"exchange-122"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、これまで地方交付税の措置、財調の都市計画交付金などによる財源の裏づけがある起債を、品川区ではずっと行われてきたと伺っています。そちらの見込みも伺いたいのですが、いかがか尋ねました。","respondent":"黒田財政課長","answer":"例えば特別交付金の対象になるところがないかというようなところもありますので、そういったところは今後の財調協議の中で、また都と協議をしていきたいというふうに考えてあります。","id":"exchange-123"},{"speaker":"高橋（し）委員","kind":"提案","question":"一般質問のほうで、基金の制定というか、条例の制定をご提案して、ここで今審議されているという基金条例については、大変ありがたいと思います。この５億円と３０億円、２５億円の差があるのですけれども、これはどのような経緯なのか尋ねました。","respondent":"黒田財政課長","answer":"一応建設の計画がまだ、令和６年度までに１２０億円を計画的に積み立てるという中では、毎年度３０億円ほどの積立てが必要になってまいります。","id":"exchange-124"},{"speaker":"高橋（し）委員","kind":"質問","question":"それなら、どうして総務委員会のほうに３０億円ずつ積み立てて１２０億円というふうに数字をしっかりと書いてあるのかということです。ということは、補正予算をあらかじめ想定して当初予算を立てるということは、まずないということだと思うのですが、その点についていかがか尋ねました。","respondent":"黒田財政課長","answer":"必ずというわけではありませんけれども、他の基金についても行ってきてまいりますので、対応を取ってまいりたいというふうに考えてあります。","id":"exchange-125"},{"speaker":"高橋（し）委員","kind":"質問","question":"別の機会にお伺いします。最後に、先ほど床の話が出ましたが、総合庁舎の持分割合、国と都についての協議は、どのように現状は進んでいるのか尋ねました。","respondent":"東野庁舎計画担当課長","answer":"現状、国、都との協議のほうを進めているところです。両方で２３％をお持ちということになりますので、そういったものを含めまして、協議を続けているところです。","id":"exchange-126"},{"speaker":"高橋（し）委員","kind":"質問","question":"別の機会に伺いたいと思います。ありがとうございました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-127"},{"speaker":"湯澤委員","kind":"質問","question":"そして平均年齢、ここ数年の推移と、コロナ禍での活動についてどうであったかをお知らせください。公園や区道への緑化や整備に対する区の考えを説明を求めました。","respondent":"高梨公園課長","answer":"人数といたしましては、約１,２５０人ほどの方が各団体に所属されて、登録をしていただいているです。緑化に対する意識を向上をさせる、していくということで、今後も積極的に取り組んでまいりたいというふうに考えているところです。","id":"exchange-128"},{"speaker":"湯澤委員","kind":"質問・要望","question":"現在はご高齢の方が多いと伺っておりますけれども、若者からお年寄り、品川区の緑と花を増やしていく取組をしてはいかがかと思います。課題といったものがあれば教えていただきたいので、課題の３点、お知らせください。","respondent":"高梨公園課長","answer":"平均年齢といったところですけれども、日々ボランティア団体の方と接する中で、やはりかなり高齢の方が多いというような認識を持っているところです。","id":"exchange-129"},{"speaker":"湯澤委員","kind":"質問・要望","question":"こちらも公園や区道のお話と同様になるのですけれども、ぜひ屋上緑化などを含みまして、緑化事業に取り組んでいただきたいとは思っております。ぜひ拡充してほしいと求めましたが、これまでの取組と、今後拡充をどのように図っていくかをお知らせほしいと求めました。","respondent":"有馬庶務課長","answer":"学校における屋上緑化の関係ですけれども、平成１４年以降１０年ぐらいかけて、一旦は屋上緑化に取り組んでおります。太陽光パネルの設置とともに屋上緑化を進めているということですので、校庭の中でも菜園、併せて推進していきたいというふうに考えております。","id":"exchange-130"},{"speaker":"湯澤委員","kind":"質問・要望","question":"本区では世界平和を願って、しながわ平和の花壇事業として、公立学校１５校と駅前３か所で花壇の活動を行っていると認識しております。区内全校や区内の各駅前、そういったところにできる限り取り組んでいただきたいなと思いますが、お考えをお知らせください。","respondent":"古巻総務課長","answer":"平和の花壇ですけれども、こちら平成２７年度からの４か年計画で、区内の中学校を中心に花壇を作らせていただいているところです。","id":"exchange-131"},{"speaker":"湯澤委員","kind":"質問・要望","question":"こういったところの民間の力なども借りながら、知恵を出し合って、緑と笑顔あふれる平和都市品川を目指していってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-132"},{"speaker":"大倉委員","kind":"質問・要望","question":"７８ページ、清掃費から、コロナ禍のごみ収集に関連して伺わせてほしいと求めました。今ちょっとホームページを見た限りでは載っていませんでしたが、そういったところについても、どのように対応されているのかお知らせください。","respondent":"品川品川区清掃事務所長","answer":"ただひたすらお風呂に入るというような対応も取ってあります。コロナにつきましても極力そのような形で、薬局等で回収をしていただくというような形で、啓発のほうを進めているところです。","id":"exchange-133"},{"speaker":"大倉委員","kind":"質問","question":"区民も、そうした中ではしっかりごみの出し方を丁寧にしていって、感染防止に努めていくということも重要かなと思っています。どのようにお考えでしょうかということと、質問をさせていただいて、何かこの手紙を活用して周知が行われたのかどうかも併せてお知らせください。","respondent":"品川品川区清掃事務所長","answer":"基本的な注射針と同じ対応ということで、コロナであろうがなかろうがというところで、とにかく注射針ということでの啓発は続けております。先ほど、こういったものを周知活動にうまく活用できないかというところも今後検討していきたいと、このように考えております。","id":"exchange-134"},{"speaker":"大倉委員","kind":"質問・要望","question":"そういうものも活用しながら、区民の人たちが、このような活動もあって私たちもしっかり取り組んでいかなければと思ってほしいと求めました。その中で、例えばケーブルテレビ等も含めたＬ字の、あのようなところに流す等も含めて、検討してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-135"},{"speaker":"須貝委員","kind":"質問","question":"私は補正全般から質問します。先ほどおくの委員からもありましたが……。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-136"},{"speaker":"須貝委員","kind":"意見","question":"そしてロシアに、やはりきちんと品川区として、自治体として訴えるべきではありませんか。お答えくださいとの意見を述べました。","respondent":"古巻総務課長","answer":"非核平和都市品川宣言を宣言したということで、核兵器の廃絶と恒久平和の確立というものが、品川区の平和宣言の趣旨ではあります。なので、国が専ら取り組むべき事柄ということで捉えておりますので、品川区としての取組を続けていきたいというふうに考えております。","id":"exchange-137"},{"speaker":"須貝委員","kind":"質問","question":"これいったい皆さんどう思うのですか。それから高齢者、障害者を抱える福祉部、それから健康課はどうなのか尋ねました。","respondent":"古巻総務課長","answer":"繰り返しになりますけれども、非核平和都市品川宣言、こちらは品川区として、核兵器の廃絶と恒久平和の願いを込めて宣言をつくったものですので、品川区といたしまして、しっかりと非核平和都市の取組を続けてまいりたいというふうに考えております。","id":"exchange-138"},{"speaker":"須貝委員","kind":"質問","question":"人権問題だ、虐待だ、いじめだ、ところがこのようなときは黙ってしまうのですか。そのような姿勢なのか尋ねました。","respondent":"古巻総務課長","answer":"決して黙っているというわけではございません。非核平和都市品川宣言の趣旨にのっとりまして、品川区としてしっかりと平和の事業を進めてまいりたいというふうに考えております。","id":"exchange-139"},{"speaker":"須貝委員","kind":"質問","question":"そのような状況に置かれているということは、私は区としてしっかりアピールすべきだと思うし、そのようにしなければいけないのではないですか。やはり体が不自由になったり、そして認知症になったりして、かえって品川区の負担も増えるのではないか尋ねました。","respondent":"宮尾高齢者福祉課長","answer":"ご本人、それからご家族の思いを尊重するということは、これはやはり視点としては大事なことかと考えています。そういったことは特段、区としてもなかなか難しいところがありますので、それはコロナ前からの基準に沿って運用させていただいているです。","id":"exchange-140"},{"speaker":"須貝委員","kind":"質問","question":"やはりそのような工夫というものはあってしかるべきだと思うのですけれども、そのようなものはあったのですか。すみません、もう１回、答えるよう求めました。","respondent":"宮尾高齢者福祉課長","answer":"ではご家族なり、そういったこともきちんとご本人のご要望とご本人の状態像をしっかり把握して、対応させていただいているというところがあります。何でもかんでも、例えば感染が怖いからサービスを止めるとか、そのようなことにはつながっていないというふうに認識をしています。","id":"exchange-141"},{"speaker":"須貝委員","kind":"質問","question":"それを何度も私はずっと言っていたのだけれども、何かできる仕組みというものは考えられないのでしょうか。何年続くか分からないですけど、もっともっと具合の悪い方、出てきてしまうのではないか尋ねました。","respondent":"菅野高齢者地域支援課長","answer":"そういったものを感染症対策を講じて実施しておりますので、そちらのカラオケ店と協定をしている、利用されている方が実績としては出ております。やはり１月以降、もう少し世の中の状況等を考えながら、どのように開始していくべきかというところを考えているところです。","id":"exchange-142"},{"speaker":"須貝委員","kind":"質問","question":"ゆうゆうプラザは確かに個室ですから、あそこはちょっとまた難しいところもあるかもしれません。私は何とか、すみません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-143"},{"speaker":"中塚委員","kind":"質問","question":"６３ページ、庁舎整備基金積立金について伺いたいと思います。そこで、現在の状況とはどのような状況を指しているのか、憂慮すべき事態とはどのような事態を指しているのか、伺いたいと思います。","respondent":"古巻総務課長","answer":"今現在起こっております、ウクライナに対するロシアの侵攻に対して、様々な動きが世界で広がっている状況です。非核平和都市品川宣言の趣旨から照らすと、なかなか何というのですか、憂慮すべき状況なのかなというふうに考えているところです。","id":"exchange-144"},{"speaker":"中塚委員","kind":"確認","question":"確認したいのですけれども、ロシアによるウクライナへの侵攻に憂慮を示しているということでよいのか、確認させてください。","respondent":"古巻総務課長","answer":"特定のというよりは、戦争につながりかねないような状況が生じていることに対しては憂慮しているということで考えております。","id":"exchange-145"},{"speaker":"中塚委員","kind":"質問","question":"つながりかねないというのは、どのような状況につながりかねないことを憂慮しているのか尋ねました。","respondent":"古巻総務課長","answer":"言葉はなかなか難しいと思いますけれども、報道等から推測いたしますと、なかなか、何というのでしょうか、平和的な外交的な解決というよりは、少しこう激しい、何か動きがあるということに対しては、憂慮すべきかなというふうに考えているところです。","id":"exchange-146"},{"speaker":"中塚委員","kind":"質問","question":"それに対して品川区は抗議すべきだというふうに、先ほどから指摘が繰り返されているのだと思います。最後に、この激しい動きとは、つまりは戦争を指すことだということでよろしいのか尋ねました。","respondent":"古巻総務課長","answer":"何をもって戦争というふうに定義づけるかということはなかなか難しいところはあるのかなと思いますけれども、いわゆる平和的なというか、話合いによるということではないという意味では、少し強い行動なのかなというふうに考えているところです。","id":"exchange-147"},{"speaker":"中塚委員","kind":"質問・要望","question":"ロシアによるウクライナ侵略はやめなさいと、区は態度を示すべきだと強く求めて、当初の質問に入りたいと思います。３０億円もの庁舎の積立金について、改めてどこからかき集めたものなのか、財源を伺いたいと思います。","respondent":"黒田財政課長","answer":"予定していたところができないことの一般財源というところと、庁舎整備基金だけではありませんので、補正予算を編成しています。","id":"exchange-148"},{"speaker":"中塚委員","kind":"質問","question":"減額補正も含めての財源ということですけれども、このコロナ禍で区民生活が厳しいときに、品川区の財政状況は随分余裕がある。その余裕分で３０億円もの庁舎基金を組み立てているということでよろしいのか尋ねました。","respondent":"黒田財政課長","answer":"東京都のほうの歳入見込みのところで、かなり企業業績が当初の見込みよりも堅調であったということで、令和２年中。そういったところもいろいろなところを勘案して見込みより増えたですので、余裕があるというところではないというふうに認識しています。","id":"exchange-149"},{"speaker":"中塚委員","kind":"質問","question":"こうした財源は、コロナで苦しい生活をされている方への支援にこそ充てるべきだと思います。つまりはまた令和４年度の最終補正で余裕分があるから、最終補正で３０億円に増やすという考えをもう既に見通しているのかどうか伺いたいと思います。","respondent":"黒田財政課長","answer":"基本構想で４００億円ほど整備費用を見込んでいるですので、令和７年度からの整備を計画しておりますので、それは計画的に基金を積み立てていくです。そういった中では、歳入等の状況を見まして、積立てをしていきたいというふうに考えてあります。","id":"exchange-150"},{"speaker":"中塚委員","kind":"質問","question":"ほかの基金を見ても、財政調整基金積立金は５６億円、公共施設整備基金積立金は４０億円ですから、合わせると補正で１２６億円も積み増します。第３３号議案ですが、また補償など、抜本的に強める必要があることを指摘して賛成したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-151"},{"speaker":"大沢委員","kind":"質問・要望","question":"質問に入らせていただきます。どのような予算編成だったのか感想をいただきたいということと、この予算編成、どのように各課に指示をされたのか説明を求めました。","respondent":"黒田財政課長","answer":"見込みよりは落ち込みが少なかったというところと、企業業績が当初の都の見込みよりも堅調だというところで、ちょっと裏腹な関係にありますが。３月までの執行見込みをしっかり立てていただきまして、歳入、歳出ともに予算編成に当たったです。","id":"exchange-152"},{"speaker":"大沢委員","kind":"質問・要望","question":"ちょっと後で質問させていただきたいのですが、やはり各課において不要であったり、実績が上がらない事業というものを抱えていると思うのです。より効果的な事業に流れを持っていくということは大事だと思うのですけれども、そこのところ、どのようにお考えになるのか説明を求めました。","respondent":"黒田財政課長","answer":"今回審議いただいているのは、いわゆる最終補正の追加分ということになりますので、年度末までの執行を見込んだ予算です。商品券の増額発行、あとキャッシュレス決済のプレミアムの対応など様々、これは令和３年度を通じて対応を取ってきたというようなところです。","id":"exchange-153"},{"speaker":"大沢委員","kind":"質問・要望","question":"この問いを続けさせてほしいと求めましたけれども、この不用額の処理については、依命通達の不用額の処理という項目があります。この考え方に基づいて今回は手続が行われたとは思うのですけれども、そこのところの感想なり、お考えを伺いたいと思います。","respondent":"黒田財政課長","answer":"ただいまご指摘いただいたとおり、補正予算につきましては執行見込みを３月まで立てて、結局減額補正になると。その余裕の部分についてはその後の決算対応になるということになりますので、この予算編成につきましては、その依命通達に基づいて編成している。","id":"exchange-154"},{"speaker":"大沢委員","kind":"質問","question":"どのようにマイナスの補正をより補正幅、マイナス幅を縮めるような対応という考え方も必要だと思うのですが、その辺りについての考え方の用意はされているのか説明を求めました。","respondent":"黒田財政課長","answer":"予算でありますので、経費の中でその対面のところで、本日のご指摘の中でもありました。例えば、執行方法を工夫する中で対応できるものがあれば、各所管のほうで対応しているような状況です。","id":"exchange-155"},{"speaker":"大沢委員","kind":"質問","question":"オンライン、これは何でしょうか、オンライン型、いわゆるデジタル型の周知方法と、また、あるいは活字型の周知方法と２つあると思うのです。オンラインはすぐに受け止められるけれども、そこは一工夫をお願いしたいと考えていますが、そこのところをいかがお考えになりますか尋ねました。","respondent":"黒田財政課長","answer":"やはり全てがオンラインで対応できるということではないと思いますので、その事業の趣旨によって、様々効果が得られるような方法を各所管のほうでも模索しながら実施しておりますので、そういった形で進めてまいりたいというふうに考えてあります。","id":"exchange-156"},{"speaker":"大沢委員","kind":"質問・要望","question":"あるいはそこから何というのですか、その後どうなったのですかということを私は知りたいのですけれども、そこのところについての考え方を聞きたい。お願いします。","respondent":"多並都市開発課長","answer":"区としてもその中で、支援する中で情報をいただきながら進めているというところですので、そこは密にしながらやっているところです。やはり、区としてもやはりそこはよく連携しながら進めるべきということで、今後もそのように進めていきたいと思っているところです。","id":"exchange-157"},{"speaker":"大沢委員","kind":"質問・要望","question":"やはり何々と報告を受けています、聞いておりますというものはなかなか理解しづらい表現ですので、そこのところを一工夫して、分かりやすいような説明をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-158"},{"speaker":"塚本委員","kind":"質問","question":"最初に７５ページの区内私立保育園経費から、それから、次に６１ページの情報システム運営費について伺いたいと思います。現状のこのコロナ第６波における、区の、主に私立保育園における休園状況、現状今どのような状況になっているのか説明を求めました。","respondent":"若生保育支援課長","answer":"方針等はお示ししておらず、そういったところの情報をきめ細かく保健所と連携しまして、状況に応じて休園のほう判断しています。それから、第６波での休園の状況ですけれども、現在のところまで、私立保育園７園ほど休園がありますが、現在休園を判断しているところは１園です。","id":"exchange-159"},{"speaker":"塚本委員","kind":"確認","question":"ちょっと１点、自粛をお願いしていると、このような園もあるかと思います。この私立保育園側からの情報提供、周知、こういったことはどの程度なされているのか確認させてください。","respondent":"若生保育支援課長","answer":"委員ご案内の小学校休業等対応助成金等の周知に関しての問合せです。これ令和２年度に実施していて、８月から１２月末までの期間でまた再開しましたということなので、国のほうから都を通じて来てあります。","id":"exchange-160"},{"speaker":"塚本委員","kind":"質問","question":"システムの、令和７年度末までに統一していくというような話ですけれども、今回この公正取引委員会の報告書で指摘されたということがありました。このシステムの委託費の中身がどうなのだという話は、この囲い込みと言われるような状況について、今どのような認識なのかお伺いします。","respondent":"宮澤情報推進課長","answer":"システムの変更が困難になるというような状況ですけれども、調達する際にはプロポーザル等で業者を選定すると。それで定期的、目安は約５年として、見直しをかけていくという形を取ってあります。","id":"exchange-161"},{"speaker":"塚本委員","kind":"質問","question":"本当にこれは必要なお金なのか、業者側からするとというか、なかなかそのシステムの中身を知らない人間からすると判断が難しい。３割ほどのコスト減を目指すというようなことも示されておりますけれども、私としては期待をしたいところですが、区としていかがか尋ねました。","respondent":"宮澤情報推進課長","answer":"様々なベンダーがシステムを提供する際に、システムの変更というものが調達の際にしやすくなってくるということは考えられます。そのようなところで競争原理等が働きまして、システムの調達に関するコストというものも削減できてくると見込んでいるところです。","id":"exchange-162"},{"speaker":"塚本委員","kind":"意見","question":"令和７年度末ということを１つのお尻にして、今進めておられるわけですが、しっかりこれを進めていっていただけるようにお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-163"},{"speaker":"石田（秀）委員","kind":"質問","question":"令和３年度の見込みの基金残高というものも出している特別区のところもあったけれども、執行率がこれから大体９５％程度ということになると思います。例えば令和３年度の基金残高の予想額というのはどれぐらいになるのか、大体そのようなことでいいのかどうかというところから、お答えをお願いします。","respondent":"黒田財政課長","answer":"財調のほうも７１億円余の再調整というところは、財調基金とか、庁舎整備基金のほうの積立ての原資としているというところはご指摘のとおりです。基金残高の見込みですが、最終補正予算の中では基金残高を見込んでおりまして、これから判断が必要かと思ってあります。","id":"exchange-164"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それはどうして、ハードとソフトの話をしますけれども、まずハードのことだけを言うと、今特養もいろいろ計画は出てきました。ですから、その辺の感覚を教えていただきたいということと、併せて説明を求めました。","respondent":"黒田財政課長","answer":"ただ、いわゆる将来の施設整備も含めた基金を年度の予算を編成する中で考えながら、今後も進めてまいりたいというふうに考えてあります。人員として、令和４年度には改めて財調協議も行うということになっておりますので、引き続き協議してまいりたいというふうに考えてあります。","id":"exchange-165"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"私は来年度の１年に求められているのだろうと思っていまして、それを増やしていくとか、中小企業なら借換えの枠を増やしていくのだと。このように臨機応変にそのような政策を打つ準備をしていただきたいと考えていますので、ぜひそれについての意気込みを聞かせていただきたい。","respondent":"黒田財政課長","answer":"やはり、小さい経費で大きな効果が得られるようにというところは、これは今後も取り組んでいかなければならないというふうに考えてあります。今年度実施計画も策定いたしまして、これからまたその実施計画の実行、施策を進めてまいりたいというふうに考えてあります。","id":"exchange-166"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201716?Template=document&Id=1144#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=3&TermStart=2022-01-01&TermEnd=2022-12-31"}],"sourceMeta":{"pages":0,"characters":129952,"voices":392}}]);
